#Requires -Version 5.1
[CmdletBinding()]
param()

# ============================================================================
#  TOOL NAME  -  change this ONE value to rename the whole application.
#  It drives the window title, the header, the footer, every popup/report
#  title, exported file names, etc. Nothing else needs to be edited to rename.
# ============================================================================
$script:AppName = 'Foreman'
# Short descriptor shown after the name in the footer AND in the header badge -
# change it once here and it updates in both places.
$script:AppTagline = 'OneLink Remote Administration'

# ============================================================================
#  OneLink Administration Tool
#  ---------------------------------------------------------------------------
#  SELF-CONTAINED / STANDALONE build with MULTI-SERVER support.
#
#  Everything that used to live in external files is embedded directly in this
#  single script:
#     - All PowerShell modules (ConfigManager, Logger, SshManager,
#       NMenuAutomation, PackageManager, OneLinkOperations)
#     - The WPF XAML user interface (was UI\MainWindow.xaml)
#     - The default JSON configuration (was Config\Settings.json and
#       Config\NMenuMappings.json)
#
#  Nothing is loaded from Modules\, UI\ or Config\ anymore.
#
#  Multi-server model:
#     - Build a list of target servers in a grid (Host + Port per row).
#     - "Same SSH credentials for all servers" -> enter one username/password.
#       Uncheck it to give every server its own username/password.
#     - "Connect All" opens an SSH session to every server in the list.
#     - Every operation has a "Target server" selector: run on ALL connected
#       servers or a single chosen server. When running on all servers a
#       failure on one server does not stop the rest; a per-server summary is
#       shown at the end.
#
#  The ONLY thing created/used beside the EXE at runtime is the Logs folder.
#  Optionally, an external "Settings.json" and/or "NMenuMappings.json" placed
#  next to the EXE overrides the embedded defaults.
#
#  Runtime requirement on the target machine: the Posh-SSH PowerShell module.
# ============================================================================

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

if ($PSVersionTable.PSEdition -eq 'Core' -and -not $IsWindows) {
    throw "This WPF application must be run on Windows."
}

# Many customer machines default to a Restricted execution policy, which blocks
# loading module script files such as Posh-SSH.psm1 ("running scripts is
# disabled on this system"). Relax the policy for THIS PROCESS ONLY - it needs
# no admin rights and writes nothing to the machine (nothing persists after the
# app closes) - so dependent modules can be imported. Wrapped in try/catch
# because a Group Policy that pins the Machine/User scope cannot be overridden
# by a process-scope change; in that case the connection step surfaces a clear
# error instead of the app failing to start.
try {
    Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass -Force -ErrorAction Stop
}
catch {
    # Intentionally ignored.
}

# ============================================================================
#  EMBEDDED DEPENDENCY: Posh-SSH
#  ---------------------------------------------------------------------------
#  The Posh-SSH module (a .psm1 plus its SSH.NET DLLs) is embedded below as a
#  base64-encoded zip so the tool is a genuine single-file EXE. On first run,
#  if the machine does not already have Posh-SSH installed, the zip is extracted
#  to a per-user folder (%LOCALAPPDATA%\OneLinkAdminTool\Modules) and made
#  importable. Nothing is written system-wide and no admin rights are needed.
# ============================================================================
$script:PoshSshEmbeddedVersion = '3.2.3'
$script:PoshSshZipBase64 = @'

'@

function Initialize-EmbeddedPoshSsh {
    [CmdletBinding()]
    param()

    # Prefer a Posh-SSH already available on the machine.
    if (Get-Module -ListAvailable -Name Posh-SSH -ErrorAction SilentlyContinue) { return }

    if ([string]::IsNullOrWhiteSpace($script:PoshSshZipBase64) -or
        $script:PoshSshZipBase64.Trim().Length -lt 100000) {
        throw "Posh-SSH is not installed on this machine and no embedded copy was compiled into this build."
    }

    $modulesRoot = Join-Path $env:LOCALAPPDATA 'OneLinkAdminTool\Modules'
    $moduleDir   = Join-Path $modulesRoot ("Posh-SSH\" + $script:PoshSshEmbeddedVersion)
    $manifest    = Join-Path $moduleDir 'Posh-SSH.psd1'

    if (-not (Test-Path -LiteralPath $manifest)) {
        if (Test-Path -LiteralPath $moduleDir) {
            Remove-Item -LiteralPath $moduleDir -Recurse -Force -ErrorAction SilentlyContinue
        }
        New-Item -ItemType Directory -Force -Path $moduleDir | Out-Null

        $tempZip = Join-Path $env:TEMP ("PoshSSH_" + [Guid]::NewGuid().ToString('N') + ".zip")
        try {
            [IO.File]::WriteAllBytes($tempZip, [Convert]::FromBase64String($script:PoshSshZipBase64.Trim()))
            Add-Type -AssemblyName System.IO.Compression.FileSystem
            [System.IO.Compression.ZipFile]::ExtractToDirectory($tempZip, $moduleDir)
        }
        finally {
            if (Test-Path -LiteralPath $tempZip) {
                Remove-Item -LiteralPath $tempZip -Force -ErrorAction SilentlyContinue
            }
        }
    }

    # Make 'Import-Module Posh-SSH' resolve to the extracted copy.
    if (($env:PSModulePath -split ';') -notcontains $modulesRoot) {
        $env:PSModulePath = $modulesRoot + ';' + $env:PSModulePath
    }
}

# Ensure Posh-SSH is loaded (from the machine, or the embedded copy).
function Import-OneLinkPoshSsh {
    [CmdletBinding()]
    param()

    if (-not (Get-Module -Name Posh-SSH)) {
        Initialize-EmbeddedPoshSsh
        Import-Module Posh-SSH -ErrorAction Stop
    }
}

Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName System.Windows.Forms
# Loaded unconditionally so the .xlsx config engine's ZipArchive / ZipArchiveMode
# (System.IO.Compression) and ZipFile (…FileSystem) always resolve - not just when
# the embedded Posh-SSH is being extracted. Both ship with .NET Framework 4.5+ (no
# new dependency); this only makes the types available in the session.
Add-Type -AssemblyName System.IO.Compression -ErrorAction SilentlyContinue
Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction SilentlyContinue

# ============================================================================
#  Server row model + role marks
# ============================================================================
#  The six fixed roles a VM (IP) can be marked with. A single IP may carry more
#  than one role (e.g. AppServer + Concentrator on the same host).
#  'Auxiliary Service' is for NON-OneLink packages/apps (nginx, postgresql, a
#  custom rpm/deb, etc.): installed like any package but with NO SSL step, and its
#  systemd unit(s) are AUTO-DISCOVERED (not a fixed onelink-* name) so they can be
#  started/restarted/stopped via plain systemctl. It never touches the OneLink role
#  logic (RoleServiceMap / RolePackageName / SSL) - it is simply absent from those.
$script:OlRoles = @('AppServer','Concentrator','ReportServer','nConnect','WebEvents','Database master','Database slave','Auxiliary Service')

# Maps a role mark to the systemd service that role runs. Used by the Services
# tab so restart/stop/status act on the services an IP is marked for (the
# package for AppServer is 'onelink' but its service is 'onelink-appserver').
# Database roles have no OneLink service and are intentionally omitted.
$script:RoleServiceMap = [ordered]@{
    'AppServer'    = 'onelink-appserver'
    'Concentrator' = 'onelink-concentrator'
    'ReportServer' = 'onelink-report-server'
    'nConnect'     = 'onelink-nconnect'
    'WebEvents'    = 'onelink-webevents'
}

# One editable row in the Server grid. A real class (not a PSCustomObject) so
# WPF two-way binding on IP/Port/Username writes back reliably. Status/Roles/
# password-display change programmatically and are refreshed via Items.Refresh().
class OlServer {
    [string]$Host = ''
    [int]$Port = 22
    [string]$Username = ''
    [string]$Roles = ''
    [string]$RolesDisplay = 'Select...'
    [string]$PasswordDisplay = 'Set...'
    [string]$Status = 'Not connected'
    [string]$ServicesDisplay = '-'
    [string]$Os = ''
    [object]$SecurePassword = $null
    [object]$Session = $null
    [object]$Credential = $null
    [object]$Services = $null
    [object]$AuxServices = $null   # discovered non-OneLink systemd units (Auxiliary Service role); $null = not yet discovered
    [string]$Health = 'View'       # resource health: View (unknown) / OK / CAUTION / CRITICAL - drives the Resources button colour (via DataTriggers)
    [string]$HealthNote = ''       # short summary e.g. "Disk /var 88% - Mem 72%"

    OlServer() {
        $this.Services = New-Object System.Collections.Generic.List[object]
    }

    # Roles as an array (splits the comma-separated display string).
    [string[]] RoleList() {
        if ([string]::IsNullOrWhiteSpace($this.Roles)) { return @() }
        return @($this.Roles -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' })
    }

    [bool] HasRole([string]$role) {
        return ($this.RoleList() -contains $role)
    }
}

# One recorded activity (a completed user task): how many clicks/fields it took
# and how long, for the Activity Metrics tab. Plain class so WPF binding is clean.
class OlActivityMetric {
    [string]$Time = ''
    [string]$Activity = ''
    [string]$Target = ''
    [string]$Outcome = ''
    [int]$Clicks = 0
    [int]$Inputs = 0
    [double]$ActivitySeconds = 0
    [double]$OperationSeconds = 0
}

# One row in the Package deployment plan: which package goes to which server
# for a given role. Package is editable in the grid (a dropdown of Available).
class OlPlanRow {
    [string]$Host = ''
    [string]$Role = ''
    [string]$Package = ''
    [string]$Size = ''
    [string]$Status = 'Planned'
    [object]$Available = @()
    [object]$Server = $null
}

# ----------------------------------------------------------------------------
#  Base directory: where the EXE (or script) lives.
#  Used ONLY for the external Logs folder and the optional external
#  Settings.json / NMenuMappings.json overrides.
# ----------------------------------------------------------------------------
if (-not [string]::IsNullOrWhiteSpace($PSScriptRoot)) {
    $script:BaseDirectory = $PSScriptRoot
}
else {
    $script:BaseDirectory = [System.AppDomain]::CurrentDomain.BaseDirectory.TrimEnd('\')
}

