            <Setter Property="Background" Value="#475569"/>
        </Style>

        <!-- GroupBox cards -->
        <Style TargetType="GroupBox">
            <Setter Property="Margin" Value="5"/>
            <Setter Property="Padding" Value="8"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="Background" Value="{StaticResource CardBrush}"/>
            <Setter Property="BorderBrush" Value="{StaticResource BorderBrush}"/>
            <Setter Property="BorderThickness" Value="1"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Foreground" Value="{StaticResource PrimaryDarkBrush}"/>
        </Style>

        <!-- Tab styling: a "step dot" before each label (Kradle wizard style) -->
        <Style TargetType="TabItem">
            <Setter Property="FontSize" Value="12.5"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Foreground" Value="{StaticResource MutedTextBrush}"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="TabItem">
                        <Border x:Name="tabBd" Background="Transparent" CornerRadius="8" Padding="14,7" Margin="2,0,2,0">
                            <StackPanel Orientation="Horizontal">
                                <Ellipse x:Name="tabDot" Width="11" Height="11" Margin="0,0,8,0"
                                         Stroke="{StaticResource MutedTextBrush}" StrokeThickness="2" Fill="Transparent"/>
                                <ContentPresenter ContentSource="Header" VerticalAlignment="Center"/>
                            </StackPanel>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsSelected" Value="True">
                                <Setter TargetName="tabBd" Property="Background" Value="{StaticResource SelectedTabBgBrush}"/>
                                <Setter TargetName="tabDot" Property="Fill" Value="{StaticResource PrimaryBrush}"/>
                                <Setter TargetName="tabDot" Property="Stroke" Value="{StaticResource PrimaryBrush}"/>
                                <Setter Property="Foreground" Value="{StaticResource PrimaryBrush}"/>
                            </Trigger>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="tabBd" Property="Background" Value="#F1F5F9"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Toggle switch (styled CheckBox) - iOS/Kradle-style on/off pill -->
        <Style x:Key="ToggleSwitchStyle" TargetType="CheckBox">
            <Setter Property="VerticalContentAlignment" Value="Center"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Foreground" Value="{StaticResource TextBrush}"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="CheckBox">
                        <StackPanel Orientation="Horizontal" Background="Transparent">
                            <Border x:Name="track" Width="40" Height="21" CornerRadius="11" Background="#CBD5E1" VerticalAlignment="Center">
                                <Ellipse x:Name="thumb" Width="15" Height="15" Fill="White" HorizontalAlignment="Left" Margin="3,0,0,0"/>
                            </Border>
                            <ContentPresenter Margin="8,0,0,0" VerticalAlignment="Center"/>
                        </StackPanel>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="track" Property="Background" Value="{StaticResource PrimaryBrush}"/>
                                <Setter TargetName="thumb" Property="HorizontalAlignment" Value="Right"/>
                                <Setter TargetName="thumb" Property="Margin" Value="0,0,3,0"/>
                            </Trigger>
                            <Trigger Property="IsEnabled" Value="False">
                                <Setter TargetName="track" Property="Opacity" Value="0.5"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Health pill button (Resources column): coloured by the row's Health value
             (green OK / amber CAUTION / red CRITICAL / grey when not yet checked) -->
        <Style x:Key="HealthButtonStyle" TargetType="Button">
            <Setter Property="Foreground" Value="White"/>
            <Setter Property="FontSize" Value="11"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="Height" Value="24"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Background" Value="{StaticResource MutedTextBrush}"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="hb" Background="{TemplateBinding Background}" CornerRadius="5" Padding="10,2">
                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="hb" Property="Opacity" Value="0.85"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
            <Style.Triggers>
                <DataTrigger Binding="{Binding Health}" Value="OK">
                    <Setter Property="Background" Value="{StaticResource SuccessBrush}"/>
                </DataTrigger>
                <DataTrigger Binding="{Binding Health}" Value="CAUTION">
                    <Setter Property="Background" Value="{StaticResource WarningBrush}"/>
                </DataTrigger>
                <DataTrigger Binding="{Binding Health}" Value="CRITICAL">
                    <Setter Property="Background" Value="{StaticResource DangerBrush}"/>
                </DataTrigger>
            </Style.Triggers>
        </Style>

        <!-- Multi-select target picker: a ComboBox-looking ToggleButton that opens a
             checkbox popup (pick several servers). -->
        <Style x:Key="TargetPickerStyle" TargetType="ToggleButton">
            <Setter Property="Height" Value="26"/>
            <Setter Property="Background" Value="White"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="FontSize" Value="12"/>
            <Setter Property="Foreground" Value="{StaticResource TextBrush}"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="ToggleButton">
                        <Border x:Name="tp" Background="{TemplateBinding Background}" BorderBrush="{StaticResource BorderBrush}" BorderThickness="1" CornerRadius="4" Padding="8,0">
                            <DockPanel>
                                <TextBlock DockPanel.Dock="Right" Text="&#9662;" Margin="6,0,0,0" VerticalAlignment="Center" Foreground="{StaticResource MutedTextBrush}"/>
                                <ContentPresenter VerticalAlignment="Center" HorizontalAlignment="Left"/>
                            </DockPanel>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsChecked" Value="True">
                                <Setter TargetName="tp" Property="BorderBrush" Value="{StaticResource PrimaryBrush}"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Subtle footer buttons (on the dark footer bar) -->
        <Style x:Key="FooterButtonStyle" TargetType="Button">
            <Setter Property="Foreground" Value="#E2E8F0"/>
            <Setter Property="Background" Value="#334155"/>
            <Setter Property="FontSize" Value="11"/>
            <Setter Property="Height" Value="20"/>
            <Setter Property="Padding" Value="10,0"/>
            <Setter Property="Margin" Value="8,0,0,0"/>
            <Setter Property="Cursor" Value="Hand"/>
            <Setter Property="Template">
                <Setter.Value>
                    <ControlTemplate TargetType="Button">
                        <Border x:Name="fb" Background="{TemplateBinding Background}" CornerRadius="4" Padding="{TemplateBinding Padding}">
                            <ContentPresenter VerticalAlignment="Center" HorizontalAlignment="Center"/>
                        </Border>
                        <ControlTemplate.Triggers>
                            <Trigger Property="IsMouseOver" Value="True">
                                <Setter TargetName="fb" Property="Background" Value="#475569"/>
                            </Trigger>
                        </ControlTemplate.Triggers>
                    </ControlTemplate>
                </Setter.Value>
            </Setter>
        </Style>

        <!-- Target-server selector label -->
        <Style x:Key="TargetLabelStyle" TargetType="TextBlock">
            <Setter Property="Foreground" Value="{StaticResource PrimaryDarkBrush}"/>
            <Setter Property="FontWeight" Value="SemiBold"/>
            <Setter Property="VerticalAlignment" Value="Center"/>
            <Setter Property="Margin" Value="0,0,8,0"/>
        </Style>

    </Window.Resources>

    <Grid>

        <Grid.RowDefinitions>
            <RowDefinition Height="58"/>
            <RowDefinition Height="*"/>
			<RowDefinition Height="28"/>
        </Grid.RowDefinitions>

        <!-- Header -->
        <Border
            Grid.Row="0"
            Background="{StaticResource HeaderGradientBrush}"
            Padding="18,7">

            <Grid>
                <Grid.ColumnDefinitions>
                    <ColumnDefinition Width="*"/>
                    <ColumnDefinition Width="Auto"/>
                </Grid.ColumnDefinitions>

                <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                    <Image Source="{StaticResource AppLogoWhite}" Width="48" Height="48" Margin="0,0,14,0"
                           VerticalAlignment="Center" RenderOptions.BitmapScalingMode="HighQuality"
                           SnapsToDevicePixels="True"/>
                    <StackPanel VerticalAlignment="Center">
                        <TextBlock
                            x:Name="TxtAppTitle"
                            Text="Foreman"
                            Foreground="White"
                            FontSize="20"
                            FontWeight="Bold"/>

                        <TextBlock
                            Text="OneLink remote deployment, database and service management"
                            Foreground="#DBE4FF"
                            FontSize="11"
                            Margin="0,2,0,0"/>
                    </StackPanel>
                </StackPanel>

                <Border
                    Grid.Column="1"
                    Background="#33FFFFFF"
                    CornerRadius="12"
                    Padding="12,5"
                    VerticalAlignment="Center">

                    <TextBlock
                        x:Name="TxtAppBadge"
                        Text="Aristocrat Customer Success"
                        Foreground="White"
                        FontSize="11"
                        FontWeight="SemiBold"/>
                </Border>
            </Grid>
        </Border>

        <!-- Scrollable middle region (header stays pinned above, footer below) -->
        <ScrollViewer Grid.Row="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <Grid>
            <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>

        <!-- Servers manager -->
        <Border
            Grid.Row="0"
            Margin="14,12,14,6"
            Padding="10"
            Background="White"
            BorderBrush="{StaticResource BorderBrush}"
            BorderThickness="1"
            CornerRadius="6">

            <Grid>
                <Grid.RowDefinitions>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="Auto"/>
                    <RowDefinition Height="150"/>
                    <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>

                <!-- Toolbar: title + row actions + config import/export -->
                <Grid Grid.Row="0">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="*"/>
                        <ColumnDefinition Width="Auto"/>
                    </Grid.ColumnDefinitions>

                    <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
                        <TextBlock Text="Servers" FontSize="14" FontWeight="Bold" Foreground="{StaticResource PrimaryDarkBrush}" VerticalAlignment="Center" Margin="0,0,12,0"/>
                        <Button x:Name="BtnAddServer" Content="Add Row" Style="{StaticResource PrimaryButtonStyle}"/>
                        <Button x:Name="BtnRemoveServer" Content="Clear All" Style="{StaticResource SecondaryButtonStyle}"
                                ToolTip="Remove every server row from the list (asks to confirm). To remove a single server, right-click its row."/>
                        <Button x:Name="BtnSameCreds" Content="Same login for all" Style="{StaticResource SecondaryButtonStyle}"
                                ToolTip="Set one username/password and apply it to every server row (or the selected rows)"/>
                    </StackPanel>

                    <StackPanel Grid.Column="1" Orientation="Horizontal" HorizontalAlignment="Right">
                        <Button x:Name="BtnTemplateConfig" Content="Template" Style="{StaticResource SecondaryButtonStyle}"
                                ToolTip="Save a blank fill-in Excel template (tabs: Servers / Database / Package / Certificate / Service) with every option"/>
                        <Button x:Name="BtnImportConfig" Content="Import Config" Style="{StaticResource SecondaryButtonStyle}"/>
                        <Button x:Name="BtnExportConfig" Content="Export Config" Style="{StaticResource SecondaryButtonStyle}"
                                ToolTip="Save the current config as a colour Excel workbook (re-importable)"/>
                    </StackPanel>
                </Grid>

                <TextBlock
                    Grid.Row="1"
                    Margin="2,8,0,4"
                    Foreground="{StaticResource MutedTextBrush}"
                    FontSize="12"
                    Text="Type IP, Port and Username in each row; click the Password and Roles cells to set them; then Connect All."/>

                <!-- Editable server grid -->
                <DataGrid
                    x:Name="ServerGrid"
                    Grid.Row="2"
                    AutoGenerateColumns="False"
                    CanUserAddRows="False"
                    CanUserDeleteRows="False"
                    HeadersVisibility="Column"
                    SelectionMode="Extended"
                    GridLinesVisibility="Horizontal"
                    Background="White"
                    RowBackground="White"
                    AlternatingRowBackground="#F8FAFC"
                    BorderBrush="{StaticResource BorderBrush}"
                    BorderThickness="1"
                    CanUserResizeRows="False"
                    RowHeight="30"
                    ColumnHeaderHeight="28"
                    HorizontalScrollBarVisibility="Auto"
                    FontWeight="Normal">
                    <DataGrid.Columns>
                        <DataGridTextColumn Header="Server IP / Host" Binding="{Binding Host, UpdateSourceTrigger=LostFocus}" Width="2*"/>
                        <DataGridTextColumn Header="Port" Binding="{Binding Port, UpdateSourceTrigger=LostFocus}" Width="55"/>
                        <DataGridTextColumn Header="Username" Binding="{Binding Username, UpdateSourceTrigger=LostFocus}" Width="1.4*"/>
                        <DataGridTemplateColumn Header="Password" Width="120" IsReadOnly="True">
                            <DataGridTemplateColumn.CellTemplate>
                                <DataTemplate>
                                    <Button Content="{Binding PasswordDisplay}" Tag="Password" Margin="2" Padding="6,2" Cursor="Hand"/>
                                </DataTemplate>
                            </DataGridTemplateColumn.CellTemplate>
                        </DataGridTemplateColumn>
                        <DataGridTemplateColumn Header="Roles (mark)" Width="2.4*" IsReadOnly="True">
                            <DataGridTemplateColumn.CellTemplate>
                                <DataTemplate>
                                    <Button Content="{Binding RolesDisplay}" Tag="Roles" Margin="2" Padding="6,2" Cursor="Hand" HorizontalContentAlignment="Left"/>
                                </DataTemplate>
                            </DataGridTemplateColumn.CellTemplate>
                        </DataGridTemplateColumn>
                        <DataGridTemplateColumn Header="OneLink Services" Width="2*" IsReadOnly="True">
                            <DataGridTemplateColumn.CellTemplate>
                                <DataTemplate>
                                    <DockPanel LastChildFill="True">
                                        <Button DockPanel.Dock="Right" Tag="RefreshServices" Content="&#x21BB;"
                                                Width="22" Height="20" Padding="0" Margin="4,1,2,1" FontSize="12" Cursor="Hand"
                                                ToolTip="Re-check the OneLink services installed on this server"/>
                                        <TextBlock Text="{Binding ServicesDisplay}" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" Margin="2,0,0,0"/>
                                    </DockPanel>
                                </DataTemplate>
                            </DataGridTemplateColumn.CellTemplate>
                        </DataGridTemplateColumn>
                        <DataGridTemplateColumn Header="Resources" Width="96" IsReadOnly="True">
                            <DataGridTemplateColumn.CellTemplate>
                                <DataTemplate>
                                    <Button Tag="Resources" Style="{StaticResource HealthButtonStyle}"
                                            Content="{Binding Health}"
                                            Margin="2"
                                            ToolTip="Show disk partitions, memory and CPU (green = OK, amber = caution, red = critical)"/>
                                </DataTemplate>
                            </DataGridTemplateColumn.CellTemplate>
                        </DataGridTemplateColumn>
                        <DataGridTextColumn Header="Status" Binding="{Binding Status}" IsReadOnly="True" Width="2*"/>
                        <DataGridTemplateColumn Header="Actions" Width="160" IsReadOnly="True">
                            <DataGridTemplateColumn.CellTemplate>
                                <DataTemplate>
                                    <StackPanel Orientation="Horizontal">
                                        <Button Tag="Console" Content="Console" Margin="2" Padding="8,2" Cursor="Hand"
                                                ToolTip="Open an SSH command console on THIS server (run touch, chmod, systemctl status, ...)."/>
                                        <Button Tag="EditFile" Content="Edit File" Margin="2" Padding="8,2" Cursor="Hand"
                                                ToolTip="Open and edit a file on this server."/>
                                    </StackPanel>
                                </DataTemplate>
                            </DataGridTemplateColumn.CellTemplate>
                        </DataGridTemplateColumn>
                    </DataGrid.Columns>
                </DataGrid>

                <!-- Connect controls + summary -->
                <Grid Grid.Row="3" Margin="0,8,0,0">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="Auto"/>
                        <ColumnDefinition Width="Auto"/>
                        <ColumnDefinition Width="Auto"/>
                        <ColumnDefinition Width="*"/>
                    </Grid.ColumnDefinitions>

                    <Button x:Name="BtnConnect"    Grid.Column="0" Content="Connect All"    Style="{StaticResource SuccessButtonStyle}"/>
                    <Button x:Name="BtnDisconnect" Grid.Column="1" Content="Disconnect All" Style="{StaticResource DangerButtonStyle}" IsEnabled="False"/>

                    <TextBlock Grid.Column="2" Text="Status:" Margin="16,0,8,0" FontWeight="SemiBold" Foreground="{StaticResource PrimaryDarkBrush}" VerticalAlignment="Center"/>

                    <Border Grid.Column="3" Background="#FEE2E2" CornerRadius="5" Padding="10,6" Margin="5" VerticalAlignment="Center">
                        <TextBlock
                            x:Name="TxtConnectionStatus"
                            Text="No servers added"
                            Foreground="{StaticResource DangerBrush}"
                            FontWeight="Bold"/>
                    </Border>
                </Grid>
            </Grid>
        </Border>

        <!-- Operations -->
        <Grid Grid.Row="1" Margin="18,8,18,4">

            <Grid.RowDefinitions>
                <RowDefinition Height="Auto"/>
                <RowDefinition Height="Auto"/>
            </Grid.RowDefinitions>

            <StackPanel Grid.Row="0" Orientation="Horizontal" Margin="0,0,0,6">
                <Border
                    Width="5"
                    Height="20"
                    Background="{StaticResource AccentBrush}"
                    CornerRadius="2"
                    Margin="0,0,8,0"/>

                <TextBlock
                    Text="Operations"
                    FontSize="16"
                    FontWeight="Bold"
                    Foreground="{StaticResource PrimaryDarkBrush}"/>
            </StackPanel>

            <TabControl Grid.Row="1" x:Name="OperationTabs" Height="470">

                <!-- Database tab -->
                <TabItem Header="Database">
                    <ScrollViewer
                        VerticalScrollBarVisibility="Auto"
                        HorizontalScrollBarVisibility="Disabled">

                        <Grid Margin="12" MinHeight="390">

                        <Grid.RowDefinitions>
                            <RowDefinition Height="Auto"/>
                            <RowDefinition Height="*"/>
                        </Grid.RowDefinitions>

                        <!-- One target for the whole Database tab (Database master / slave only) -->
                        <StackPanel Grid.Row="0">
                            <StackPanel Orientation="Horizontal" Margin="4,0,4,6">
                                <TextBlock Text="Target server (Database master / slave):" Style="{StaticResource TargetLabelStyle}"/>
                                <ToggleButton x:Name="BtnTargetDb" MinWidth="220" MaxWidth="360" Content="No DB server" Style="{StaticResource TargetPickerStyle}"
                                              ToolTip="Pick one or more Database-marked servers to act on"/>
                                <Popup x:Name="PopTargetDb" StaysOpen="False" Placement="Bottom" PlacementTarget="{Binding ElementName=BtnTargetDb}" IsOpen="{Binding IsChecked, ElementName=BtnTargetDb, Mode=TwoWay}">
                                    <Border Background="White" BorderBrush="{StaticResource BorderBrush}" BorderThickness="1" CornerRadius="6" Padding="8" Margin="0,2,0,0">
                                        <ScrollViewer MaxHeight="240" VerticalScrollBarVisibility="Auto"><StackPanel x:Name="PnlTargetDb" MinWidth="200"/></ScrollViewer>
                                    </Border>
                                </Popup>
                            </StackPanel>

                            <StackPanel Orientation="Horizontal" Margin="4,0,4,10">
                                <TextBlock Text="MySQL service:" Style="{StaticResource TargetLabelStyle}"/>
                                <Button x:Name="BtnMysqlRestart" Content="Restart" Style="{StaticResource PrimaryButtonStyle}" MinWidth="90"/>
                                <Button x:Name="BtnMysqlStop" Content="Stop" Style="{StaticResource DangerButtonStyle}" MinWidth="90"/>
                                <Button x:Name="BtnMysqlStatus" Content="Get Status of Database" Style="{StaticResource SecondaryButtonStyle}"/>
                                <Border CornerRadius="5" Padding="12,4" Margin="10,0,0,0" VerticalAlignment="Center" Background="#F1F5F9">
                                    <TextBlock x:Name="TxtMysqlStatus" Text="Status: unknown" FontWeight="Bold" Foreground="{StaticResource MutedTextBrush}"/>
                                </Border>
                            </StackPanel>
                        </StackPanel>

                        <Grid Grid.Row="1">
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="*"/>
                                <ColumnDefinition Width="*"/>
                            </Grid.ColumnDefinitions>

                            <!-- LEFT COLUMN: Create Database, then Create Database User -->
                            <StackPanel Grid.Column="0">

                                <GroupBox Header="Create Database">
                                    <Grid Margin="10">
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="135"/>
                                            <ColumnDefinition Width="*"/>
                                        </Grid.ColumnDefinitions>
                                        <Grid.RowDefinitions>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                        </Grid.RowDefinitions>

                                        <TextBlock Grid.Row="0" Text="Database Name:"/>
                                        <TextBox x:Name="TxtDatabaseName" Grid.Row="0" Grid.Column="1" ToolTip="Database to create"/>

                                        <Button x:Name="BtnCreateDatabase" Grid.Row="1" Grid.ColumnSpan="2"
                                                Content="Create Database" Style="{StaticResource PrimaryButtonStyle}"
                                                HorizontalAlignment="Right" Margin="6,14,6,6"/>
                                    </Grid>
                                </GroupBox>

                                <GroupBox Header="Create Database User">
                                    <Grid Margin="10">
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="135"/>
                                            <ColumnDefinition Width="*"/>
                                        </Grid.ColumnDefinitions>
                                        <Grid.RowDefinitions>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                        </Grid.RowDefinitions>

                                        <TextBlock Grid.Row="0" Text="Username:"/>
                                        <TextBox x:Name="TxtDbUser" Grid.Row="0" Grid.Column="1" ToolTip="New MySQL username"/>

                                        <TextBlock Grid.Row="1" Text="Password:"/>
                                        <PasswordBox x:Name="PwdDbUser" Grid.Row="1" Grid.Column="1" ToolTip="Password for the new MySQL user"/>

                                        <TextBlock Grid.Row="2" Text="Re-type Password:"/>
                                        <PasswordBox x:Name="PwdDbUserConfirm" Grid.Row="2" Grid.Column="1" ToolTip="Re-enter the password to confirm it matches"/>

                                        <CheckBox x:Name="ChkSetAllowedIp" Style="{StaticResource ToggleSwitchStyle}" Grid.Row="3" Content="Allowed IP:" VerticalAlignment="Center"
                                                  ToolTip="Leave UNCHECKED to use the default (% = any host). Check it to lock in a specific client host/IP."/>
                                        <ComboBox x:Name="CmbDbUserIp" Grid.Row="3" Grid.Column="1" IsEditable="True" IsEnabled="False"
                                                  ToolTip="Client host allowed to connect. Pick % (any host), localhost (local-only), the target server IP, or type one. Blank = % (works locally AND remotely). Enabled only when 'Allowed IP' is checked."/>

                                        <Button x:Name="BtnCreateDbUser" Grid.Row="4" Grid.ColumnSpan="2"
                                                Content="Create DB User" Style="{StaticResource PrimaryButtonStyle}"
                                                HorizontalAlignment="Right" Margin="6,14,6,6"/>
                                    </Grid>
                                </GroupBox>

                                <GroupBox Header="InnoDB Buffer Pool Size">
                                    <Grid Margin="10">
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="135"/>
                                            <ColumnDefinition Width="*"/>
                                        </Grid.ColumnDefinitions>
                                        <Grid.RowDefinitions>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                        </Grid.RowDefinitions>

                                        <TextBlock x:Name="TxtInnodbInfo" Grid.Row="0" Grid.ColumnSpan="2" TextWrapping="Wrap"
                                                   Foreground="{StaticResource MutedTextBrush}" Margin="0,0,0,8"
                                                   Text="Click 'Check Current / Recommended' to load the current buffer pool size and RAM for the target server."/>

                                        <Button x:Name="BtnInnodbCheck" Grid.Row="1" Grid.ColumnSpan="2"
                                                Content="Check Current / Recommended" Style="{StaticResource SecondaryButtonStyle}"
                                                HorizontalAlignment="Right" Margin="6,0,6,10"/>

                                        <TextBlock Grid.Row="2" Text="New Size:"/>
                                        <TextBox x:Name="TxtInnodbSize" Grid.Row="2" Grid.Column="1"
                                                 ToolTip="e.g. 1.5G, 500M, 2GB, 1.5g, 500mb (case-insensitive; G/GB or M/MB)"/>

                                        <Border x:Name="BrdInnodbWarn" Grid.Row="3" Grid.ColumnSpan="2" CornerRadius="5" Padding="10,6" Margin="0,8,0,0" Background="#F1F5F9">
                                            <TextBlock x:Name="TxtInnodbWarn" TextWrapping="Wrap" Foreground="{StaticResource MutedTextBrush}"
                                                       Text="Enter a size (e.g. 1.5G, 500M) and click 'Check Current / Recommended' to compare it against this server's RAM."/>
                                        </Border>

                                        <Button x:Name="BtnInnodbApply" Grid.Row="4" Grid.ColumnSpan="2"
                                                Content="Apply (Restarts MySQL)" Style="{StaticResource PrimaryButtonStyle}"
                                                HorizontalAlignment="Right" Margin="6,14,6,6"/>
                                    </Grid>
                                </GroupBox>

                                <!-- Run a .sql script already on the target server (nmenu 'ndb_run' equivalent) -->
                                <GroupBox Header="Run SQL Script">
                                    <Grid Margin="10">
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="135"/>
                                            <ColumnDefinition Width="*"/>
                                        </Grid.ColumnDefinitions>
                                        <Grid.RowDefinitions>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                        </Grid.RowDefinitions>

                                        <TextBlock Grid.Row="0" Text="Search (name contains):"/>
                                        <TextBox x:Name="TxtSqlSearchTerm" Grid.Row="0" Grid.Column="1"
                                                 ToolTip="e.g. 'test' finds test.sql, TEST.sql, Test_v2.sql, etc. anywhere on the target server."/>

                                        <Button x:Name="BtnSqlSearch" Grid.Row="1" Grid.ColumnSpan="2"
                                                Content="Search" Style="{StaticResource SecondaryButtonStyle}"
                                                HorizontalAlignment="Right" Margin="6,0,6,10"/>

                                        <TextBlock Grid.Row="2" Text="Found scripts:"/>
                                        <ComboBox x:Name="CmbSqlScriptFound" Grid.Row="2" Grid.Column="1"
                                                  ToolTip="Pick one of the matching .sql files found on the target server."/>

                                        <TextBlock x:Name="TxtSqlSearchStatus" Grid.Row="3" Grid.ColumnSpan="2" Text=""
                                                   Foreground="{StaticResource MutedTextBrush}" TextWrapping="Wrap" Margin="0,8,0,0"/>

                                        <Button x:Name="BtnRunSqlScript" Grid.Row="4" Grid.ColumnSpan="2"
                                                Content="Run Script" Style="{StaticResource DangerButtonStyle}"
                                                HorizontalAlignment="Right" Margin="6,14,6,6"/>
                                    </Grid>
                                </GroupBox>
                            </StackPanel>

                            <!-- RIGHT COLUMN: Grant, then Backup / Restore -->
                            <StackPanel Grid.Column="1">

                                <GroupBox Header="Grant Admin Privileges">
                                    <Grid Margin="10">
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="150"/>
                                            <ColumnDefinition Width="*"/>
                                        </Grid.ColumnDefinitions>
                                        <Grid.RowDefinitions>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                        </Grid.RowDefinitions>

                                        <TextBlock Grid.Row="0" Text="User:"/>
                                        <ComboBox x:Name="CmbGrantUser" Grid.Row="0" Grid.Column="1" IsEditable="True"
                                                  ToolTip="MySQL user. Use 'Refresh users / databases' to load them from the target, or type one."/>

                                        <TextBlock Grid.Row="1" Text="Database:"/>
                                        <ComboBox x:Name="CmbGrantDb" Grid.Row="1" Grid.Column="1" IsEditable="True"
                                                  ToolTip="Database to grant on. Use 'Refresh users / databases' to load them from the target, or type one."/>

                                        <TextBlock Grid.Row="2" Text="Account host / IP:"/>
                                        <ComboBox x:Name="CmbGrantHost" Grid.Row="2" Grid.Column="1" IsEditable="True" Text="%"
                                                  ToolTip="Use the same host as the MySQL account: %, localhost, or the IP supplied when creating the user."/>
                                        <TextBlock Grid.Row="3" Text="Password (Optional):"/>
                                        <PasswordBox x:Name="PwdGrant" Grid.Row="3" Grid.Column="1"
                                                     ToolTip="OPTIONAL - use at your own risk. Leave BLANK to grant without touching the password. If you set it, a WRONG value WILL overwrite the user's real password."/>

                                        <TextBlock Grid.Row="4" Text="Re-type Password:"/>
                                        <PasswordBox x:Name="PwdGrantConfirm" Grid.Row="4" Grid.Column="1"
                                                     ToolTip="Re-enter the optional password to confirm it matches (leave blank if you left Password blank)."/>

                                        <Button x:Name="BtnRefreshDbLists" Grid.Row="5" Grid.ColumnSpan="2"
                                                Content="Refresh users / databases" Style="{StaticResource SecondaryButtonStyle}"
                                                HorizontalAlignment="Right" Margin="6,12,6,4"/>

                                        <Button x:Name="BtnGrantPrivileges" Grid.Row="6" Grid.ColumnSpan="2"
                                                Content="Grant Admin Privileges" Style="{StaticResource SuccessButtonStyle}"
                                                HorizontalAlignment="Right" Margin="6,4,6,6"/>
                                    </Grid>
                                </GroupBox>

                                <!-- BACKUP (export a dump to a destination) -->
                                <GroupBox Header="Backup (Export)">
                                    <Grid Margin="10">
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="150"/>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <Grid.RowDefinitions>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                        </Grid.RowDefinitions>

                                        <TextBlock Grid.Row="0" Text="Database:"/>
                                        <ComboBox x:Name="CmbExportDb" Grid.Row="0" Grid.Column="1" Grid.ColumnSpan="2" IsEditable="True" Text="onelink"
                                                  ToolTip="Database to back up. Use 'Refresh users / databases' to load them from the target, or type one."/>

                                        <TextBlock Grid.Row="1" Text="Destination:"/>
                                        <ComboBox x:Name="CmbExportDest" Grid.Row="1" Grid.Column="1" Grid.ColumnSpan="2"
                                                  ToolTip="Where to write the backup. Server = a path on the target VM; Local Windows = this PC; Network location = a UNC share (with credentials).">
                                            <ComboBoxItem Content="Server (path on the VM)" IsSelected="True"/>
                                            <ComboBoxItem Content="Local Windows (this PC)"/>
                                            <ComboBoxItem Content="Network location (share)"/>
                                        </ComboBox>

                                        <StackPanel x:Name="ExportNetRow" Grid.Row="2" Grid.ColumnSpan="3" Orientation="Horizontal" Visibility="Collapsed" Margin="0,4,0,0">
                                            <TextBlock Text="Network user / pass:" Width="150" VerticalAlignment="Center"/>
                                            <TextBox x:Name="TxtExportNetUser" Width="150" ToolTip="OPTIONAL. Username for the network share (e.g. DOMAIN\\user)."/>
                                            <PasswordBox x:Name="PwdExportNetPass" Width="150" Margin="8,0,0,0" ToolTip="OPTIONAL. Password for the network share."/>
                                        </StackPanel>

                                        <TextBlock Grid.Row="3" Text="Backup file:"/>
                                        <TextBox x:Name="TxtExportFile" Grid.Row="3" Grid.Column="1" Text="/mysqldata/ndb_export.sql.gz"
                                                 ToolTip="Where to write the dump. Server: an absolute Linux path. Local Windows: a path on THIS PC (Browse). Network: a UNC path (e.g. \\server\share\db.sql.gz)."/>
                                        <Button x:Name="BtnBrowseExport" Grid.Row="3" Grid.Column="2" Content="Browse..." Style="{StaticResource SecondaryButtonStyle}" Margin="6,0,0,0"/>

                                        <TextBlock x:Name="TxtExportStatus" Grid.Row="4" Grid.ColumnSpan="3" Text="" Foreground="{StaticResource MutedTextBrush}" TextWrapping="Wrap" Margin="0,6,0,0"/>

                                        <StackPanel Grid.Row="5" Grid.ColumnSpan="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,10,0,4">
                                            <Button x:Name="BtnStopExport" Content="Stop" Style="{StaticResource DangerButtonStyle}" IsEnabled="False"/>
                                            <Button x:Name="BtnExportDb" Content="Export DB" Style="{StaticResource SuccessButtonStyle}"/>
                                        </StackPanel>
                                    </Grid>
                                </GroupBox>

                                <!-- RESTORE (import a dump from a source) -->
                                <GroupBox Header="Restore (Import)">
                                    <Grid Margin="10">
                                        <Grid.ColumnDefinitions>
                                            <ColumnDefinition Width="150"/>
                                            <ColumnDefinition Width="*"/>
                                            <ColumnDefinition Width="Auto"/>
                                        </Grid.ColumnDefinitions>
                                        <Grid.RowDefinitions>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                            <RowDefinition Height="Auto"/>
                                        </Grid.RowDefinitions>

                                        <TextBlock Grid.Row="0" Text="Database:"/>
                                        <ComboBox x:Name="CmbImportDb" Grid.Row="0" Grid.Column="1" Grid.ColumnSpan="2" IsEditable="True" Text="onelink"
                                                  ToolTip="Database to restore INTO. Use 'Refresh users / databases' to load them from the target, or type one."/>

                                        <TextBlock Grid.Row="1" Text="Source:"/>
                                        <ComboBox x:Name="CmbImportSrc" Grid.Row="1" Grid.Column="1" Grid.ColumnSpan="2"
                                                  ToolTip="Where the backup file comes FROM. Server = a path already on the target VM; Local Windows = this PC; Network location = a UNC share; Another VM = pull it from a different VM over SSH.">
                                            <ComboBoxItem Content="Server (path on the VM)" IsSelected="True"/>
                                            <ComboBoxItem Content="Local Windows (this PC)"/>
                                            <ComboBoxItem Content="Network location (share)"/>
                                            <ComboBoxItem Content="Another VM (SSH)"/>
                                        </ComboBox>

                                        <StackPanel x:Name="ImportNetRow" Grid.Row="2" Grid.ColumnSpan="3" Orientation="Horizontal" Visibility="Collapsed" Margin="0,4,0,0">
                                            <TextBlock Text="Network user / pass:" Width="150" VerticalAlignment="Center"/>
                                            <TextBox x:Name="TxtImportNetUser" Width="150" ToolTip="OPTIONAL. Username for the network share."/>
                                            <PasswordBox x:Name="PwdImportNetPass" Width="150" Margin="8,0,0,0" ToolTip="OPTIONAL. Password for the network share."/>
                                        </StackPanel>

                                        <StackPanel x:Name="ImportVmRow" Grid.Row="3" Grid.ColumnSpan="3" Orientation="Horizontal" Visibility="Collapsed" Margin="0,4,0,0">
                                            <TextBlock Text="VM host / user / pass:" Width="150" VerticalAlignment="Center"/>
                                            <TextBox x:Name="TxtImportVmHost" Width="120" ToolTip="IP / hostname of the other VM (RHEL or Debian)."/>
                                            <TextBox x:Name="TxtImportVmUser" Width="90" Margin="6,0,0,0" ToolTip="SSH username on the other VM."/>
                                            <PasswordBox x:Name="PwdImportVmPass" Width="90" Margin="6,0,0,0" ToolTip="SSH password on the other VM."/>
                                        </StackPanel>

                                        <TextBlock Grid.Row="4" Text="Backup file:"/>
                                        <TextBox x:Name="TxtImportFile" Grid.Row="4" Grid.Column="1" Text="/mysqldata/ndb_export.sql.gz"
                                                 ToolTip="Path of the backup to restore FROM. Server / Another VM: an absolute Linux path. Local Windows: a path on THIS PC (Browse). Network: a UNC path."/>
                                        <Button x:Name="BtnBrowseImport" Grid.Row="4" Grid.Column="2" Content="Browse..." Style="{StaticResource SecondaryButtonStyle}" Margin="6,0,0,0"/>

                                        <TextBlock x:Name="TxtImportStatus" Grid.Row="5" Grid.ColumnSpan="3" Text="" Foreground="{StaticResource MutedTextBrush}" TextWrapping="Wrap" Margin="0,6,0,0"/>

                                        <StackPanel Grid.Row="6" Grid.ColumnSpan="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,10,0,4">
                                            <Button x:Name="BtnStopImport" Content="Stop" Style="{StaticResource DangerButtonStyle}" IsEnabled="False"/>
                                            <Button x:Name="BtnImportDb" Content="Import DB" Style="{StaticResource PrimaryButtonStyle}"/>
                                        </StackPanel>
                                    </Grid>
                                </GroupBox>
                            </StackPanel>
                        </Grid>
                    </Grid>
                </ScrollViewer>
                </TabItem>

                <!-- Package tab -->
                <TabItem Header="Certificates">
                    <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
                        <Grid Margin="12" MinHeight="340">
                        <GroupBox Header="Deploy Certificate / License" MinHeight="220" VerticalAlignment="Top">
                          <StackPanel>
                            <StackPanel Orientation="Horizontal" Margin="12,8,12,0">
                                <TextBlock Text="Target server:" Style="{StaticResource TargetLabelStyle}"/>
                                <ToggleButton x:Name="BtnTargetCert" MinWidth="220" MaxWidth="360" Content="All servers" Style="{StaticResource TargetPickerStyle}"
                                              ToolTip="Pick one or more servers to act on"/>
                                <Popup x:Name="PopTargetCert" StaysOpen="False" Placement="Bottom" PlacementTarget="{Binding ElementName=BtnTargetCert}" IsOpen="{Binding IsChecked, ElementName=BtnTargetCert, Mode=TwoWay}">
                                    <Border Background="White" BorderBrush="{StaticResource BorderBrush}" BorderThickness="1" CornerRadius="6" Padding="8" Margin="0,2,0,0">
                                        <ScrollViewer MaxHeight="240" VerticalScrollBarVisibility="Auto"><StackPanel x:Name="PnlTargetCert" MinWidth="200"/></ScrollViewer>
                                    </Border>
                                </Popup>
                            </StackPanel>
                            <Grid Margin="12">
                                <Grid.ColumnDefinitions>
                                    <ColumnDefinition Width="190"/>
                                    <ColumnDefinition Width="*"/>
                                    <ColumnDefinition Width="140"/>
                                </Grid.ColumnDefinitions>
                                <Grid.RowDefinitions>
                                    <RowDefinition Height="Auto"/>
                                    <RowDefinition Height="Auto"/>
                                    <RowDefinition Height="Auto"/>
                                    <RowDefinition Height="Auto"/>
                                    <RowDefinition Height="Auto"/>
                                    <RowDefinition Height="Auto"/>
                                    <RowDefinition Height="Auto"/>
                                    <RowDefinition Height="Auto"/>
                                    <RowDefinition Height="Auto"/>
                                    <RowDefinition Height="Auto"/>
                                    <RowDefinition Height="Auto"/>
                                </Grid.RowDefinitions>

                                <TextBlock Grid.Row="0" Text="Cert / License file (local/network):" VerticalAlignment="Center"/>
                                <TextBox x:Name="TxtCertFile" Grid.Row="0" Grid.Column="1"
                                         ToolTip="Local file OR a network path (e.g. \\server\share\file.pem). Accepts certificates AND licenses: .pem .crt .cer .der .cert .ks .jks .p12 .pfx .lic .key ..."/>
                                <Button x:Name="BtnBrowseCert" Grid.Row="0" Grid.Column="2" Content="Browse..."
                                        Style="{StaticResource SecondaryButtonStyle}"/>

                                <CheckBox x:Name="ChkCertNetAuth" Style="{StaticResource ToggleSwitchStyle}" Grid.Row="1" Content="Network login:" VerticalAlignment="Center"
                                          ToolTip="Tick only if the network folder needs a username and password."/>
                                <StackPanel Grid.Row="1" Grid.Column="1" Grid.ColumnSpan="2" Orientation="Horizontal">
                                    <TextBlock Text="User" VerticalAlignment="Center" Margin="0,0,5,0"/>
                                    <TextBox x:Name="TxtCertNetUser" Width="150" IsEnabled="False" ToolTip="Type the USERNAME for the network share (e.g. DOMAIN\\user). Enabled only when 'Network login' is ticked."/>
                                    <TextBlock Text="Password" VerticalAlignment="Center" Margin="12,0,5,0"/>
                                    <PasswordBox x:Name="PwdCertNetPass" Width="150" IsEnabled="False" ToolTip="Type the PASSWORD for the network share. Enabled only when 'Network login' is ticked."/>
                                    <Button x:Name="BtnCertNetTest" Content="Test login" IsEnabled="False" Margin="12,0,0,0"
                                            Style="{StaticResource SecondaryButtonStyle}"
                                            ToolTip="Check whether this username/password can connect to the network file/folder above."/>
                                </StackPanel>

                                <TextBlock Grid.Row="2" Text="Destination (server path):" VerticalAlignment="Center"/>
                                <TextBox x:Name="TxtCertDest" Grid.Row="2" Grid.Column="1" Grid.ColumnSpan="2"
                                         ToolTip="Absolute Linux path on the target (RHEL or Debian). End with '/' to keep the original filename, or give a full file path."/>
                                <TextBlock Grid.Row="3" Grid.Column="1" Grid.ColumnSpan="2" Foreground="Gray" FontStyle="Italic"
                                           Text="e.g. /opt/onelink/etc/client.ks   (or a directory like /opt/onelink/ ending in / )"/>

                                <TextBlock Grid.Row="4" Text="Back up existing file to:" VerticalAlignment="Center"
                                           ToolTip="If a file already exists at the destination, Deploy saves a copy of it here FIRST, before overwriting. Nothing is saved if there is no existing file yet."/>
                                <ComboBox x:Name="CmbCertBackupDest" Grid.Row="4" Grid.Column="1" Grid.ColumnSpan="2">
                                    <ComboBoxItem Content="Local Windows (this PC)" IsSelected="True"/>
                                    <ComboBoxItem Content="Server (same VM, alongside the file)"/>
                                    <ComboBoxItem Content="Don't back up"/>
                                </ComboBox>

                                <TextBlock Grid.Row="5" Text="Backup folder:" VerticalAlignment="Center"/>
                                <TextBox x:Name="TxtCertBackupPath" Grid.Row="5" Grid.Column="1"
                                         ToolTip="Where the backup copy goes. For 'Local Windows' this is a folder on this PC (a per-server subfolder is created under it); for 'Server' this is an absolute Linux folder on the target. Pre-filled but fully editable."/>
                                <Button x:Name="BtnCertBackupBrowse" Grid.Row="5" Grid.Column="2" Content="Browse..."
                                        Style="{StaticResource SecondaryButtonStyle}"
                                        ToolTip="Pick a folder on this PC (only used for the 'Local Windows' backup destination)."/>

                                <Separator Grid.Row="6" Grid.ColumnSpan="3" Margin="0,8,0,4"/>

                                <TextBlock Grid.Row="7" Text="Check Status - look for:" VerticalAlignment="Center"/>
                                <ComboBox x:Name="CmbCertType" Grid.Row="7" Grid.Column="1" Grid.ColumnSpan="2"
                                          ToolTip="File type to look for when you click 'List files' on a folder.">
                                    <ComboBoxItem Content="All (certs, keystores, licenses, keys)" IsSelected="True"/>
                                    <ComboBoxItem Content="Certificates (.pem .crt .cer .der .cert .ca .p7b .p7c .csr .crl)"/>
                                    <ComboBoxItem Content="Keystores (.ks .jks .p12 .pfx .keystore .truststore .jceks .bks)"/>
                                    <ComboBoxItem Content="Licenses (.lic .license)"/>
                                    <ComboBoxItem Content="Keys (.key .pk8 .p8)"/>
                                </ComboBox>

                                <TextBlock Grid.Row="8" Text="Folder / file on server:" VerticalAlignment="Center"/>
                                <TextBox x:Name="TxtCertScanPath" Grid.Row="8" Grid.Column="1" Text="/opt/onelink/etc/"
                                         ToolTip="A folder to scan (e.g. /opt/onelink/etc/) or a single file path on the target server."/>
                                <Button x:Name="BtnCertList" Grid.Row="8" Grid.Column="2" Content="List files"
                                        Style="{StaticResource SecondaryButtonStyle}"
                                        ToolTip="Scan that folder on the selected server and list the matching cert/keystore/license files below."/>

                                <TextBlock Grid.Row="9" Text="Found files:" VerticalAlignment="Center"/>
                                <ComboBox x:Name="CmbCertFound" Grid.Row="9" Grid.Column="1" Grid.ColumnSpan="2"
                                          ToolTip="Pick a file found by 'List files', then click 'Check Status'."/>

                                <StackPanel Grid.Row="10" Grid.ColumnSpan="3" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,10,0,0">
                                    <Button x:Name="BtnCertStatus" Content="Check Status"
                                            Style="{StaticResource SecondaryButtonStyle}"
                                            ToolTip="Show the details of the file selected in 'Found files' (or type a full file path there and check it)."/>
                                    <Button x:Name="BtnDeployCert" Content="Deploy Certificate"
                                            Style="{StaticResource SuccessButtonStyle}"/>
                                </StackPanel>
                            </Grid>
                            <Border Background="#FEF9C3" CornerRadius="6" Padding="10" Margin="12,0,12,12">
                                <TextBlock TextWrapping="Wrap" Foreground="{StaticResource PrimaryDarkBrush}"
                                           Text="Deploy uploads the selected file (certificate OR license: .pem .crt .cer .der .cert .ks .jks .p12 .pfx .lic .key ...) and installs it at the destination path on each target server. To inspect what's on a server: type a folder in 'Folder / file on server', click 'List files' to find the certs/keystores/licenses, pick one under 'Found files', then click 'Check Status'. If a service must load a new cert (e.g. an appserver keystore), restart it from the Package tab -> Service Installer."/>
                            </Border>
                          </StackPanel>
                        </GroupBox>
                    </Grid>
                    </ScrollViewer>
                </TabItem>

                <!-- Activity Metrics tab - clicks/fields/time captured per activity -->
                <TabItem Header="Package">
                    <ScrollViewer
                        VerticalScrollBarVisibility="Auto"
                        HorizontalScrollBarVisibility="Disabled">

                        <Grid Margin="12" MinHeight="330">
                            <Grid.ColumnDefinitions>
                                <ColumnDefinition Width="Auto"/>
                                <ColumnDefinition Width="*"/>
                            </Grid.ColumnDefinitions>
                            <Grid.RowDefinitions>
                                <RowDefinition Height="Auto"/>
                                <RowDefinition Height="Auto"/>
                                <RowDefinition Height="230"/>
                                <RowDefinition Height="Auto"/>
                            </Grid.RowDefinitions>

                            <GroupBox Grid.Row="0" Grid.Column="1" Header="Package Source (folder of .rpm / .deb packages)">
                                <Grid Margin="14">
                                    <Grid.ColumnDefinitions>
                                        <ColumnDefinition Width="180"/>
                                        <ColumnDefinition Width="*"/>
                                        <ColumnDefinition Width="140"/>
                                    </Grid.ColumnDefinitions>
                                    <Grid.RowDefinitions>
                                        <RowDefinition Height="Auto"/>
                                        <RowDefinition Height="Auto"/>
                                        <RowDefinition Height="Auto"/>
                                        <RowDefinition Height="Auto"/>
                                        <RowDefinition Height="Auto"/>
                                    </Grid.RowDefinitions>

                                    <TextBlock Grid.Row="0" Text="Folder(s) (local or network):" VerticalAlignment="Top" Margin="0,6,0,0"/>
                                    <TextBox
                                        x:Name="TxtPackagePath"
                                        Grid.Row="0"
                                        Grid.Column="1"
                                        TextWrapping="Wrap" AcceptsReturn="False"
                                        ToolTip="One folder, OR several LOCAL folders picked via Browse (shown separated by ' ; '), OR a single network path (e.g. \\server\share\...). Every subfolder under each one is searched too. You can also type or paste a single path directly."/>
                                    <Button
                                        x:Name="BtnBrowsePackage"
                                        Grid.Row="0"
                                        Grid.Column="2"
                                        Content="Browse..."
                                        VerticalAlignment="Top"
                                        Style="{StaticResource SecondaryButtonStyle}"
                                        ToolTip="Tick one or more folders (any drive, any branch) in the picker, then click OK - all of them are added at once."/>

                                    <CheckBox x:Name="ChkPkgNetAuth" Style="{StaticResource ToggleSwitchStyle}" Grid.Row="4" Content="Network login:" VerticalAlignment="Center"
                                              ToolTip="Tick only if the network folder needs a username and password."/>
                                    <StackPanel Grid.Row="4" Grid.Column="1" Grid.ColumnSpan="2" Orientation="Horizontal">
                                        <TextBlock Text="User" VerticalAlignment="Center" Margin="0,0,5,0"/>
                                        <TextBox x:Name="TxtNetUser" Width="150" IsEnabled="False" ToolTip="Type the USERNAME for the network share (e.g. DOMAIN\\user). Enabled only when 'Network login' is ticked."/>
                                        <TextBlock Text="Password" VerticalAlignment="Center" Margin="12,0,5,0"/>
                                        <PasswordBox x:Name="PwdNetPass" Width="150" IsEnabled="False" ToolTip="Type the PASSWORD for the network share. Enabled only when 'Network login' is ticked."/>
                                        <Button x:Name="BtnPkgNetTest" Content="Test login" IsEnabled="False" Margin="12,0,0,0"
                                                Style="{StaticResource SecondaryButtonStyle}"
                                                ToolTip="Check whether this username/password can connect to the network folder above."/>
                                    </StackPanel>

                                    <TextBlock Grid.Row="1" Text="Remote Directory:"/>
                                    <TextBox
                                        x:Name="TxtRemoteDirectory"
                                        Grid.Row="1"
                                        Grid.Column="1"
                                        Grid.ColumnSpan="2"
                                        ToolTip="Remote Linux directory used for package upload"/>

                                    <TextBlock Grid.Row="2" Text="Installation Mode:"/>
                                    <ComboBox
                                        x:Name="CmbInstallMode"
                                        Grid.Row="2"
                                        Grid.Column="1"
                                        Grid.ColumnSpan="2">
                                        <ComboBoxItem Content="Upgrade" IsSelected="True"/>
                                        <ComboBoxItem Content="Install"/>
                                    </ComboBox>

                                    <TextBlock Grid.Row="3" Text="Install Reason:"/>
                                    <TextBox
                                        x:Name="TxtInstallReason"
                                        Grid.Row="3"
                                        Grid.Column="1"
                                        Grid.ColumnSpan="2"
                                        ToolTip="Reason supplied to the package's install script (required for gaming-compliance packages). Sent both as the prompt answer and as the REASON environment variable."/>
                                </Grid>
                            </GroupBox>

                            <StackPanel Grid.Row="1" Grid.ColumnSpan="2" Orientation="Horizontal" Margin="4,10,4,4">
                                <TextBlock Text="Deployment plan (each role-marked, connected server -> matched package):"
                                           Style="{StaticResource TargetLabelStyle}" VerticalAlignment="Center"/>
                                <Button x:Name="BtnBuildPlan" Content="Build / Refresh Plan" Style="{StaticResource PrimaryButtonStyle}"/>
                                <Button x:Name="BtnRemovePlanRow" Content="Remove Selected" Style="{StaticResource SecondaryButtonStyle}"/>
                                <Button x:Name="BtnClearPlan" Content="Clear Plan" Style="{StaticResource DangerButtonStyle}"/>
                            </StackPanel>

                            <DataGrid
                                x:Name="PackageGrid"
                                Grid.Row="2"
                                Grid.ColumnSpan="2"
                                AutoGenerateColumns="False"
                                CanUserAddRows="False"
                                CanUserDeleteRows="False"
                                SelectionMode="Extended"
                                SelectionUnit="FullRow"
                                HeadersVisibility="Column"
                                GridLinesVisibility="Horizontal"
                                Background="White"
                                RowBackground="White"
                                AlternatingRowBackground="#F8FAFC"
                                BorderBrush="{StaticResource BorderBrush}"
                                BorderThickness="1"
                                FontWeight="Normal">
                                <DataGrid.Columns>
                                    <DataGridTextColumn Header="Server IP / Host" Binding="{Binding Host}" Width="1.6*" IsReadOnly="True"/>
                                    <DataGridTextColumn Header="Role" Binding="{Binding Role}" Width="*" IsReadOnly="True"/>
                                    <DataGridTemplateColumn Header="Package (pick or skip)" Width="3.4*">
                                        <DataGridTemplateColumn.CellTemplate>
                                            <DataTemplate>
                                                <ComboBox Tag="PlanPackage" ItemsSource="{Binding Available}" SelectedItem="{Binding Package, Mode=TwoWay, UpdateSourceTrigger=PropertyChanged}" Margin="2"/>
                                            </DataTemplate>
                                        </DataGridTemplateColumn.CellTemplate>
                                    </DataGridTemplateColumn>
                                    <DataGridTextColumn Header="Size" Binding="{Binding Size}" Width="0.8*" IsReadOnly="True"/>
                                    <DataGridTextColumn Header="Status" Binding="{Binding Status}" Width="1.6*" IsReadOnly="True"/>
                                </DataGrid.Columns>
                            </DataGrid>

                            <StackPanel Grid.Row="3" Grid.ColumnSpan="2" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,8,0,0">
                                <TextBlock Text="SSL after install (Concentrator / Report Server / Appserver):" Style="{StaticResource TargetLabelStyle}" VerticalAlignment="Center"/>
                                <ComboBox x:Name="CmbSslAfterInstall" Width="120" Margin="0,0,12,0"
                                          ToolTip="After a successful install, optionally enable/disable SSL for Concentrator and Report Server (via nmenu) and OneLink Appserver (via app.properties). Appserver Enable needs a keystore at /opt/onelink/etc/client.ks - deploy one first on the Certificates tab. Restart the affected service afterwards to apply.">
                                    <ComboBoxItem Content="No change" IsSelected="True"/>
                                    <ComboBoxItem Content="Enable"/>
                                    <ComboBoxItem Content="Disable"/>
                                </ComboBox>
                                <CheckBox x:Name="ChkEnableStart" Style="{StaticResource ToggleSwitchStyle}" Content="Enable &amp; start service after install" VerticalAlignment="Center" Margin="0,0,12,0"
                                          ToolTip="If checked, after a successful install the service is enabled and started (systemctl enable --now). If unchecked, the package is only installed."/>
                                <Button
                                    x:Name="BtnUploadPackage"
                                    Content="Upload Only"
                                    Style="{StaticResource SecondaryButtonStyle}"/>
                                <Button
                                    x:Name="BtnUploadInstall"
                                    Content="Upload and Install"
                                    Style="{StaticResource SuccessButtonStyle}"/>
                            </StackPanel>

                            <!-- Service Installer: check status first, then start/restart/stop -->
                            <GroupBox Grid.Row="0" Grid.Column="0" Header="Service Installer (check status, then start / restart / stop)" Margin="0,0,10,10">
                              <StackPanel>
                                <StackPanel Orientation="Horizontal" Margin="12,8,12,0">
                                    <TextBlock Text="Target server:" Style="{StaticResource TargetLabelStyle}"/>
                                    <ToggleButton x:Name="BtnTargetService" MinWidth="200" MaxWidth="340" Content="All servers" Style="{StaticResource TargetPickerStyle}"
                                                  ToolTip="Pick one or more servers to act on"/>
                                    <Popup x:Name="PopTargetService" StaysOpen="False" Placement="Bottom" PlacementTarget="{Binding ElementName=BtnTargetService}" IsOpen="{Binding IsChecked, ElementName=BtnTargetService, Mode=TwoWay}">
                                        <Border Background="White" BorderBrush="{StaticResource BorderBrush}" BorderThickness="1" CornerRadius="6" Padding="8" Margin="0,2,0,0">
                                            <ScrollViewer MaxHeight="240" VerticalScrollBarVisibility="Auto"><StackPanel x:Name="PnlTargetService" MinWidth="200"/></ScrollViewer>
                                        </Border>
                                    </Popup>
                                    <Button x:Name="BtnRefreshServices" Content="Refresh" Style="{StaticResource SecondaryButtonStyle}" MinWidth="80"/>
                                </StackPanel>
                                <Grid Margin="12">
                                    <Grid.ColumnDefinitions>
                                        <ColumnDefinition Width="135"/>
                                        <ColumnDefinition Width="*"/>
                                    </Grid.ColumnDefinitions>
                                    <Grid.RowDefinitions>
                                        <RowDefinition Height="Auto"/>
                                        <RowDefinition Height="Auto"/>
                                        <RowDefinition Height="Auto"/>
                                        <RowDefinition Height="Auto"/>
                                    </Grid.RowDefinitions>

                                    <TextBlock Grid.Row="0" Text="Services:" VerticalAlignment="Top" Margin="0,6,0,0"/>
                                    <StackPanel Grid.Row="0" Grid.Column="1" Margin="5" HorizontalAlignment="Left" Width="430">
                                        <StackPanel Orientation="Horizontal" Margin="0,0,0,4">
                                            <TextBlock Text="Find:" VerticalAlignment="Center" Margin="0,0,6,0"/>
                                            <TextBox x:Name="TxtServiceSearch" Width="150" VerticalAlignment="Center"
                                                     ToolTip="Type to filter the service list by name"/>
                                            <Button x:Name="BtnSvcSelectAll" Content="Select all" Style="{StaticResource SecondaryButtonStyle}" MinWidth="80"
                                                    ToolTip="Tick all services currently shown"/>
                                            <Button x:Name="BtnSvcDeselectAll" Content="Deselect all" Style="{StaticResource SecondaryButtonStyle}" MinWidth="80"
                                                    ToolTip="Untick all services currently shown"/>
                                        </StackPanel>
                                        <Border BorderBrush="{StaticResource BorderBrush}" BorderThickness="1"
                                                CornerRadius="4" Background="White" MinHeight="90">
                                            <ScrollViewer VerticalScrollBarVisibility="Auto" MaxHeight="150">
                                                <StackPanel x:Name="SvcCheckPanel" Margin="8"/>
                                            </ScrollViewer>
                                        </Border>
                                    </StackPanel>

                                    <TextBlock Grid.Row="1" Text="Action:"/>
                                    <ComboBox x:Name="CmbServiceAction" Grid.Row="1" Grid.Column="1" Width="200" HorizontalAlignment="Left">
                                        <ComboBoxItem Content="Restart" IsSelected="True"/>
                                        <ComboBoxItem Content="Stop"/>
                                    </ComboBox>

                                    <StackPanel Grid.Row="2" Grid.ColumnSpan="2" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,8,0,0">
                                        <Button x:Name="BtnServiceStatus" Content="Check Service Status" Style="{StaticResource SecondaryButtonStyle}"/>
                                        <Button x:Name="BtnServiceDetails" Content="Check Details (version)" Style="{StaticResource SecondaryButtonStyle}"
                                                ToolTip="Show the installed package name/version and status for the selected service"/>
                                    </StackPanel>
                                    <Button x:Name="BtnServiceAction" Grid.Row="3" Grid.ColumnSpan="2"
                                            Content="Start / Restart / Stop Service" Style="{StaticResource PrimaryButtonStyle}"
                                            HorizontalAlignment="Right" Margin="0,4,0,0"/>
                                </Grid>
                              </StackPanel>
                            </GroupBox>
                        </Grid>
                    </ScrollViewer>
                </TabItem>

                <!-- Certificates tab - deploy a certificate file to the server(s) -->
                <TabItem x:Name="TabMetrics" Header="Metrics">
                    <Grid Margin="12">
                        <Grid.RowDefinitions>
                            <RowDefinition Height="Auto"/>
                            <RowDefinition Height="Auto"/>
                            <RowDefinition Height="*"/>
                        </Grid.RowDefinitions>

                        <StackPanel Grid.Row="0" Orientation="Horizontal" Margin="2,0,2,6">
                            <TextBlock Text="Activity Metrics" FontSize="14" FontWeight="Bold" Foreground="{StaticResource PrimaryDarkBrush}" VerticalAlignment="Center" Margin="0,0,14,0"/>
                            <CheckBox x:Name="ChkCaptureMetrics" Style="{StaticResource ToggleSwitchStyle}" Content="Record efficiency metrics" VerticalAlignment="Center" Margin="0,0,14,0"
                                      ToolTip="When ON, each completed activity records its clicks, distinct fields edited and elapsed time. When OFF, nothing is captured."/>
                            <Button x:Name="BtnExportMetrics" Content="Export CSV" Style="{StaticResource SecondaryButtonStyle}"/>
                            <Button x:Name="BtnClearMetrics" Content="Clear" Style="{StaticResource DangerButtonStyle}"/>
                        </StackPanel>

                        <Border Grid.Row="1" Background="#EEF2F7" CornerRadius="6" Padding="10,6" Margin="2,0,2,6">
                            <TextBlock x:Name="TxtActivitySummary" Text="No activities recorded yet." FontWeight="SemiBold" Foreground="{StaticResource PrimaryDarkBrush}" TextWrapping="Wrap"/>
                        </Border>

                        <DataGrid x:Name="ActivityGrid" Grid.Row="2"
                                  AutoGenerateColumns="False" CanUserAddRows="False" CanUserDeleteRows="False"
                                  IsReadOnly="True" HeadersVisibility="Column" GridLinesVisibility="Horizontal"
                                  Background="White" RowBackground="White" AlternatingRowBackground="#F8FAFC"
                                  BorderBrush="{StaticResource BorderBrush}" BorderThickness="1" FontWeight="Normal">
                            <DataGrid.Columns>
                                <DataGridTextColumn Header="Time started" Binding="{Binding Time}" Width="1*"/>
                                <DataGridTextColumn Header="Activity" Binding="{Binding Activity}" Width="2*"/>
                                <DataGridTextColumn Header="Target server" Binding="{Binding Target}" Width="1.5*"/>
                                <DataGridTextColumn Header="Mouse clicks" Binding="{Binding Clicks}" Width="1*"/>
                                <DataGridTextColumn Header="Fields edited" Binding="{Binding Inputs}" Width="1*"/>
                                <DataGridTextColumn Header="Active time (s)" Binding="{Binding ActivitySeconds}" Width="1.3*"/>
                                <DataGridTextColumn Header="Server op (s)" Binding="{Binding OperationSeconds}" Width="1.2*"/>
                                <DataGridTextColumn Header="Outcome" Binding="{Binding Outcome}" Width="1*"/>
                            </DataGrid.Columns>
                        </DataGrid>
                    </Grid>
                </TabItem>
            </TabControl>
        </Grid>

        <!-- Activity log -->
        <GroupBox
            Grid.Row="2"
            Header="Activity Log"
            Height="450"
            Margin="18,8,18,14">

            <Grid Margin="8">

                <Grid.RowDefinitions>
                    <RowDefinition Height="*"/>
                    <RowDefinition Height="Auto"/>
                </Grid.RowDefinitions>

                <TextBox
                    x:Name="TxtLog"
                    Grid.Row="0"
                    MinHeight="330"
                    VerticalContentAlignment="Top"
                    IsReadOnly="True"
                    AcceptsReturn="True"
                    VerticalScrollBarVisibility="Auto"
                    HorizontalScrollBarVisibility="Auto"
                    FontFamily="Consolas"
                    FontSize="12"
                    TextWrapping="NoWrap"
                    Background="#111827"
                    Foreground="#D1FAE5"
                    BorderThickness="0"/>

                <StackPanel
                    Grid.Row="1"
                    Orientation="Horizontal"
                    HorizontalAlignment="Right">

                    <Button
                        x:Name="BtnClearLog"
                        Content="Clear Log"
                        Style="{StaticResource SecondaryButtonStyle}"/>

                    <Button
                        x:Name="BtnOpenLog"
                        Content="Open Log File"
                        Style="{StaticResource PrimaryButtonStyle}"/>
                </StackPanel>
            </Grid>
        </GroupBox>
        </Grid>
        </ScrollViewer>

				<!-- Footer -->
		<Border
			Grid.Row="2"
			Background="#1E293B"
			BorderThickness="0,1,0,0"
			BorderBrush="#CBD5E1">

			<Grid Margin="12,0">

				<Grid.ColumnDefinitions>
					<ColumnDefinition Width="*"/>
					<ColumnDefinition Width="Auto"/>
					<ColumnDefinition Width="Auto"/>
					<ColumnDefinition Width="Auto"/>
				</Grid.ColumnDefinitions>

				<StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center">
					<TextBlock
						VerticalAlignment="Center"
						Foreground="White"
						FontSize="12"
						FontWeight="SemiBold"
						x:Name="TxtAppFooter" Text="Foreman &#183; Aristocrat Customer Success"/>
					<Button x:Name="BtnUnlockMetrics" Content="Efficiency Recorder" Style="{StaticResource FooterButtonStyle}" Margin="16,0,0,0"
						ToolTip="Open the Efficiency Recorder (capture and report usage metrics)"/>
					<Button x:Name="BtnLogFolder" Content="Change Log Folder" Style="{StaticResource FooterButtonStyle}"
						ToolTip="Choose where log files are saved. Foreman remembers this the next time you open it."/>
					<Button x:Name="BtnResetTool" Content="Reset Tool" Style="{StaticResource FooterButtonStyle}"
						ToolTip="If Foreman has been left open a long time and starts acting up (stuck buttons, a connection that never responds), click this. It clears stuck internal state and every server connection - WITHOUT closing Foreman or losing your server list, settings, or package plan. Click Connect All afterwards."/>
				</StackPanel>

				<TextBlock
					Grid.Column="1"
					Margin="30,0"
					VerticalAlignment="Center"
					Foreground="#E2E8F0"
					FontSize="12"
					Text="Version : 1.1.0"/>

				<TextBlock
					Grid.Column="2"
					Margin="30,0"
					VerticalAlignment="Center"
					Foreground="#E2E8F0"
					FontSize="12"
					Text="Latest Update : 02-Sep-2026"/>

				<TextBlock
					x:Name="TxtActivityHud"
					Grid.Column="3"
					Margin="30,0"
					VerticalAlignment="Center"
					Foreground="#22C55E"
					FontWeight="Bold"
					FontSize="12"
					Text="Ready"/>

			</Grid>

		</Border>
    </Grid>
</Window>
'@

# ============================================================================
#  EMBEDDED MODULE: ConfigManager  (was Modules\ConfigManager.psm1)
# ============================================================================

function Get-JsonConfiguration {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Path
    )

    if (-not (Test-Path -LiteralPath $Path)) {
        throw "Configuration file was not found: $Path"
    }

    try {
        return Get-Content -LiteralPath $Path -Raw -Encoding UTF8 | ConvertFrom-Json
    }
    catch {
        throw "Unable to read JSON configuration '$Path'. $($_.Exception.Message)"
    }
}

# Standalone loader: prefer an external file beside the EXE, otherwise use the
# embedded default JSON that ships inside this script.
function Get-OneLinkConfiguration {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$ExternalPath,
        [Parameter(Mandatory)][string]$DefaultJson
    )

    if (Test-Path -LiteralPath $ExternalPath -PathType Leaf) {
        try {
            return Get-Content -LiteralPath $ExternalPath -Raw -Encoding UTF8 | ConvertFrom-Json
        }
        catch {
            throw "Unable to read external JSON configuration '$ExternalPath'. $($_.Exception.Message)"
        }
    }

    return $DefaultJson | ConvertFrom-Json
}

# ============================================================================
#  EMBEDDED MODULE: Logger  (was Modules\Logger.psm1)
# ============================================================================

$script:LogFile = $null
$script:LogCallback = $null

function Initialize-OneLinkLogger {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Directory,

        [scriptblock]$GuiCallback
    )

    if (-not (Test-Path -LiteralPath $Directory)) {
        New-Item -Path $Directory -ItemType Directory -Force | Out-Null
    }

    $script:LogFile = Join-Path $Directory ("OneLinkAdminTool_{0}.log" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
    $script:LogCallback = $GuiCallback
    New-Item -Path $script:LogFile -ItemType File -Force | Out-Null
    return $script:LogFile
}

# ----------------------------------------------------------------------------
#  Persisted user preferences (survive EXE restarts). Stored as a small JSON
#  file in the per-user app folder (%LOCALAPPDATA%\OneLinkAdminTool) - no extra
#  dependency, keeps the tool a standalone EXE. Currently remembers the chosen
#  log folder.
# ----------------------------------------------------------------------------
function Get-OneLinkPrefsPath {
    return (Join-Path $env:LOCALAPPDATA 'OneLinkAdminTool\preferences.json')
}

function Get-OneLinkPrefs {
    $p = Get-OneLinkPrefsPath
    if (Test-Path -LiteralPath $p) {
        try { return (Get-Content -LiteralPath $p -Raw -ErrorAction Stop | ConvertFrom-Json) } catch { }
    }
    return $null
}

function Save-OneLinkPref {
    param([Parameter(Mandatory)][string]$Name, [string]$Value)
    try {
        $p = Get-OneLinkPrefsPath
        $dir = Split-Path -Parent $p
        if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        $obj = Get-OneLinkPrefs
        if ($null -eq $obj) { $obj = [pscustomobject]@{} }
        $obj | Add-Member -NotePropertyName $Name -NotePropertyValue $Value -Force
        $obj | ConvertTo-Json | Set-Content -LiteralPath $p -Encoding UTF8
        return $true
    }
    catch { return $false }
}

function Protect-LogText {
    [CmdletBinding()]
    param([AllowNull()][string]$Message)

    if ($null -eq $Message) { return "" }

    $protected = $Message
    $protected = $protected -replace '(?i)(password\s*[:=]\s*)\S+', '$1********'
    $protected = $protected -replace '(?i)(passwd\s*[:=]\s*)\S+', '$1********'
    return $protected
}

function Write-OneLinkLog {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Message,

        [ValidateSet('Debug','Info','Warning','Error','Success')]
        [string]$Level = 'Info'
    )

    $safeMessage = Protect-LogText -Message $Message
    $line = "{0} [{1}] {2}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Level.ToUpperInvariant(), $safeMessage

    if ($script:LogFile) {
        Add-Content -LiteralPath $script:LogFile -Value $line -Encoding UTF8
    }

    if ($script:LogCallback) {
        & $script:LogCallback $line
    }
}

function Get-OneLinkLogFile {
    return $script:LogFile
}

# ----------------------------------------------------------------------------
#  Efficiency log: a separate CSV-style log recording each operation's target,
#  start time, end time, duration and outcome. No secrets are written (only the
#  operation name and target host). Used to see how long installs/uploads/etc.
#  take.
# ----------------------------------------------------------------------------
$script:EfficiencyLogFile = $null

function Initialize-OneLinkEfficiencyLog {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$Directory)

    if (-not (Test-Path -LiteralPath $Directory)) {
        New-Item -Path $Directory -ItemType Directory -Force | Out-Null
    }
    $script:EfficiencyLogFile = Join-Path $Directory ("OneLinkAdminTool_efficiency_{0}.csv" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
    if (-not (Test-Path -LiteralPath $script:EfficiencyLogFile)) {
        Add-Content -LiteralPath $script:EfficiencyLogFile -Value 'Operation,Target,Outcome,StartTime,EndTime,DurationSeconds' -Encoding UTF8
    }
    return $script:EfficiencyLogFile
}

# Records one operation's timing. $Target is a host or 'all'; never a secret.
function Write-OneLinkEfficiency {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$Operation,
        [Parameter(Mandatory)][string]$Target,
        [Parameter(Mandatory)][string]$Outcome,
        [Parameter(Mandatory)][datetime]$Start,
        [Parameter(Mandatory)][datetime]$End
    )

    $duration = [math]::Round(($End - $Start).TotalSeconds, 2)
    $csvField = {
        param($v)
        $s = [string]$v
        if ($s -match '[",\r\n]') { '"' + ($s -replace '"', '""') + '"' } else { $s }
    }
    $line = @(
        (& $csvField (Protect-LogText -Message $Operation)),
        (& $csvField $Target),
        (& $csvField $Outcome),
        (& $csvField ($Start.ToString('yyyy-MM-dd HH:mm:ss'))),
        (& $csvField ($End.ToString('yyyy-MM-dd HH:mm:ss'))),
        $duration
    ) -join ','

    if ($script:EfficiencyLogFile) {
        Add-Content -LiteralPath $script:EfficiencyLogFile -Value $line -Encoding UTF8
    }
    Write-OneLinkLog ("[timing] {0} on {1}: {2} in {3}s" -f $Operation, $Target, $Outcome, $duration) -Level Debug
}

# ----------------------------------------------------------------------------
#  Activity metrics: how many CLICKS + distinct FIELDS a user task took, and how
#  long (wall-clock) from the previous completed activity to this one. Captured
#  automatically; shown live in the footer and in the Activity Metrics tab.
# ----------------------------------------------------------------------------
$script:ActClicks = 0                 # running window click count (PreviewMouseDown)
$script:ActBoundaryClicks = 0         # click count when the current activity segment began
$script:ActBoundaryTime = Get-Date    # when the current activity segment began
$script:ActTouchedFields = New-Object 'System.Collections.Generic.HashSet[string]'  # distinct fields edited this segment
$script:ActivityMetrics = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
$script:MetricsLogFile = $null
$script:ActCaptureEnabled = $false    # toggled by the "Record efficiency metrics" checkbox
# Active-time tracking: only count time while the user is actually working. Any
# gap longer than the idle threshold between interactions is treated as idle and
# is NOT added to the activity's time.
$script:ActActiveSeconds = 0.0
$script:ActLastInteraction = Get-Date
$script:ActIdleThresholdSeconds = 30

# Accumulate active time between interactions (excluding idle gaps). Called on
# every click and field edit while capture is on.
function Register-OneLinkInteraction {
    if (-not $script:ActCaptureEnabled) { return }
    $now = Get-Date
    $gap = ($now - $script:ActLastInteraction).TotalSeconds
    if ($gap -ge 0 -and $gap -le $script:ActIdleThresholdSeconds) { $script:ActActiveSeconds += $gap }
    $script:ActLastInteraction = $now
}

function Initialize-OneLinkMetricsLog {
    param([Parameter(Mandatory)][string]$Directory)
    if (-not (Test-Path -LiteralPath $Directory)) { New-Item -Path $Directory -ItemType Directory -Force | Out-Null }
    $script:MetricsLogFile = Join-Path $Directory ("OneLinkAdminTool_activity_{0}.csv" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
    if (-not (Test-Path -LiteralPath $script:MetricsLogFile)) {
        Add-Content -LiteralPath $script:MetricsLogFile -Value 'Time,Activity,Target,Outcome,Clicks,InputsEdited,ActivitySeconds,OperationSeconds' -Encoding UTF8
    }
    return $script:MetricsLogFile
}

# Reset the activity segment (called after each completed activity, so the next
# activity's clicks/fields/time start fresh).
function Reset-OneLinkActivitySegment {
    $script:ActBoundaryClicks = $script:ActClicks
    $script:ActBoundaryTime = Get-Date
    $script:ActTouchedFields.Clear()
    $script:ActActiveSeconds = 0.0
    $script:ActLastInteraction = Get-Date
}

# Record one completed activity: clicks + distinct fields + wall-clock time since
# the previous activity, then reset the segment. Safe to call on the UI thread.
function Complete-OneLinkActivity {
    param(
        [Parameter(Mandatory)][string]$Name,
        [string]$Target = '',
        [string]$Outcome = 'Success',
        [double]$OperationSeconds = 0,
        [hashtable]$Context = $null
    )
    # Only record when the user has switched capture on.
    if (-not $script:ActCaptureEnabled) { return }
    $now = Get-Date
    $clicks = [math]::Max(0, $script:ActClicks - $script:ActBoundaryClicks)
    $inputs = $script:ActTouchedFields.Count
    if ($Context) {
        if ($Context.ContainsKey('Frozen') -and $Context.Frozen -and $Context.Generation -ne $script:ActCaptureGeneration) { return }
        if ($Context.Generation -ne $script:ActCaptureGeneration) { Reset-OneLinkRecorderContext $Context }
        $clicks = $Context.Clicks
        $inputs = $Context.Fields.Count
    }
    # Active (hands-on) time only: form-filling active gaps (idle excluded) plus
    # the operation's own run time. Idle time between activities is NOT counted.
    $actSecs = [math]::Round($script:ActActiveSeconds + $OperationSeconds, 2)
    if ($Context) { $actSecs = [math]::Round($Context.ActiveSeconds + $OperationSeconds, 2) }

    $m = [OlActivityMetric]::new()
    $m.Time = $now.ToString('HH:mm:ss')
    $m.Activity = $Name
    $m.Target = $Target
    $m.Outcome = $Outcome
    $m.Clicks = $clicks
    $m.Inputs = $inputs
    $m.ActivitySeconds = $actSecs
    $m.OperationSeconds = [math]::Round($OperationSeconds, 2)
    $script:ActivityMetrics.Insert(0, $m)   # newest first

    if ($script:MetricsLogFile) {
        $q = { param($v) $s = [string]$v; if ($s -match '[",\r\n]') { '"' + ($s -replace '"', '""') + '"' } else { $s } }
        $line = @((& $q $now.ToString('yyyy-MM-dd HH:mm:ss')), (& $q (Protect-LogText -Message $Name)), (& $q $Target), (& $q $Outcome), $clicks, $inputs, $actSecs, $m.OperationSeconds) -join ','
        Add-Content -LiteralPath $script:MetricsLogFile -Value $line -Encoding UTF8
    }

    Update-OneLinkActivitySummary
    if ($Context) { Reset-OneLinkRecorderContext $Context } else { Reset-OneLinkActivitySegment }
}

# Separate counters for each auxiliary window. Only field identities are stored,
# never typed values, passwords, file contents or command text.
$script:ActCaptureGeneration = 0
function Set-OneLinkRecorderCapture {
    param([bool]$Enabled)
    if ($Enabled -and -not $script:ActCaptureEnabled) { $script:ActCaptureGeneration++; Reset-OneLinkActivitySegment }
    $script:ActCaptureEnabled = $Enabled
}

function Test-OneLinkRecorderCapture { return $script:ActCaptureEnabled }

function Reset-OneLinkRecorderContext {
    param([hashtable]$Context)
    $Context.Clicks = 0
    $Context.Fields = New-Object 'System.Collections.Generic.HashSet[string]'
    $Context.ActiveSeconds = 0.0
    $Context.Last = Get-Date
    $Context.Generation = $script:ActCaptureGeneration
}

function Register-OneLinkRecorderEvent {
    param([hashtable]$Context, [switch]$Click, [string]$Field = '')
    if (-not $script:ActCaptureEnabled) { return }
    if ($Context.Generation -ne $script:ActCaptureGeneration) { Reset-OneLinkRecorderContext $Context }
    $now = Get-Date
    $gap = ($now - $Context.Last).TotalSeconds
    if ($gap -ge 0 -and $gap -le $script:ActIdleThresholdSeconds) { $Context.ActiveSeconds += $gap }
    $Context.Last = $now
    if ($Click) { $Context.Clicks++ }
    if ($Field) { [void]$Context.Fields.Add($Field) }
}

function Start-OneLinkRecordedOperation {
    param([hashtable]$Context)
    if ($Context.Generation -ne $script:ActCaptureGeneration) { Reset-OneLinkRecorderContext $Context }
    $snapshot = @{
        Clicks = $Context.Clicks; Fields = $Context.Fields; ActiveSeconds = $Context.ActiveSeconds
        Generation = $Context.Generation; Frozen = $true; Started = Get-Date
    }
    Reset-OneLinkRecorderContext $Context
    return $snapshot
}

function Enable-OneLinkWindowRecorder {
    param($Window)
    $context = @{}
    Reset-OneLinkRecorderContext $context
    if ($script:ActCaptureEnabled) {
        $context.Clicks = [math]::Max(0, $script:ActClicks - $script:ActBoundaryClicks)
        $context.ActiveSeconds = $script:ActActiveSeconds
        foreach ($field in $script:ActTouchedFields) { [void]$context.Fields.Add($field) }
        Reset-OneLinkActivitySegment
    }
    $Window.Add_PreviewMouseDown({ Register-OneLinkRecorderEvent -Context $context -Click }.GetNewClosure())
    $Window.Add_PreviewKeyDown({ Register-OneLinkRecorderEvent -Context $context }.GetNewClosure())
    $touch = {
        param($sender, $eventArgs)
        $control = $eventArgs.OriginalSource
        if ($control -and $control.IsKeyboardFocusWithin) {
            Register-OneLinkRecorderEvent -Context $context -Field ([string]$control.GetHashCode())
        }
    }.GetNewClosure()
    $Window.AddHandler([System.Windows.Controls.Primitives.TextBoxBase]::TextChangedEvent, [System.Windows.Controls.TextChangedEventHandler]$touch)
    $Window.AddHandler([System.Windows.Controls.PasswordBox]::PasswordChangedEvent, [System.Windows.RoutedEventHandler]$touch)
    $Window.AddHandler([System.Windows.Controls.Primitives.Selector]::SelectionChangedEvent, [System.Windows.Controls.SelectionChangedEventHandler]$touch)
    $Window.AddHandler([System.Windows.Controls.Primitives.ToggleButton]::CheckedEvent, [System.Windows.RoutedEventHandler]$touch)
    $Window.AddHandler([System.Windows.Controls.Primitives.ToggleButton]::UncheckedEvent, [System.Windows.RoutedEventHandler]$touch)
    return $context
}

function Update-OneLinkConsoleRecording {
    param([hashtable]$State, [string]$Chunk = '', [switch]$Closing)
    $State.Buffer += $Chunk
    foreach ($pending in @($State.Pending.ToArray())) {
        $match = [regex]::Match($State.Buffer, ([regex]::Escape($pending.Token) + ':(\d+)\r?\n'))
        if ($match.Success -or $Closing -or ((Get-Date) - $pending.Context.Started).TotalSeconds -ge $State.Timeout) {
            $outcome = if ($match.Success) { if ([int]$match.Groups[1].Value -eq 0) { 'Success' } else { 'Failed' } } else { 'Unknown' }
            Complete-OneLinkActivity -Name 'SSH Command' -Target $pending.Host -Outcome $outcome -OperationSeconds (((Get-Date) - $pending.Context.Started).TotalSeconds) -Context $pending.Context
            [void]$State.Pending.Remove($pending)
        }
    }
    # Hide the instrumentation's echoed printf line and completion marker.
    $State.Buffer = $State.Buffer -replace '(?m)^.*printf.*OLK_METRIC_[a-f0-9]+.*\r?\n', ''
    $State.Buffer = $State.Buffer -replace 'OLK_METRIC_[a-f0-9]+:\d+\r?\n', ''
    $end = $State.Buffer.LastIndexOf("`n") + 1
    if ($State.Pending.Count -eq 0) { $end = $State.Buffer.Length }
    if ($end -gt 0) {
        $display = $State.Buffer.Substring(0, $end)
        $State.Buffer = $State.Buffer.Substring($end)
        return $display
    }
}

# Refresh the Activity Metrics summary line (totals + averages).
function Update-OneLinkActivitySummary {
    if (-not $script:TxtActivitySummary) { return }
    $n = $script:ActivityMetrics.Count
    if ($n -eq 0) { $script:TxtActivitySummary.Text = 'No activities recorded yet.'; return }
    $totClicks = ($script:ActivityMetrics | Measure-Object -Property Clicks -Sum).Sum
    $totInputs = ($script:ActivityMetrics | Measure-Object -Property Inputs -Sum).Sum
    $totSecs = ($script:ActivityMetrics | Measure-Object -Property ActivitySeconds -Sum).Sum
    $avgActions = [math]::Round(($totClicks + $totInputs) / $n, 1)
    $mins = [math]::Floor($totSecs / 60); $secs = [int]($totSecs % 60)
    $script:TxtActivitySummary.Text = ("Activities: {0}   |   Total time: {1}m {2}s   |   Clicks: {3}   |   Fields: {4}   |   Avg actions/activity: {5}" -f `
        $n, $mins, $secs, $totClicks, $totInputs, $avgActions)
}

# Efficiency panel (opened from the footer diamond - no sign-in). Start/stop
# capturing, open the Metrics tab, and export the report. Capturing counts only
# ACTIVE work; idle time (no interaction for over the threshold) is not counted.
function Show-OneLinkCaptureDialog {
    $win = New-Object System.Windows.Window
    $win.Title = 'Efficiency metrics'
    $win.SizeToContent = 'WidthAndHeight'; $win.WindowStartupLocation = 'CenterScreen'; $win.ResizeMode = 'NoResize'; $win.MinWidth = 380
    $win.WindowStyle = 'SingleBorderWindow'
    if ($script:Window) { $win.Owner = $script:Window }
    $sp = New-Object System.Windows.Controls.StackPanel; $sp.Margin = '16'
    $status = New-Object System.Windows.Controls.TextBlock; $status.TextWrapping = 'Wrap'; $status.Margin = '0,0,0,14'; $status.MaxWidth = 360
    $status.Text = if ($script:ActCaptureEnabled) {
        "Capturing is ON. Each completed action records its clicks, fields and ACTIVE time (idle time is not counted). Results appear on the Metrics tab."
    } else {
        "Capturing is OFF. Start it to record each action's clicks, fields and ACTIVE time. Idle time (no interaction for over $($script:ActIdleThresholdSeconds)s) is not counted."
    }
    $mk = {
        param($text)
        $b = New-Object System.Windows.Controls.Button
        $b.Content = $text; $b.Height = 30; $b.Margin = '0,0,0,8'; $b.HorizontalContentAlignment = 'Center'
        return $b
    }
    $toggleText = 'Start capturing'; if ($script:ActCaptureEnabled) { $toggleText = 'Stop capturing' }
    $toggle = & $mk $toggleText
    $openTab = & $mk 'Open Metrics tab'
    $export = & $mk 'Export report (CSV)'
    $close = New-Object System.Windows.Controls.Button; $close.Content = 'Close'; $close.Height = 30; $close.HorizontalAlignment = 'Right'; $close.Width = 90; $close.IsCancel = $true

    $revealTab = { $TabMetrics.Visibility = [System.Windows.Visibility]::Visible; $TabMetrics.IsSelected = $true }

    $toggle.Add_Click({
        if (Test-OneLinkRecorderCapture) {
            Set-OneLinkRecorderCapture $false
            $ChkCaptureMetrics.IsChecked = $false
            Write-OneLinkLog "Efficiency capture stopped." -Level Info
        }
        else {
            Set-OneLinkRecorderCapture $true
            $ChkCaptureMetrics.IsChecked = $true
            Reset-OneLinkActivitySegment
            & $revealTab
            Write-OneLinkLog "Efficiency capture STARTED (active time only)." -Level Success
        }
        $win.Close()
    }.GetNewClosure())
    $openTab.Add_Click({ & $revealTab; $win.Close() }.GetNewClosure())
    $export.Add_Click({ Export-OneLinkActivityMetrics }.GetNewClosure())
    $close.Add_Click({ $win.Close() }.GetNewClosure())

    foreach ($el in @($status, $toggle, $openTab, $export, $close)) { [void]$sp.Children.Add($el) }
    $win.Content = $sp; [void]$win.ShowDialog()
}

# ============================================================================
#  EMBEDDED MODULE: SshManager  (was Modules\SshManager.psm1)
# ============================================================================

function New-OneLinkCredential {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$Username,
        [Parameter(Mandatory)][System.Security.SecureString]$Password
    )

    return [PSCredential]::new($Username, $Password)
}

function Connect-OneLinkSsh {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [Parameter(Mandatory)][int]$Port,
        [Parameter(Mandatory)][PSCredential]$Credential,
        [Parameter(Mandatory)]$Settings
    )

    Import-OneLinkPoshSsh

    $params = @{
        ComputerName = $ComputerName
        Port = $Port
        Credential = $Credential
        ConnectionTimeout = [int]$Settings.Ssh.ConnectionTimeoutSeconds
        ErrorAction = 'Stop'
    }

    if ([bool]$Settings.Ssh.AcceptNewHostKey) {
        $params.AcceptKey = $true
    }

    try {
        return New-SSHSession @params
    }
    catch {
        # A rebuilt server presents a NEW SSH host key. Posh-SSH's -AcceptKey
        # trusts a brand-new host automatically, but REJECTS a *changed* key -
        # which SSH.NET reports as the misleading "Key exchange negotiation
        # failed". When we already have a stored key for this host AND the
        # failure looks like a host-key/KEX rejection, the server was almost
        # certainly rebuilt: refresh the stored key (the tool's equivalent of
        # 'ssh-keygen -R <host>') and retry ONCE. Auth/network errors do NOT
        # match this, so a wrong password never causes a key to be re-trusted.
        $trustChanged = [bool](Get-OneLinkProperty -Object $Settings.Ssh -Name 'TrustChangedHostKey' -Default $true)
        $cat = (Get-OneLinkFriendlySshError $_.Exception.Message).Category
        $hasStored = $false
        try { $hasStored = @(Get-SSHTrustedHost -HostName $ComputerName -ErrorAction SilentlyContinue).Count -gt 0 } catch { }
        if ($trustChanged -and $hasStored -and ($cat -eq 'KeyExchange' -or $cat -eq 'HostKey')) {
            Write-OneLinkLog "[$ComputerName] The server's SSH host key has changed since it was last trusted (the server was likely rebuilt). Refreshing the stored key and retrying." -Level Warning
            try { Remove-SSHTrustedHost -HostName $ComputerName -ErrorAction SilentlyContinue | Out-Null } catch { }
            return New-SSHSession @params
        }
        throw
    }
}

function Test-OneLinkSshConnection {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [int]$TimeoutSeconds = 20
    )

    $result = Invoke-SSHCommand -SessionId $Session.SessionId `
        -Command "printf 'CONNECTED|'; hostname; printf '|'; id -un; printf '|'; uname -srm" `
        -TimeOut $TimeoutSeconds

    if ($result.ExitStatus -ne 0) {
        throw "SSH validation failed: $($result.Error -join [Environment]::NewLine)"
    }

    return ($result.Output -join [Environment]::NewLine)
}

# Turn a raw SSH/network exception into a short, plain-language reason a
# non-technical user can act on. Returns @{ Short = <grid status text>;
# Hint = <one-line suggestion for the log> }. Unknown errors pass through as-is.
function Get-OneLinkFriendlySshError {
    [CmdletBinding()]
    param([string]$Message)

    $m = [string]$Message
    switch -Regex ($m) {
        'key exchange|\bkex\b|negotiat' {
            return @{
                Category = 'KeyExchange'
                Short = 'incompatible SSH security settings (key exchange).'
                Hint  = "This usually means the server's SSH host key changed (e.g. it was rebuilt) and the old key is still trusted, OR the server offers handshake algorithms this tool's SSH library doesn't support. It is NOT a wrong-password issue and is unrelated to the Windows known_hosts file."
            }
        }
        'host key|hostkey|known.?host|fingerprint|server.?identif' {
            return @{
                Category = 'HostKey'
                Short = "server identity (host key) changed or rejected."
                Hint  = "The server's SSH host key has changed since it was last trusted (e.g. the box was rebuilt). If you trust this server, disconnect and reconnect to accept the new key."
            }
        }
        'denied|authenticat|permission|bad password|wrong password|credential|logon|login failed' {
            return @{
                Category = 'Auth'
                Short = 'username or password not accepted.'
                Hint  = 'Check the Username and Password cells for this row.'
            }
        }
        'timed out|timeout|actively refused|connection refused|unreachable|no such host|not known|could not resolve|no route|failed to establish' {
            return @{
                Category = 'Network'
                Short = "couldn't reach the server (check IP/host, port and network/VPN)."
                Hint  = 'Verify the server is powered on, the IP/host and port are correct, and you are on the right network/VPN.'
            }
        }
        default {
            return @{ Category = 'Other'; Short = $m; Hint = '' }
        }
    }
}

function Invoke-OneLinkSshCommand {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [Parameter(Mandatory)][string]$Command,
        [int]$TimeoutSeconds = 120
    )

    # PowerShell here-strings carry this file's CRLF line endings. Bash on the
    # remote end chokes on a stray \r (e.g. "set -o pipefail<CR>" is read as an
    # invalid option name, heredoc terminators no longer match, and identifiers
    # embedded in scripts pick up a trailing \r). Every caller of this function
    # funnels through here, so normalize once rather than at each call site.
    $lfCommand = $Command.Replace("`r`n", "`n").Replace("`r", "`n")

    $result = Invoke-SSHCommand -SessionId $Session.SessionId -Command $lfCommand -TimeOut $TimeoutSeconds

    [PSCustomObject]@{
        ExitStatus = $result.ExitStatus
        Output = ($result.Output -join [Environment]::NewLine)
        Error = ($result.Error -join [Environment]::NewLine)
    }
}

function New-OneLinkShellStream {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [Parameter(Mandatory)]$Settings
    )

    # Posh-SSH 3.x exposes the terminal size as -Columns / -Rows (character
    # grid). The Settings.Ssh.TerminalWidth / TerminalHeight values are the
    # column and row counts, so they map directly onto those parameters.
    return New-SSHShellStream `
        -SessionId $Session.SessionId `
        -TerminalName ([string]$Settings.Ssh.TerminalName) `
        -Columns ([int]$Settings.Ssh.TerminalWidth) `
        -Rows ([int]$Settings.Ssh.TerminalHeight) `
        -BufferSize ([int]$Settings.Ssh.BufferSize)
}

function Disconnect-OneLinkSsh {
    [CmdletBinding()]
    param([AllowNull()]$Session)

    if ($null -ne $Session) {
        Remove-SSHSession -SessionId $Session.SessionId | Out-Null
    }
}

# ============================================================================
#  Shared shell quoting and direct database operations.
#  Legacy service/SSL helpers below remain separate from the Database tab.
# ============================================================================

# Quote a value as a single bash argument (safe for arbitrary text/passwords).
function ConvertTo-OneLinkBashArg {
    [CmdletBinding()]
    param([AllowEmptyString()][string]$Value)
    return "'" + ($Value -replace "'", "'\''") + "'"
}

# Run an nmenu helper script over SSH with a sane PATH; throw on non-zero exit.
function Invoke-OneLinkNmenuCommand {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [Parameter(Mandatory)][string]$Command,
        [int]$TimeoutSeconds = 120
    )

    $prefixedPath = 'PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH'
    $full = "$prefixedPath; $Command"
    $result = Invoke-OneLinkSshCommand -Session $Session -Command $full -TimeoutSeconds $TimeoutSeconds

    $text = (@($result.Output, $result.Error) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join [Environment]::NewLine
    if ($result.ExitStatus -ne 0) {
        throw ("nmenu command failed (exit {0}). {1}" -f $result.ExitStatus, $text)
    }
    return $text
}

# Database operations use the installed MySQL/MariaDB clients, never nmenu.
function ConvertTo-OneLinkDatabaseIdentifier {
    param([Parameter(Mandatory)][string]$Name)
    if ([string]::IsNullOrWhiteSpace($Name) -or $Name.Length -gt 64 -or $Name -match '[\x00-\x1f\x7f/\\.]' -or $Name.EndsWith(' ')) {
        throw 'Database name must be 1-64 characters and cannot contain control characters, dots, slashes or a trailing space.'
    }
    return '`' + $Name.Replace('`', '``') + '`'
}

function ConvertTo-OneLinkSqlString {
    param([AllowEmptyString()][string]$Value)
    if ($Value -match '[\x00\r\n]') { throw 'Database account values cannot contain NUL or line breaks.' }
    # Statements execute with NO_BACKSLASH_ESCAPES in their own session.
    return "'" + $Value.Replace("'", "''") + "'"
}

function Get-OneLinkDatabaseShell {
    return @'
set -euo pipefail
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH
db_run() { if [ "$(id -u)" = 0 ]; then "$@"; else sudo -n "$@"; fi; }
mysql_client=$(command -v mysql || command -v mariadb) || { echo 'MySQL/MariaDB client is not installed.' >&2; exit 1; }
db_mysql() { db_run "$mysql_client" --protocol=SOCKET --user=root --default-character-set=utf8mb4 --binary-mode "$@"; }
'@
}

function ConvertTo-OneLinkDatabaseCommand {
    param([Parameter(Mandatory)][string]$Script)
    # Windows here-strings contain CRLF. Bash must receive LF, including heredoc
    # terminators and assignments. Transport the script as data, not shell syntax.
    $lf = $Script.Replace("`r`n", "`n").Replace("`r", "`n")
    $encoded = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($lf))
    return "printf '%s' '$encoded' | base64 --decode | bash"
}

function Invoke-OneLinkDatabaseCommand {
    param($Session, [string]$Command, [int]$TimeoutSeconds = 120, [string[]]$Secrets = @())
    $result = Invoke-OneLinkSshCommand -Session $Session -Command (ConvertTo-OneLinkDatabaseCommand $Command) -TimeoutSeconds $TimeoutSeconds
    $text = (@($result.Output, $result.Error) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join [Environment]::NewLine
    foreach ($secret in $Secrets) {
        if ($secret) { $text = $text.Replace($secret, '********').Replace($secret.Replace("'", "''"), '********') }
    }
    if ($result.ExitStatus -ne 0) {
        $hint = if ($text -match '(?i)access denied|using password|sudo:') { ' Check that the SSH account can run sudo without a prompt and that root socket login is configured for the installed database client.' } else { '' }
        throw "Database command failed (exit $($result.ExitStatus)). $text$hint"
    }
    return $text
}

function New-OneLinkMysqlSqlCommand {
    param([string]$Sql)
    $sqlText = "SET SESSION sql_mode = 'NO_BACKSLASH_ESCAPES';`n" + $Sql
    $payload = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($sqlText))
    return (Get-OneLinkDatabaseShell) + "`n" + "printf '%s' '$payload' | base64 --decode | db_mysql --batch --skip-column-names"
}

# Run an existing .sql file (already on the target server) through the MySQL
# root socket - the direct equivalent of nmenu's 'ndb_run <file>'.
function New-OneLinkSqlScriptRunCommand {
    param([string]$FilePath)
    $fileArg = ConvertTo-OneLinkBashArg $FilePath
    return (Get-OneLinkDatabaseShell) + "`n" +
        "F=$fileArg`n" +
        'if [ ! -f "$F" ]; then echo "SQL script not found on the server: $F" >&2; exit 1; fi' + "`n" +
        'db_mysql < "$F"'
}

function Invoke-OneLinkCreateDatabaseUser {
    param($Session, $Settings, [string]$Username, [string]$Password, [AllowEmptyString()][string]$AllowedIp)
    if ([string]::IsNullOrWhiteSpace($Username)) { throw 'Database username is required.' }
    if ([string]::IsNullOrEmpty($Password)) { throw 'Database password is required.' }
    $ip = if ([string]::IsNullOrWhiteSpace($AllowedIp)) { '%' } else { $AllowedIp.Trim() }
    $userStr = ConvertTo-OneLinkSqlString $Username.Trim()
    $ipStr = ConvertTo-OneLinkSqlString $ip
    $account = "$userStr@$ipStr"

    # Check BEFORE creating so an existing account is reported as such, instead
    # of silently resetting its password (the previous unconditional ALTER USER).
    $existing = @(Invoke-OneLinkMysqlQuery -Session $Session -Sql "SELECT 1 FROM mysql.user WHERE User = $userStr AND Host = $ipStr LIMIT 1;" -TimeoutSeconds ([int]$Settings.Ssh.CommandTimeoutSeconds))
    if ($existing.Count -gt 0) {
        return "Database user $account already exists. No changes made (use Grant Admin Privileges' optional password field to reset it)."
    }

    $secret = ConvertTo-OneLinkSqlString $Password
    $sql = "CREATE USER IF NOT EXISTS $account IDENTIFIED BY $secret;"
    Invoke-OneLinkDatabaseCommand -Session $Session -Command (New-OneLinkMysqlSqlCommand $sql) -TimeoutSeconds ([int]$Settings.Ssh.CommandTimeoutSeconds) -Secrets @($Password) | Out-Null
    return "Database user $account created."
}

function Invoke-OneLinkCreateDatabase {
    param($Session, $Settings, [string]$DatabaseName)
    $identifier = ConvertTo-OneLinkDatabaseIdentifier $DatabaseName
    $nameStr = ConvertTo-OneLinkSqlString $DatabaseName

    $existing = @(Invoke-OneLinkMysqlQuery -Session $Session -Sql "SELECT 1 FROM information_schema.SCHEMATA WHERE SCHEMA_NAME = $nameStr LIMIT 1;" -TimeoutSeconds ([int]$Settings.Ssh.CommandTimeoutSeconds))
    if ($existing.Count -gt 0) {
        return "Database '$DatabaseName' already exists. No changes made."
    }

    Invoke-OneLinkDatabaseCommand -Session $Session -Command (New-OneLinkMysqlSqlCommand "CREATE DATABASE IF NOT EXISTS $identifier;") -TimeoutSeconds ([int]$Settings.Ssh.CommandTimeoutSeconds) | Out-Null
    return "Database '$DatabaseName' created."
}

function Invoke-OneLinkGrantPrivileges {
    param($Session, $Settings, [string]$Username, [AllowEmptyString()][string]$AllowedIp, [string]$DatabaseName, [AllowEmptyString()][string]$Password)
    if ([string]::IsNullOrWhiteSpace($Username)) { throw 'Database username is required.' }
    $identifier = ConvertTo-OneLinkDatabaseIdentifier $DatabaseName
    $ip = if ([string]::IsNullOrWhiteSpace($AllowedIp)) { '%' } else { $AllowedIp.Trim() }
    $userStr = ConvertTo-OneLinkSqlString $Username.Trim()
    $ipStr = ConvertTo-OneLinkSqlString $ip
    $account = "$userStr@$ipStr"

    $existing = @(Invoke-OneLinkMysqlQuery -Session $Session -Sql "SELECT 1 FROM mysql.user WHERE User = $userStr AND Host = $ipStr LIMIT 1;" -TimeoutSeconds ([int]$Settings.Ssh.CommandTimeoutSeconds))
    $userExisted = $existing.Count -gt 0

    # MySQL 8 no longer creates the user implicitly on GRANT - fail with a clear
    # reason up front rather than letting a raw SQL error bubble up.
    if (-not $userExisted -and [string]::IsNullOrEmpty($Password)) {
        throw "Database user $account does not exist yet. Enter a password to create the account as part of this grant, or create the user first via 'Create DB User'."
    }

    $sql = ''
    $passwordNote = ''
    if (-not [string]::IsNullOrEmpty($Password)) {
        $secret = ConvertTo-OneLinkSqlString $Password
        $sql = "CREATE USER IF NOT EXISTS $account IDENTIFIED BY $secret;`nALTER USER $account IDENTIFIED BY $secret;`n"
        $passwordNote = if ($userExisted) { ' (existing account - password updated)' } else { ' (new account created)' }
    }
    $sql += "GRANT ALL PRIVILEGES ON $identifier.* TO $account;"
    Invoke-OneLinkDatabaseCommand -Session $Session -Command (New-OneLinkMysqlSqlCommand $sql) -TimeoutSeconds ([int]$Settings.Ssh.CommandTimeoutSeconds) -Secrets @($Password) | Out-Null
    return "Granted privileges on '$DatabaseName' to $account$passwordNote."
}

# Both synchronous helpers and background transfer workers use these builders.
function New-OneLinkDatabaseExportCommand {
    param([string]$DatabaseName, [string]$FilePath)
    [void](ConvertTo-OneLinkDatabaseIdentifier $DatabaseName)
    if ($FilePath -notmatch '^/' -or $FilePath -match '[\r\n\x00]') { throw 'Backup path must be an absolute Linux file path.' }
    $header = (Get-OneLinkDatabaseShell) + "`ndb=" + (ConvertTo-OneLinkBashArg $DatabaseName) + "`noutFile=" + (ConvertTo-OneLinkBashArg $FilePath) + "`n"
    $body = @'
dump_client=$(command -v mysqldump || command -v mariadb-dump) || { echo 'Database dump client is not installed.' >&2; exit 1; }
umask 077
# Build the dump in /tmp (always writable by the connecting user) - the final
# destination directory (e.g. /mysqldata) is commonly root/mysql-owned and NOT
# writable by that user, so both the temp file AND the final copy must go
# through db_run (sudo). A plain '>' or 'mv' into that directory only carries
# the connecting user's own permissions, not sudo's, and fails with
# "Permission denied" even though db_run's mysqldump itself succeeds.
outDir=$(dirname -- "$outFile")
db_run mkdir -p -- "$outDir" 2>/dev/null || true
tmp=$(mktemp -- "${TMPDIR:-/tmp}/onelink-db-export.XXXXXX")
trap 'rm -f -- "$tmp" "${tmp}.gz"' EXIT
if ! db_run "$dump_client" --protocol=SOCKET --user=root --add-drop-table --skip-lock-tables --single-transaction --hex-blob --master-data=2 -- "$db" > "$tmp"; then
    db_run "$dump_client" --protocol=SOCKET --user=root --add-drop-table --skip-lock-tables --single-transaction --hex-blob -- "$db" > "$tmp"
fi
case "$outFile" in
    *.gz) gzip -c -- "$tmp" > "${tmp}.gz"; db_run cp -f -- "${tmp}.gz" "$outFile" ;;
    *) db_run cp -f -- "$tmp" "$outFile" ;;
esac
# The copy above runs as root (via db_run), leaving $outFile root-owned. That is
# invisible for a 'Server' destination (nothing reads it back through this
# session), but for Local/Network destinations this SAME file is immediately
# SCP'd down by the connecting (non-root) user - which then fails with
# "Permission denied" against a root:0600 file, even though every step up to
# here succeeded. Reclaim ownership for the connecting user BEFORE locking it
# down, so it stays private (0600) but is readable by whoever actually ran the
# export, on this box or over SCP.
me=$(id -un)
db_run chown -- "$me" "$outFile" 2>/dev/null || true
chmod 0600 -- "$outFile" 2>/dev/null || db_run chmod 0600 -- "$outFile" 2>/dev/null || true
echo "Database export completed."
'@
    return ConvertTo-OneLinkDatabaseCommand ($header + $body)
}

function New-OneLinkDatabaseImportCommand {
    param([string]$DatabaseName, [string]$FilePath)
    $identifier = ConvertTo-OneLinkDatabaseIdentifier $DatabaseName
    if ($DatabaseName -in @('mysql','sys','information_schema','performance_schema')) { throw 'Restoring over a system database is not supported.' }
    if ($FilePath -notmatch '^/' -or $FilePath -match '[\r\n\x00]') { throw 'Restore path must be an absolute Linux file path.' }
    $sql = "SET SESSION sql_mode = 'NO_BACKSLASH_ESCAPES'; DROP DATABASE IF EXISTS $identifier; CREATE DATABASE $identifier;"
    $payload = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes($sql))
    $header = (Get-OneLinkDatabaseShell) + "`ndb=" + (ConvertTo-OneLinkBashArg $DatabaseName) + "`nsqlFile=" + (ConvertTo-OneLinkBashArg $FilePath) + "`ncreateSql='$payload'`n"
    $body = @'
# The backup file (e.g. under /mysqldata) may be root/mysql-owned and NOT
# readable by the connecting user, even though db_run's sudo commands can read
# it fine. A plain 'test -r' / '<' redirect only carries the connecting user's
# own permissions (redirection happens in this shell, before sudo runs), so
# every touch of "$sqlFile" below goes through db_run instead.
db_run test -r "$sqlFile" || { echo 'Backup file is missing or not readable.' >&2; exit 1; }
db_run test -s "$sqlFile" || { echo 'Backup file is empty.' >&2; exit 1; }
case "$sqlFile" in *.gz) db_run gzip -t -- "$sqlFile" ;; esac
# Confirm database authentication BEFORE dropping the selected database.
db_mysql --execute='SELECT 1' >/dev/null
printf '%s' "$createSql" | base64 --decode | db_mysql
case "$sqlFile" in
    *.gz) db_run gzip -dc -- "$sqlFile" | db_mysql --database="$db" ;;
    *) db_run cat -- "$sqlFile" | db_mysql --database="$db" ;;
esac
echo 'Database import completed.'
'@
    return ConvertTo-OneLinkDatabaseCommand ($header + $body)
}

function Get-OneLinkDatabaseWorkerFunctions {
    $names = @('ConvertTo-OneLinkBashArg','ConvertTo-OneLinkDatabaseIdentifier','Get-OneLinkDatabaseShell','ConvertTo-OneLinkDatabaseCommand','New-OneLinkDatabaseExportCommand','New-OneLinkDatabaseImportCommand','New-OneLinkDatabaseJobCommand','ConvertTo-OneLinkWinArg','Invoke-OneLinkNetUse','New-OneLinkSqlScriptRunCommand')
    return (($names | ForEach-Object { 'function ' + $_ + " {`n" + (Get-Item "Function:$_").Definition + "`n}" }) -join "`n")
}
function New-OneLinkDatabaseJobCommand {
    param([string]$Command, [ValidatePattern('^[a-f0-9]{32}$')][string]$JobId)
    $dir = '/tmp/onelink-db-' + $JobId
    $body = 'set -euo pipefail; echo $$ > ' + (ConvertTo-OneLinkBashArg "$dir/pid") + "; trap 'rm -f -- " + "$dir/pid; rmdir -- $dir" + "' EXIT; " + $Command
    return 'umask 077; mkdir -- ' + (ConvertTo-OneLinkBashArg $dir) + ' && setsid bash -c ' + (ConvertTo-OneLinkBashArg $body)
}

function Invoke-OneLinkDatabaseServiceAction {
    param($Session, [ValidateSet('Restart','Stop')][string]$Action, [string]$Unit, [int]$TimeoutSeconds = 120)
    $verb = $Action.ToLowerInvariant()
    $scriptText = "set -e`n" + 'PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH' + "`n" +
        'if [ "$(id -u)" = 0 ]; then systemctl ' + $verb + ' ' + (ConvertTo-OneLinkBashArg $Unit) + '; else sudo -n systemctl ' + $verb + ' ' + (ConvertTo-OneLinkBashArg $Unit) + '; fi'
    Invoke-OneLinkDatabaseCommand -Session $Session -Command $scriptText -TimeoutSeconds $TimeoutSeconds | Out-Null
}
function Invoke-NMenuServiceAction {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [Parameter(Mandatory)]$Settings,
        [Parameter(Mandatory)][string]$SystemdName,
        [Parameter(Mandatory)][ValidateSet('Restart','Stop')][string]$Action
    )
    $verb = if ($Action -eq 'Stop') { 'stop' } else { 'restart' }
    # Direct equivalent of nmenu 'nstart'/'nstop' (with ncheck_os): systemctl on
    # RHEL, service on Debian - no nmenu.
    $tmpl = @'
unit=__UNITQ__
OS=$(uname -r | grep -q "el" && echo redhat || echo debian)
if [ "$OS" = "redhat" ]; then sudo systemctl __VERB__ "$unit"; else sudo service "$unit" __VERB__; fi
'@
    $cmd = $tmpl.Replace('__UNITQ__', (ConvertTo-OneLinkBashArg $SystemdName)).Replace('__VERB__', $verb)
    return Invoke-OneLinkNmenuCommand -Session $Session -Command $cmd -TimeoutSeconds ([int]$Settings.Ssh.CommandTimeoutSeconds)
}

function Get-NMenuServiceStatus {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [Parameter(Mandatory)][string]$SystemdName
    )
    # nstatus exits non-zero when a unit is not running - that is not an error
    # for a status check, so capture the output regardless of exit code.
    # Direct equivalent of nmenu 'nstatus' (+ ncheck_os) - no nmenu.
    $prefixedPath = 'PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH'
    $statusTmpl = @'
unit=__UNITQ__
OS=$(uname -r | grep -q "el" && echo redhat || echo debian)
if [ "$OS" = "redhat" ]; then sudo SYSTEMD_PAGER= PAGER= systemctl status "$unit"; else sudo SYSTEMD_PAGER= PAGER= service "$unit" status; fi
'@
    $cmd = "$prefixedPath; " + $statusTmpl.Replace('__UNITQ__', (ConvertTo-OneLinkBashArg $SystemdName))
    return Invoke-OneLinkSshCommand -Session $Session -Command $cmd -TimeoutSeconds 30
}

function Invoke-NMenuSslConfig {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [Parameter(Mandatory)]$Settings,
        [Parameter(Mandatory)][ValidateSet('Concentrator','Report Server')][string]$Component,
        [Parameter(Mandatory)][ValidateSet('Enable','Disable')][string]$Action
    )
    $arg = switch ("$Component|$Action") {
        'Concentrator|Enable'   { 'enable_concentrator' }
        'Concentrator|Disable'  { 'disable_concentrator' }
        'Report Server|Enable'  { 'enable_reportserver' }
        'Report Server|Disable' { 'disable_reportserver' }
        default { throw "No SSL argument mapping for '$Component' / '$Action'." }
    }

    # Direct equivalent of nmenu 'n_ssl_config' - the exact same awk/sed edits to
    # the concentrator activemq.xml and the report-server ssl.properties, run inline
    # so the tool never invokes nmenu. The interactive pause is a no-op here. We
    # still judge success by the "SSL ENABLED/DISABLED" message it prints.
    $prefixedPath = 'PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH'
    $sslTmpl = @'
CONC_DIR="/opt/onelink-concentrator/conf"
CONC_XML="$CONC_DIR/activemq.xml"
CONC_KEYSTORE="$CONC_DIR/client.ks"
REPORT_DIR="/opt/onelink-report-server/etc"
REPORT_SSL="$REPORT_DIR/ssl.properties"
pause() { :; }
enable_conc_ssl() {
    [ -f "$CONC_XML" ] || { echo "ERROR: $CONC_XML not found"; pause; return; }
    [ -f "$CONC_KEYSTORE" ] || { echo "ERROR: $CONC_KEYSTORE not found"; pause; return; }
    if sudo grep -q '^[[:space:]]*<!-- SSL: UNCOMMENT TO ENABLE' "$CONC_XML"; then
        sudo awk '
        BEGIN { inblock=0 }
        /^[[:space:]]*<!-- SSL: UNCOMMENT TO ENABLE/ { inblock=1; next }
        inblock && /^[[:space:]]*-->$/ { inblock=0; next }
        { print }
        ' "$CONC_XML" | sudo tee "$CONC_XML.tmp" >/dev/null
        sudo mv "$CONC_XML.tmp" "$CONC_XML"
    fi
    if ! sudo grep -q 'NONSSL START' "$CONC_XML"; then
        sudo awk '
        BEGIN { done=0 }
        /^[[:space:]]*<transportConnector name="openwire"/ && !done {
            print "            <!-- NONSSL START"
            print
            getline
            print
            print "                 NONSSL END -->"
            done=1
            next
        }
        { print }
        ' "$CONC_XML" | sudo tee "$CONC_XML.tmp" >/dev/null
        sudo mv "$CONC_XML.tmp" "$CONC_XML"
    fi
    sudo chown onelink:onelink "$CONC_XML"
    sudo chmod 664 "$CONC_XML"
    echo "SSL ENABLED for Concentrator"
    pause
}
disable_conc_ssl() {
    [ -f "$CONC_XML" ] || { echo "ERROR: $CONC_XML not found"; pause; return; }
    if ! sudo grep -q '^[[:space:]]*<!-- SSL: UNCOMMENT TO ENABLE' "$CONC_XML"; then
        sudo awk '
        BEGIN { done=0 }
        /^[[:space:]]*<transportConnector name="ssl"/ && !done {
            print "            <!-- SSL: UNCOMMENT TO ENABLE (must acquire client.ks from Paltronics Support)"
            print
            getline
            print
            print "            -->"
            done=1
            next
        }
        { print }
        ' "$CONC_XML" | sudo tee "$CONC_XML.tmp" >/dev/null
        sudo mv "$CONC_XML.tmp" "$CONC_XML"
    fi
    if sudo grep -q 'NONSSL START' "$CONC_XML"; then
        sudo awk '
        BEGIN { inblock=0 }
        /^[[:space:]]*<!--[[:space:]]*NONSSL START/ { inblock=1; next }
        inblock && /NONSSL END[[:space:]]*-->$/ { inblock=0; next }
        { print }
        ' "$CONC_XML" | sudo tee "$CONC_XML.tmp" >/dev/null
        sudo mv "$CONC_XML.tmp" "$CONC_XML"
    fi
    sudo chown onelink:onelink "$CONC_XML"
    sudo chmod 664 "$CONC_XML"
    echo "SSL DISABLED for Concentrator"
    pause
}
enable_report_ssl() {
    [ -f "$REPORT_SSL" ] || { echo "ERROR: $REPORT_SSL not found"; pause; return; }
    sudo cp -f "$REPORT_SSL" "$REPORT_SSL.bak"
    sudo sed -i 's/^api.use.ssl=.*/api.use.ssl=true/' "$REPORT_SSL"
    sudo chown onelink:onelink "$REPORT_SSL"
    sudo chmod 664 "$REPORT_SSL"
    echo "SSL ENABLED for Report Server"
    pause
}
disable_report_ssl() {
    [ -f "$REPORT_SSL" ] || { echo "ERROR: $REPORT_SSL not found"; pause; return; }
    sudo cp -f "$REPORT_SSL" "$REPORT_SSL.bak"
    sudo sed -i 's/^api.use.ssl=.*/api.use.ssl=false/' "$REPORT_SSL"
    sudo chown onelink:onelink "$REPORT_SSL"
    sudo chmod 664 "$REPORT_SSL"
    echo "SSL DISABLED for Report Server"
    pause
}
case "__ARG__" in
    enable_concentrator)  enable_conc_ssl ;;
    disable_concentrator) disable_conc_ssl ;;
    enable_reportserver)  enable_report_ssl ;;
    disable_reportserver) disable_report_ssl ;;
    *) echo "Invalid option" ;;
esac
'@
    $sslCmd = "$prefixedPath; " + $sslTmpl.Replace('__ARG__', $arg)
    $result = Invoke-OneLinkSshCommand -Session $Session -Command $sslCmd -TimeoutSeconds ([int]$Settings.Ssh.CommandTimeoutSeconds)
    $text = (@($result.Output, $result.Error) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join [Environment]::NewLine

    if ($text -match '(?i)SSL\s+(ENABLED|DISABLED)') {
        return $text
    }
    if ($text -match '(?i)not\s+found') {
        # Config file absent -> the component isn't installed on this box yet.
        # Per requirements this is a non-fatal note, not a failure.
        Write-OneLinkLog "SSL $Action ($Component): component not present on this server - $text" -Level Warning
        return $text
    }
    throw "SSL $Action ($Component) did not report success (exit $($result.ExitStatus)). $text"
}

# Enable/Disable SSL for the OneLink Appserver. nmenu's n_ssl_config has NO
# appserver option, so - like the testing team's utility - we do it by editing
# /opt/onelink/etc/app.properties (jetty.ssl.enabled=true|false). For Enable a
# keystore must exist at /opt/onelink/etc/client.ks; the caller may first upload
# one (RemoteKeystorePath) or rely on one already on the box. We do NOT restart
# the service here - the caller tells the user to restart it. Judged by the
# printed marker, not the exit code.
function Invoke-AppserverSslConfig {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [Parameter(Mandatory)]$Settings,
        [Parameter(Mandatory)][ValidateSet('Enable','Disable')][string]$Action,
        [string]$RemoteKeystorePath
    )

    $val = if ($Action -eq 'Enable') { 'true' } else { 'false' }

    # Optional keystore install block (only when a file was uploaded).
    $ksBlock = ''
    if ($Action -eq 'Enable' -and -not [string]::IsNullOrWhiteSpace($RemoteKeystorePath)) {
        $q = ConvertTo-OneLinkBashArg $RemoteKeystorePath
        $ksBlock = @"
(sudo -n install -m 0644 $q "`$TARGET" || install -m 0644 $q "`$TARGET")
(sudo -n rm -f $q || rm -f $q || true)
"@
    }

    $cmd = @"
set -uo pipefail
PROPS=/opt/onelink/etc/app.properties
TARGET=/opt/onelink/etc/client.ks
stamp=`$(date +%s)
if [ ! -f "`$PROPS" ]; then echo OLK_APPSSL_NOPROPS 1>&2; exit 3; fi
(sudo -n cp "`$PROPS" "`$PROPS.bak_ssl_`$stamp" 2>/dev/null || cp "`$PROPS" "`$PROPS.bak_ssl_`$stamp")
$ksBlock
if [ "$val" = "true" ] && [ ! -f "`$TARGET" ]; then echo OLK_APPSSL_NOKS 1>&2; exit 4; fi
if (sudo -n grep -Eq '^[[:space:]]*jetty\.ssl\.enabled[[:space:]]*=' "`$PROPS" 2>/dev/null || grep -Eq '^[[:space:]]*jetty\.ssl\.enabled[[:space:]]*=' "`$PROPS"); then
  (sudo -n sed -i -E 's/^[[:space:]]*jetty\.ssl\.enabled[[:space:]]*=.*/jetty.ssl.enabled=$val/' "`$PROPS" || sed -i -E 's/^[[:space:]]*jetty\.ssl\.enabled[[:space:]]*=.*/jetty.ssl.enabled=$val/' "`$PROPS")
else
  (printf '\njetty.ssl.enabled=$val\n' | sudo -n tee -a "`$PROPS" >/dev/null || printf '\njetty.ssl.enabled=$val\n' | tee -a "`$PROPS" >/dev/null)
fi
echo OLK_APPSSL_OK
(sudo -n grep -nE 'jetty\.ssl\.enabled|jetty\.ssl\.port|jetty\.ssl\.keystorePath|jetty\.ssl\.trustStorePath' "`$PROPS" || grep -nE 'jetty\.ssl\.enabled|jetty\.ssl\.port|jetty\.ssl\.keystorePath|jetty\.ssl\.trustStorePath' "`$PROPS")
"@

    $result = Invoke-OneLinkSshCommand -Session $Session -Command $cmd -TimeoutSeconds ([int]$Settings.Ssh.CommandTimeoutSeconds)
    $text = (@($result.Output, $result.Error) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join [Environment]::NewLine

    if ($text -match 'OLK_APPSSL_OK') { return $text }
    if ($text -match 'OLK_APPSSL_NOPROPS') { throw "SSL $Action (OneLink Appserver): /opt/onelink/etc/app.properties not found - appserver is not installed on this server." }
    if ($text -match 'OLK_APPSSL_NOKS') { throw "SSL Enable (OneLink Appserver): no keystore at /opt/onelink/etc/client.ks. Provide one via 'Appserver keystore' (Browse) or place client.ks on the server first." }
    throw "SSL $Action (OneLink Appserver) did not report success (exit $($result.ExitStatus)). $text"
}

# Install an already-uploaded file (RemoteSource, sitting in the upload dir) to a
# final path on the server, creating parent folders with sudo. Used by the
# Certificates tab to drop a cert/keystore where the user asks. Judged by marker.
function Install-OneLinkCertificate {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [Parameter(Mandatory)]$Settings,
        [Parameter(Mandatory)][string]$RemoteSource,
        [Parameter(Mandatory)][string]$FinalPath,
        [Parameter(Mandatory)][string]$ParentDir
    )
    $qs = ConvertTo-OneLinkBashArg $RemoteSource
    $qf = ConvertTo-OneLinkBashArg $FinalPath
    $qd = ConvertTo-OneLinkBashArg $ParentDir
    $cmd = @"
set -uo pipefail
(sudo -n mkdir -p $qd || mkdir -p $qd)
(sudo -n install -m 0644 $qs $qf || install -m 0644 $qs $qf)
(sudo -n rm -f $qs || rm -f $qs || true)
if [ -f $qf ]; then echo OLK_CERT_OK; (sudo -n ls -l $qf || ls -l $qf); else echo OLK_CERT_FAIL 1>&2; exit 1; fi
"@
    $result = Invoke-OneLinkSshCommand -Session $Session -Command $cmd -TimeoutSeconds ([int]$Settings.Ssh.CommandTimeoutSeconds)
    $text = (@($result.Output, $result.Error) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join [Environment]::NewLine
    if ($text -match 'OLK_CERT_OK') { return $text }
    throw "Certificate install to '$FinalPath' did not confirm (exit $($result.ExitStatus)). $text"
}

# If FinalPath already exists on the server, back it up BEFORE Install-OneLinkCertificate
# overwrites it. No-ops cleanly (returns a 'nothing to back up' message) if there is no
# existing file yet - e.g. a first-time deploy. Never throws: a backup failure is a
# warning, not a reason to abort the deploy.
#   -Dest 'Server'         : sudo-copies it to $BackupPath (an absolute Linux folder) on
#                            the SAME server, right there - no transfer involved.
#   -Dest 'Local Windows'  : stages a copy under the tool's upload dir, then downloads it
#                            to $BackupPath\<server host>\ on this PC. The staged copy is
#                            chown'd back to the CONNECTING user before download - the same
#                            fix as the database-export permission bug: a file a sudo copy
#                            leaves root:0600 cannot be pulled down over SCP by a non-root
#                            login, so every download in this tool must reclaim ownership
#                            first.
function Backup-OneLinkCertificateFile {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [Parameter(Mandatory)]$Settings,
        [Parameter(Mandatory)][string]$FinalPath,
        [Parameter(Mandatory)][ValidateSet('Server', 'Local Windows')][string]$Dest,
        [Parameter(Mandatory)][string]$BackupPath,
        [string]$ServerHost, [int]$ServerPort, [object]$ServerCredential
    )
    $qf = ConvertTo-OneLinkBashArg $FinalPath
    $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $baseName = [IO.Path]::GetFileName($FinalPath.TrimEnd('/'))
    $timeout = [int]$Settings.Ssh.CommandTimeoutSeconds

    if ($Dest -eq 'Server') {
        $backupDir = $BackupPath.TrimEnd('/'); if ($backupDir -eq '') { $backupDir = '/' }
        $qd = ConvertTo-OneLinkBashArg $backupDir
        $backupFile = "$backupDir/$baseName.$stamp.bak"
        $qb = ConvertTo-OneLinkBashArg $backupFile
        $cmd = @"
set -uo pipefail
if sudo -n test -f $qf 2>/dev/null || test -f $qf 2>/dev/null; then
    (sudo -n mkdir -p -- $qd || mkdir -p -- $qd)
    (sudo -n cp -f -- $qf $qb || cp -f -- $qf $qb)
    if sudo -n test -f $qb 2>/dev/null || test -f $qb 2>/dev/null; then echo "OLK_BK_OK $backupFile"; else echo OLK_BK_FAIL; fi
else
    echo OLK_BK_NONE
fi
"@
        $r = Invoke-OneLinkSshCommand -Session $Session -Command $cmd -TimeoutSeconds $timeout
        $text = (@($r.Output, $r.Error) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join ' '
        if ($text -match 'OLK_BK_NONE') { return "No existing file at $FinalPath - nothing to back up." }
        if ($text -match 'OLK_BK_OK') { return "Backed up existing $FinalPath to $backupFile on the server." }
        return "WARNING: backup of existing $FinalPath failed ($text) - continuing with deploy anyway."
    }

    # Local Windows: stage a connecting-user-owned copy server-side, then SCP it down.
    $remoteDir = ([string]$Settings.Remote.UploadDirectory).TrimEnd('/')
    Ensure-OneLinkRemoteDirectory -Session $Session -RemoteDirectory $remoteDir -TimeoutSeconds $timeout
    $tmp = "$remoteDir/olk_certbak_$([guid]::NewGuid().ToString('N'))_$baseName"
    $qt = ConvertTo-OneLinkBashArg $tmp
    $cmd = @"
set -uo pipefail
if sudo -n test -f $qf 2>/dev/null || test -f $qf 2>/dev/null; then
    (sudo -n cp -f -- $qf $qt || cp -f -- $qf $qt)
    me=`$(id -un)
    (sudo -n chown -- "`$me" $qt 2>/dev/null || true)
    chmod 0644 -- $qt 2>/dev/null || sudo -n chmod 0644 -- $qt 2>/dev/null || true
    if [ -r $qt ]; then echo OLK_BK_OK; else echo OLK_BK_FAIL; fi
else
    echo OLK_BK_NONE
fi
"@
    $r = Invoke-OneLinkSshCommand -Session $Session -Command $cmd -TimeoutSeconds $timeout
    $text = (@($r.Output, $r.Error) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join ' '
    if ($text -match 'OLK_BK_NONE') { return "No existing file at $FinalPath - nothing to back up." }
    if ($text -notmatch 'OLK_BK_OK') { return "WARNING: backup of existing $FinalPath failed ($text) - continuing with deploy anyway." }

    try {
        Import-OneLinkPoshSsh
        $localDir = Join-Path $BackupPath ($ServerHost -replace '[\\/:*?"<>|]', '_')
        if (-not (Test-Path -LiteralPath $localDir)) { New-Item -ItemType Directory -Path $localDir -Force | Out-Null }
        $dlDir = Join-Path ([IO.Path]::GetTempPath()) ('olk_certbak_dl_' + [guid]::NewGuid().ToString('N'))
        [void](New-Item -ItemType Directory -Path $dlDir)
        try {
            Get-SCPItem -ComputerName $ServerHost -Port $ServerPort -Credential $ServerCredential -Path $tmp -PathType File -Destination $dlDir -AcceptKey -Force -ErrorAction Stop
            $downloaded = Join-Path $dlDir ([IO.Path]::GetFileName($tmp))
            $finalLocal = Join-Path $localDir "$baseName.$stamp.bak"
            Move-Item -LiteralPath $downloaded -Destination $finalLocal -Force
        }
        finally {
            if (Test-Path -LiteralPath $dlDir) { Remove-Item -LiteralPath $dlDir -Recurse -Force -ErrorAction SilentlyContinue }
            Invoke-OneLinkSshCommand -Session $Session -Command ("(sudo -n rm -f -- $qt || rm -f -- $qt) 2>/dev/null; true") -TimeoutSeconds 30 | Out-Null
        }
        return "Backed up existing $FinalPath to $finalLocal on this PC."
    }
    catch {
        Invoke-OneLinkSshCommand -Session $Session -Command ("(sudo -n rm -f -- $qt || rm -f -- $qt) 2>/dev/null; true") -TimeoutSeconds 30 | Out-Null
        return "WARNING: backup download of existing $FinalPath failed ($($_.Exception.Message)) - continuing with deploy anyway."
    }
}

# ============================================================================
#  EMBEDDED MODULE: PackageManager  (was Modules\PackageManager.psm1)
# ============================================================================

function Ensure-OneLinkRemoteDirectory {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [Parameter(Mandatory)][string]$RemoteDirectory,
        [int]$TimeoutSeconds = 60
    )

    $quoted = "'" + ($RemoteDirectory -replace "'", "'\''") + "'"
    # Create the upload dir AND make sure the SSH user can write to it. A common
    # failure is the dir being left root-owned by an earlier run, which makes the
    # SCP upload fail with "Permission denied". If it is not writable, recreate /
    # chown it to the connecting user via sudo, then verify.
    $cmd = @"
mkdir -p $quoted 2>/dev/null || true
# Take ownership of the dir AND every file inside it (recursive). A root-owned
# leftover file - from an earlier run or a manual 'sudo' copy - blocks the SCP
# overwrite with "Permission denied" even when the directory itself is writable.
sudo chown -R "`$(id -un)":"`$(id -gn)" $quoted 2>/dev/null || true
# Verify by actually creating a file (real write test, not just [ -w ]).
if touch $quoted/.olk_w 2>/dev/null; then rm -f $quoted/.olk_w 2>/dev/null; echo OLK_DIR_OK; else echo OLK_DIR_FAIL; fi
"@
    $result = Invoke-OneLinkSshCommand -Session $Session -Command $cmd -TimeoutSeconds $TimeoutSeconds
    if (([string]$result.Output) -notmatch 'OLK_DIR_OK') {
        throw "Remote upload directory '$RemoteDirectory' is not writable by the SSH user and could not be fixed with sudo (the account may lack passwordless sudo). Fix its ownership on the server (e.g. sudo rm -rf '$RemoteDirectory'), or use a directory under the user's home."
    }
}

function Send-OneLinkPackage {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$ComputerName,
        [Parameter(Mandatory)][int]$Port,
        [Parameter(Mandatory)][PSCredential]$Credential,
        [Parameter(Mandatory)][string]$LocalPath,
        [Parameter(Mandatory)][string]$RemoteDirectory
    )

    if (-not (Test-Path -LiteralPath $LocalPath -PathType Leaf)) {
        throw "Package file was not found: $LocalPath"
    }

    Import-OneLinkPoshSsh

    Set-SCPItem `
        -ComputerName $ComputerName `
        -Port $Port `
        -Credential $Credential `
        -Path $LocalPath `
        -Destination $RemoteDirectory `
        -AcceptKey `
        -ErrorAction Stop

    return (Join-Path $RemoteDirectory ([IO.Path]::GetFileName($LocalPath))).Replace('\','/')
}

# Built-in command templates used when Settings.Packages.Types does not define
# a given extension (keeps older external Settings.json files working).
function Get-OneLinkDefaultPackageCommand {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$Extension,
        [Parameter(Mandatory)][string]$Mode
    )

    switch ($Extension) {
        'rpm' {
            if ($Mode -eq 'Install') { return "sudo rpm -ivh --replacepkgs '{0}'" }
            return "sudo rpm -Uvh '{0}'"
        }
        'deb' {
            # Return dpkg's own exit status; run the dependency fix best-effort
            # so an offline apt-get can never mask a successful dpkg install.
            return 'sudo DEBIAN_FRONTEND=noninteractive dpkg -i ''{0}''; rc=$?; sudo DEBIAN_FRONTEND=noninteractive apt-get -y -f install >/dev/null 2>&1 || true; exit $rc'
        }
        default {
            throw "Unsupported package type '.$Extension'. Add a template under Packages.Types.$Extension in Settings.json."
        }
    }
}

# Install/upgrade a package, auto-detecting the packager from the file
# extension (.rpm -> RHEL/rpm, .deb -> Debian/dpkg, others configurable via
# Settings.Packages.Types). Any interactive prompt is auto-answered (the
# configured Packages.AutoAnswer value is fed on repeat via 'yes', which also
# presses Enter for you) so installation runs unattended.
function Install-OneLinkPackage {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [Parameter(Mandatory)]$Settings,
        [Parameter(Mandatory)][string]$RemotePackagePath,
        [ValidateSet('Install','Upgrade')][string]$Mode,
        [AllowEmptyString()][string]$Reason = ''
    )

    $ext = ([IO.Path]::GetExtension($RemotePackagePath)).TrimStart('.').ToLowerInvariant()
    if ($ext -ne 'rpm' -and $ext -ne 'deb') {
        throw "Unsupported package type '.$ext' (only .rpm and .deb are supported)."
    }

    if ([string]::IsNullOrEmpty($Reason)) {
        $Reason = [string](Get-OneLinkProperty -Object $Settings.Packages -Name 'Reason' -Default "Installed via $($script:AppName)")
    }

    $pkgQ = ConvertTo-OneLinkBashArg $RemotePackagePath
    $reasonQ = ConvertTo-OneLinkBashArg $Reason

    # We do NOT trust the package-manager exit code (dpkg/rpm can return non-zero
    # for cosmetic reasons, e.g. a postinst warning). Instead we install, then
    # ask the package database whether the package - identified by the NAME read
    # FROM the file itself - is now present at the version we shipped. The REASON
    # is supplied both as an env var and on stdin (compliance prompt). No apt-get
    # / dnf dependency step is run.
    if ($ext -eq 'deb') {
        $template = @'
export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH
set +e
PKGFILE=__PKGQ__
PKG=$(dpkg-deb -f "$PKGFILE" Package 2>/dev/null)
WANT=$(dpkg-deb -f "$PKGFILE" Version 2>/dev/null)
yes __REASONQ__ 2>/dev/null | head -n 200 | sudo env REASON=__REASONQ__ DEBIAN_FRONTEND=noninteractive dpkg -i "$PKGFILE"
STATUS=$(dpkg-query -W -f='${Status}' "$PKG" 2>/dev/null)
HAVE=$(dpkg-query -W -f='${Version}' "$PKG" 2>/dev/null)
echo "OLK_VERIFY package=$PKG wanted=$WANT installed=$HAVE state=[$STATUS]"
if [ "$STATUS" = "install ok installed" ] && [ -n "$WANT" ] && [ "$HAVE" = "$WANT" ]; then echo "OLK_RESULT=OK"; else echo "OLK_RESULT=FAIL"; fi
'@
        $script = $template.Replace('__PKGQ__', $pkgQ).Replace('__REASONQ__', $reasonQ)
    }
    else {
        $rpmCmd = if ($Mode -eq 'Install') { 'rpm -ivh --replacepkgs' } else { 'rpm -Uvh' }
        # The OneLink RPM's %prein scriptlet prompts for a compliance reason by
        # reading /dev/tty. An SSH exec has no controlling terminal, so a plain
        # install dies with "/dev/tty: No such device or address". We run rpm
        # inside a pseudo-terminal via `script` so /dev/tty exists, and feed the
        # reason into that tty (also pass REASON as an env var, like the .deb path).
        $template = @'
export PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH
set +e
PKGFILE=__PKGQ__
PKG=$(rpm -qp --qf '%{NAME}' "$PKGFILE" 2>/dev/null)
WANT=$(rpm -qp --qf '%{VERSION}-%{RELEASE}' "$PKGFILE" 2>/dev/null)
if command -v script >/dev/null 2>&1; then
  yes __REASONQ__ 2>/dev/null | head -n 200 | sudo env REASON=__REASONQ__ script -qe -c "__RPMCMD__ \"$PKGFILE\"" /dev/null
else
  yes __REASONQ__ 2>/dev/null | head -n 200 | sudo env REASON=__REASONQ__ __RPMCMD__ "$PKGFILE"
fi
HAVE=$(rpm -q --qf '%{VERSION}-%{RELEASE}' "$PKG" 2>/dev/null)
echo "OLK_VERIFY package=$PKG wanted=$WANT installed=$HAVE"
if rpm -q "$PKG" >/dev/null 2>&1 && [ -n "$WANT" ] && [ "$HAVE" = "$WANT" ]; then echo "OLK_RESULT=OK"; else echo "OLK_RESULT=FAIL"; fi
'@
        $script = $template.Replace('__PKGQ__', $pkgQ).Replace('__REASONQ__', $reasonQ).Replace('__RPMCMD__', $rpmCmd)
    }

    # Package installs can be slow (large packages, scriptlets, service setup),
    # far longer than a normal command. Use a generous install timeout - the
    # configurable Packages.InstallTimeoutSeconds (default 1800s = 30 min),
    # never shorter than the normal command timeout.
    $installTimeout = [int](Get-OneLinkProperty -Object $Settings.Packages -Name 'InstallTimeoutSeconds' -Default 1800)
    if ($installTimeout -lt [int]$Settings.Ssh.CommandTimeoutSeconds) { $installTimeout = [int]$Settings.Ssh.CommandTimeoutSeconds }

    Write-OneLinkLog "Installing .$ext package ($Mode); success is verified against the package database (timeout ${installTimeout}s)." -Level Debug
    $result = Invoke-OneLinkSshCommand `
        -Session $Session `
        -Command $script `
        -TimeoutSeconds $installTimeout

    $output = (@($result.Output, $result.Error) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join [Environment]::NewLine

    if ($output -notmatch 'OLK_RESULT=OK') {
        throw "$ext $Mode did not verify as installed. $output"
    }

    # Return the package output without our internal marker line.
    return (($output -split "`r?`n" | Where-Object { $_ -notmatch '^OLK_RESULT=' }) -join [Environment]::NewLine)
}

