function Show-ErrorMessage {
    param([string]$Message)
    Write-OneLinkLog $Message -Level Error
    [System.Windows.MessageBox]::Show($Message, $script:AppName, 'OK', 'Error') | Out-Null
}

function Show-InfoMessage {
    param([string]$Message)
    [System.Windows.MessageBox]::Show($Message, $script:AppName, 'OK', 'Information') | Out-Null
}

function Show-WarningMessage {
    param([string]$Message)
    Write-OneLinkLog $Message -Level Warning
    [System.Windows.MessageBox]::Show($Message, $script:AppName, 'OK', 'Warning') | Out-Null
}

# A clean, professional report window (navy title bar + monospaced, scrollable
# body so columns line up) used for status / version / certificate reports.
# A helper: a modern gradient (blue -> violet) brush matching the app header.
function New-OneLinkHeaderBrush {
    $g = New-Object System.Windows.Media.LinearGradientBrush
    $g.StartPoint = New-Object System.Windows.Point(0, 0)
    $g.EndPoint = New-Object System.Windows.Point(1, 0)
    [void]$g.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.ColorConverter]::ConvertFromString('#2563EB'), 0)))
    [void]$g.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.ColorConverter]::ConvertFromString('#4F46E5'), 0.55)))
    [void]$g.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.ColorConverter]::ConvertFromString('#7C3AED'), 1)))
    $g.Freeze(); return $g
}

# Grab a style from the main window's resources (so popup buttons match the app).
function Get-OneLinkStyle { param([string]$Key) try { return $script:Window.FindResource($Key) } catch { return $null } }

function Show-OneLinkReport {
    param([string]$Title, [string]$Body)
    $win = New-Object System.Windows.Window
    $win.Title = $Title
    # Compact: size the window to the content, capped so it never gets huge.
    $lines = @($Body -split "`r?`n")
    $maxLine = ($lines | ForEach-Object { $_.Length } | Measure-Object -Maximum).Maximum
    if (-not $maxLine) { $maxLine = 40 }
    $win.Width = [Math]::Min(940, [Math]::Max(420, 70 + $maxLine * 7.4))
    $win.Height = [Math]::Min(640, [Math]::Max(200, 120 + $lines.Count * 17.5))
    $win.MinWidth = 380; $win.MinHeight = 180
    $win.WindowStartupLocation = 'CenterScreen'
    $win.Background = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#F5F7FB'))
    if ($script:Window) { $win.Owner = $script:Window }

    $grid = New-Object System.Windows.Controls.Grid
    foreach ($h in @('Auto', '*', 'Auto')) {
        $rd = New-Object System.Windows.Controls.RowDefinition
        $rd.Height = [System.Windows.GridLength]::new(1, $(if ($h -eq '*') { 'Star' } else { 'Auto' }))
        [void]$grid.RowDefinitions.Add($rd)
    }

    $hdr = New-Object System.Windows.Controls.Border
    $hdr.Background = New-OneLinkHeaderBrush
    $hdr.Padding = '16,11'
    $htxt = New-Object System.Windows.Controls.TextBlock
    $htxt.Text = $Title; $htxt.Foreground = [System.Windows.Media.Brushes]::White; $htxt.FontSize = 15; $htxt.FontWeight = 'Bold'
    $hdr.Child = $htxt
    [System.Windows.Controls.Grid]::SetRow($hdr, 0); [void]$grid.Children.Add($hdr)

    $card = New-Object System.Windows.Controls.Border
    $card.Background = [System.Windows.Media.Brushes]::White
    $card.BorderBrush = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#E2E8F0'))
    $card.BorderThickness = New-Object System.Windows.Thickness(1)
    $card.CornerRadius = New-Object System.Windows.CornerRadius(8)
    $card.Margin = '12,12,12,6'
    $tb = New-Object System.Windows.Controls.TextBox
    $tb.Text = $Body; $tb.IsReadOnly = $true; $tb.AcceptsReturn = $true
    $tb.FontFamily = New-Object System.Windows.Media.FontFamily('Consolas, Courier New, monospace')
    $tb.FontSize = 13; $tb.TextWrapping = 'NoWrap'
    $tb.VerticalScrollBarVisibility = 'Auto'; $tb.HorizontalScrollBarVisibility = 'Auto'
    $tb.BorderThickness = New-Object System.Windows.Thickness(0)
    $tb.Padding = '14,12'; $tb.Background = [System.Windows.Media.Brushes]::White
    $card.Child = $tb
    [System.Windows.Controls.Grid]::SetRow($card, 1); [void]$grid.Children.Add($card)

    $bp = New-Object System.Windows.Controls.StackPanel
    $bp.Orientation = 'Horizontal'; $bp.HorizontalAlignment = 'Right'; $bp.Margin = '12,4,12,12'
    $primaryStyle = Get-OneLinkStyle 'PrimaryButtonStyle'
    $secondaryStyle = Get-OneLinkStyle 'SecondaryButtonStyle'
    $copy = New-Object System.Windows.Controls.Button
    $copy.Content = 'Copy'; $copy.Width = 90; $copy.Height = 28; $copy.Margin = '0,0,8,0'
    if ($secondaryStyle) { $copy.Style = $secondaryStyle }
    $close = New-Object System.Windows.Controls.Button
    $close.Content = 'Close'; $close.Width = 90; $close.Height = 28; $close.IsDefault = $true; $close.IsCancel = $true
    if ($primaryStyle) { $close.Style = $primaryStyle }
    $copy.Add_Click({ try { [System.Windows.Clipboard]::SetText($Body) } catch { } }.GetNewClosure())
    $close.Add_Click({ $win.Close() }.GetNewClosure())
    [void]$bp.Children.Add($copy); [void]$bp.Children.Add($close)
    [System.Windows.Controls.Grid]::SetRow($bp, 2); [void]$grid.Children.Add($bp)

    $win.Content = $grid
    [void]$win.ShowDialog()
}

# A "loose" key for tolerant file-name matching: lower-cased with spaces and
# bracket/parenthesis characters removed. So "license (3).lic", "license(3).lic"
# and "license 3.lic" all reduce to the same key ("license3.lic"), letting the
# Find feature match a name the user half-remembers.
function ConvertTo-OneLinkLooseKey {
    param([AllowEmptyString()][string]$Value)
    return (([string]$Value).ToLowerInvariant() -replace '[\s()\[\]{}]', '')
}

# ----------------------------------------------------------------------------
#  Generic "Edit File" popup
#  ---------------------------------------------------------------------------
#  Open ANY file on a connected server, edit it in place, and save it back.
#  - Reads with sudo (so root-owned files are visible) and transports the
#    content as base64 so arbitrary bytes/quotes survive the round trip.
#  - Saves via 'sudo tee' onto the existing inode, which PRESERVES the file's
#    owner and permission bits (tee never chmod/chown's). A timestamped .bak
#    backup is made first.
#  - If exactly ONE server is connected it is used automatically (no picker);
#    with more than one connected, a server dropdown is shown.
# ----------------------------------------------------------------------------
function Show-OneLinkFileEditor {
    param([object]$Server = $null)   # when set (e.g. from a server row's right-click), use that server directly
    $connected = @($script:Servers | Where-Object { $null -ne $_.Session -and -not [string]::IsNullOrWhiteSpace($_.Host) })
    if ($connected.Count -eq 0) {
        Show-WarningMessage "Connect to at least one server first, then use Edit File."
        return
    }
    if ($null -ne $Server) {
        if ($null -eq $Server.Session) { Show-WarningMessage "Connect to $($Server.Host) first, then edit a file on it."; return }
        $connected = @($Server)
    }

    # Capture settings into a LOCAL so the closures below (GetNewClosure) see it -
    # inside a closure $script:Settings resolves to the closure's own (empty) scope.
    $settings = $script:Settings

    $win = New-Object System.Windows.Window
    $win.Title = 'Edit File'
    $win.Width = 900; $win.Height = 640
    $win.MinWidth = 560; $win.MinHeight = 420
    $win.WindowStartupLocation = 'CenterScreen'
    $win.Background = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#F5F7FB'))
    if ($script:Window) { $win.Owner = $script:Window }

    $grid = New-Object System.Windows.Controls.Grid
    # Rows: 0 header, 1 server+path, 2 search-results, 3 editor(*), 4 restart, 5 buttons
    foreach ($h in @('Auto', 'Auto', 'Auto', '*', 'Auto', 'Auto')) {
        $rd = New-Object System.Windows.Controls.RowDefinition
        $rd.Height = [System.Windows.GridLength]::new(1, $(if ($h -eq '*') { 'Star' } else { 'Auto' }))
        [void]$grid.RowDefinitions.Add($rd)
    }

    # Row 0: header
    $hdr = New-Object System.Windows.Controls.Border
    $hdr.Background = New-OneLinkHeaderBrush
    $hdr.Padding = '16,11'
    $htxt = New-Object System.Windows.Controls.TextBlock
    $htxt.Text = 'Edit File'; $htxt.Foreground = [System.Windows.Media.Brushes]::White; $htxt.FontSize = 15; $htxt.FontWeight = 'Bold'
    $hdr.Child = $htxt
    [System.Windows.Controls.Grid]::SetRow($hdr, 0); [void]$grid.Children.Add($hdr)

    # Row 1: server + path + Find + Load
    $top = New-Object System.Windows.Controls.Grid
    $top.Margin = '12,12,12,4'
    foreach ($w in @('Auto', 'Auto', '*', 'Auto', 'Auto')) {
        $cd = New-Object System.Windows.Controls.ColumnDefinition
        $cd.Width = [System.Windows.GridLength]::new(1, $(if ($w -eq '*') { 'Star' } else { 'Auto' }))
        [void]$top.ColumnDefinitions.Add($cd)
    }

    $lblSrv = New-Object System.Windows.Controls.TextBlock
    $lblSrv.Text = 'Server:'; $lblSrv.VerticalAlignment = 'Center'; $lblSrv.Margin = '0,0,8,0'; $lblSrv.FontWeight = 'SemiBold'
    [System.Windows.Controls.Grid]::SetColumn($lblSrv, 0); [void]$top.Children.Add($lblSrv)

    $cmbServer = $null
    $lblSrvValue = $null
    if ($connected.Count -eq 1) {
        # Single server: no picker, just show it.
        $lblSrvValue = New-Object System.Windows.Controls.TextBlock
        $lblSrvValue.Text = [string]$connected[0].Host
        $lblSrvValue.VerticalAlignment = 'Center'; $lblSrvValue.Margin = '0,0,14,0'
        [System.Windows.Controls.Grid]::SetColumn($lblSrvValue, 1); [void]$top.Children.Add($lblSrvValue)
    }
    else {
        $cmbServer = New-Object System.Windows.Controls.ComboBox
        $cmbServer.Width = 190; $cmbServer.Margin = '0,0,14,0'; $cmbServer.VerticalAlignment = 'Center'
        foreach ($s in $connected) { [void]$cmbServer.Items.Add([string]$s.Host) }
        $cmbServer.SelectedIndex = 0
        [System.Windows.Controls.Grid]::SetColumn($cmbServer, 1); [void]$top.Children.Add($cmbServer)
    }

    $txtPath = New-Object System.Windows.Controls.TextBox
    $txtPath.VerticalAlignment = 'Center'; $txtPath.Height = 26; $txtPath.Margin = '0,0,8,0'
    $txtPath.VerticalContentAlignment = 'Center'; $txtPath.Padding = '6,0'
    $txtPath.ToolTip = "Full path of the file to edit (e.g. /opt/onelink-concentrator/conf/activemq.xml)." + [Environment]::NewLine +
        "Don't know the path? Type just the file name (e.g. activemq.xml or *.properties) and click Find."
    [System.Windows.Controls.Grid]::SetColumn($txtPath, 2); [void]$top.Children.Add($txtPath)

    $secondaryStyle = Get-OneLinkStyle 'SecondaryButtonStyle'
    $primaryStyle = Get-OneLinkStyle 'PrimaryButtonStyle'

    $btnFind = New-Object System.Windows.Controls.Button
    $btnFind.Content = 'Find'; $btnFind.Width = 84; $btnFind.Height = 28; $btnFind.Margin = '0,0,8,0'
    $btnFind.ToolTip = "Search the server for a file by name when you don't know its full path. Type a name or wildcard (e.g. server.xml or *.properties)."
    if ($secondaryStyle) { $btnFind.Style = $secondaryStyle }
    [System.Windows.Controls.Grid]::SetColumn($btnFind, 3); [void]$top.Children.Add($btnFind)

    $btnLoad = New-Object System.Windows.Controls.Button
    $btnLoad.Content = 'Load'; $btnLoad.Width = 90; $btnLoad.Height = 28
    if ($secondaryStyle) { $btnLoad.Style = $secondaryStyle }
    [System.Windows.Controls.Grid]::SetColumn($btnLoad, 4); [void]$top.Children.Add($btnLoad)

    [System.Windows.Controls.Grid]::SetRow($top, 1); [void]$grid.Children.Add($top)

    # Row 2: search results (hidden until a Find runs)
    $matchRow = New-Object System.Windows.Controls.Grid
    $matchRow.Margin = '12,0,12,4'; $matchRow.Visibility = [System.Windows.Visibility]::Collapsed
    foreach ($w in @('Auto', '*')) {
        $cd = New-Object System.Windows.Controls.ColumnDefinition
        $cd.Width = [System.Windows.GridLength]::new(1, $(if ($w -eq '*') { 'Star' } else { 'Auto' }))
        [void]$matchRow.ColumnDefinitions.Add($cd)
    }
    $lblMatch = New-Object System.Windows.Controls.TextBlock
    $lblMatch.Text = 'Found:'; $lblMatch.VerticalAlignment = 'Center'; $lblMatch.Margin = '0,0,8,0'; $lblMatch.FontWeight = 'SemiBold'
    [System.Windows.Controls.Grid]::SetColumn($lblMatch, 0); [void]$matchRow.Children.Add($lblMatch)
    $cmbMatches = New-Object System.Windows.Controls.ComboBox
    $cmbMatches.VerticalAlignment = 'Center'
    $cmbMatches.ToolTip = 'Files found on the server. Pick one to load it into the editor.'
    [System.Windows.Controls.Grid]::SetColumn($cmbMatches, 1); [void]$matchRow.Children.Add($cmbMatches)
    [System.Windows.Controls.Grid]::SetRow($matchRow, 2); [void]$grid.Children.Add($matchRow)

    # Row 3: editor
    $card = New-Object System.Windows.Controls.Border
    $card.Background = [System.Windows.Media.Brushes]::White
    $card.BorderBrush = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#E2E8F0'))
    $card.BorderThickness = New-Object System.Windows.Thickness(1)
    $card.CornerRadius = New-Object System.Windows.CornerRadius(8)
    $card.Margin = '12,4,12,6'
    $editor = New-Object System.Windows.Controls.TextBox
    $editor.AcceptsReturn = $true; $editor.AcceptsTab = $true; $editor.IsReadOnly = $true
    $editor.FontFamily = New-Object System.Windows.Media.FontFamily('Consolas, Courier New, monospace')
    $editor.FontSize = 13; $editor.TextWrapping = 'NoWrap'
    $editor.VerticalScrollBarVisibility = 'Auto'; $editor.HorizontalScrollBarVisibility = 'Auto'
    $editor.BorderThickness = New-Object System.Windows.Thickness(0)
    $editor.Padding = '14,12'; $editor.Background = [System.Windows.Media.Brushes]::White
    $editor.Text = '(Enter a file path and click Load.)'
    $card.Child = $editor
    [System.Windows.Controls.Grid]::SetRow($card, 3); [void]$grid.Children.Add($card)

    # Row 4: restart-service option
    $opt = New-Object System.Windows.Controls.StackPanel
    $opt.Orientation = 'Horizontal'; $opt.Margin = '12,0,12,4'; $opt.VerticalAlignment = 'Center'
    $chkRestart = New-Object System.Windows.Controls.CheckBox
    $chkRestart.Content = 'Restart service after save:'; $chkRestart.VerticalAlignment = 'Center'; $chkRestart.Margin = '0,0,8,0'
    [void]$opt.Children.Add($chkRestart)
    $cmbService = New-Object System.Windows.Controls.ComboBox
    $cmbService.Width = 220; $cmbService.VerticalAlignment = 'Center'; $cmbService.IsEnabled = $false
    [void]$opt.Children.Add($cmbService)
    [System.Windows.Controls.Grid]::SetRow($opt, 4); [void]$grid.Children.Add($opt)

    # Row 5: buttons + status
    $bottom = New-Object System.Windows.Controls.Grid
    $bottom.Margin = '12,2,12,12'
    foreach ($w in @('*', 'Auto', 'Auto')) {
        $cd = New-Object System.Windows.Controls.ColumnDefinition
        $cd.Width = [System.Windows.GridLength]::new(1, $(if ($w -eq '*') { 'Star' } else { 'Auto' }))
        [void]$bottom.ColumnDefinitions.Add($cd)
    }
    $lblStatus = New-Object System.Windows.Controls.TextBlock
    $lblStatus.VerticalAlignment = 'Center'; $lblStatus.Foreground = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#475569'))
    $lblStatus.TextTrimming = 'CharacterEllipsis'
    [System.Windows.Controls.Grid]::SetColumn($lblStatus, 0); [void]$bottom.Children.Add($lblStatus)
    $btnSave = New-Object System.Windows.Controls.Button
    $btnSave.Content = 'Save'; $btnSave.Width = 100; $btnSave.Height = 28; $btnSave.Margin = '0,0,8,0'; $btnSave.IsEnabled = $false
    if ($primaryStyle) { $btnSave.Style = $primaryStyle }
    [System.Windows.Controls.Grid]::SetColumn($btnSave, 1); [void]$bottom.Children.Add($btnSave)
    $btnClose = New-Object System.Windows.Controls.Button
    $btnClose.Content = 'Close'; $btnClose.Width = 90; $btnClose.Height = 28; $btnClose.IsCancel = $true
    if ($secondaryStyle) { $btnClose.Style = $secondaryStyle }
    [System.Windows.Controls.Grid]::SetColumn($btnClose, 2); [void]$bottom.Children.Add($btnClose)
    [System.Windows.Controls.Grid]::SetRow($bottom, 5); [void]$grid.Children.Add($bottom)

    $win.Content = $grid
    $recorder = Enable-OneLinkWindowRecorder $win

    # ---- shared state (mutated inside closures via hashtable members) ----
    $state = @{ Loaded = $false; Path = $null; Host = $null; SuppressMatch = $false }

    $resolveServer = {
        if ($null -ne $cmbServer) {
            $h = [string]$cmbServer.SelectedItem
            return ($connected | Where-Object { [string]$_.Host -eq $h } | Select-Object -First 1)
        }
        return $connected[0]
    }.GetNewClosure()

    $populateServices = {
        $cmbService.Items.Clear()
        $srv = & $resolveServer
        if ($srv -and $srv.Services) {
            foreach ($svc in $srv.Services) {
                $item = New-Object System.Windows.Controls.ComboBoxItem
                $item.Content = [string]$svc.DisplayName
                $item.Tag = [string]$svc.SystemdName
                [void]$cmbService.Items.Add($item)
            }
        }
        if ($cmbService.Items.Count -gt 0) { $cmbService.SelectedIndex = 0 }
    }.GetNewClosure()
    & $populateServices

    if ($null -ne $cmbServer) {
        $cmbServer.Add_SelectionChanged({
            # Switching server invalidates the loaded content and any search hits.
            $state.Loaded = $false
            $btnSave.IsEnabled = $false
            $editor.IsReadOnly = $true
            $editor.Text = '(Server changed - click Load to read the file from this server.)'
            $lblStatus.Text = ''
            $state.SuppressMatch = $true
            $cmbMatches.Items.Clear()
            $state.SuppressMatch = $false
            $matchRow.Visibility = [System.Windows.Visibility]::Collapsed
            & $populateServices
        }.GetNewClosure())
    }

    $chkRestart.Add_Checked({ $cmbService.IsEnabled = $true }.GetNewClosure())
    $chkRestart.Add_Unchecked({ $cmbService.IsEnabled = $false }.GetNewClosure())

    # ---- Load ----
    $btnLoad.Add_Click({
        $path = ([string]$txtPath.Text).Trim()
        if ([string]::IsNullOrWhiteSpace($path)) { Show-WarningMessage 'Enter the full path of the file to edit.'; return }
        $srv = & $resolveServer
        if (-not $srv) { Show-WarningMessage 'No connected server selected.'; return }

        $operation = Start-OneLinkRecordedOperation $recorder
        $outcome = 'Failed'
        $remoteSeconds = $null
        $win.Cursor = [Windows.Input.Cursors]::Wait
        try {
            $tmpl = @'
F=__PATH__
if sudo -n test -f "$F" 2>/dev/null || test -f "$F" 2>/dev/null; then
  if sudo -n base64 -w0 "$F" 2>/dev/null; then echo; echo OLK_EDIT_OK
  elif base64 -w0 "$F" 2>/dev/null; then echo; echo OLK_EDIT_OK
  else echo OLK_EDIT_DENIED; fi
elif sudo -n test -e "$F" 2>/dev/null || test -e "$F" 2>/dev/null; then
  echo OLK_EDIT_NOTFILE
else
  echo OLK_EDIT_NOPATH
fi
'@
            $cmd = $tmpl.Replace('__PATH__', (ConvertTo-OneLinkBashArg $path))
            $res = Invoke-OneLinkSshCommand -Session $srv.Session -Command $cmd -TimeoutSeconds 60
            $remoteSeconds = ((Get-Date) - $operation.Started).TotalSeconds
            $out = [string]$res.Output
            $lines = @($out -split "`r?`n")

            if ($lines -contains 'OLK_EDIT_NOPATH') {
                Show-WarningMessage "No such file on $($srv.Host):`n$path"
                return
            }
            if ($lines -contains 'OLK_EDIT_NOTFILE') {
                Show-WarningMessage "That path exists but is not a regular file (it may be a directory):`n$path"
                return
            }
            if ($lines -contains 'OLK_EDIT_DENIED') {
                Show-WarningMessage "Permission denied reading '$path' on $($srv.Host). The account needs sudo rights to read this file."
                return
            }
            $okIdx = [array]::IndexOf($lines, 'OLK_EDIT_OK')
            if ($okIdx -lt 0) {
                Show-ErrorMessage "Could not read the file. Server response:`n$out"
                return
            }
            $b64 = ($lines[0..($okIdx - 1)] -join '').Trim()
            $text = ''
            if ($b64.Length -gt 0) {
                $bytes = $null
                try { $bytes = [Convert]::FromBase64String($b64) }
                catch { Show-ErrorMessage "The file content could not be read from the server."; return }
                # A NUL byte means the file is binary; editing it as text would
                # corrupt it on save, so refuse. Any TEXT file (regardless of
                # extension - .java, .py, .xml, .conf, .html, .sh, .txt, ...)
                # is fine.
                if ($bytes -contains [byte]0) {
                    Show-WarningMessage "'$path' looks like a binary file (it contains non-text data), so it can't be edited safely as text.`n`nUse Edit File for text-based files of any type (e.g. .xml, .properties, .conf, .java, .py, .sh, .txt, .html, .json, .yaml)."
                    return
                }
                $text = [System.Text.Encoding]::UTF8.GetString($bytes)
            }
            # Show with Windows line endings for comfortable editing.
            $editor.Text = ($text -replace "`r?`n", "`r`n")
            $editor.IsReadOnly = $false
            $btnSave.IsEnabled = $true
            $outcome = 'Success'
            $state.Loaded = $true
            $state.Path = $path
            $state.Host = [string]$srv.Host
            $lblStatus.Text = "Loaded from $($srv.Host):$path"
            Write-OneLinkLog "[$($srv.Host)] Edit File: loaded '$path' ($($text.Length) chars)." -Level Info
        }
        catch {
            Show-ErrorMessage "Failed to load the file: $($_.Exception.Message)"
        }
        finally {
            $win.Cursor = $null
            if ($null -eq $remoteSeconds) { $remoteSeconds = ((Get-Date) - $operation.Started).TotalSeconds }
            Complete-OneLinkActivity -Name 'Load File' -Target ([string]$srv.Host) -Outcome $outcome -OperationSeconds $remoteSeconds -Context $operation
            $recorder.Last = Get-Date
        }
    }.GetNewClosure())

    # ---- Find on server (locate a file by name when the path is unknown) ----
    $btnFind.Add_Click({
        $raw = ([string]$txtPath.Text).Trim()
        if ([string]::IsNullOrWhiteSpace($raw)) { Show-WarningMessage "Type a file name (or wildcard, e.g. *.properties) to search for, then click Find."; return }
        # Search by the file NAME only (drop any directory the user pasted).
        $name = if ($raw -match '/') { ($raw -split '/')[-1] } else { $raw }
        if ([string]::IsNullOrWhiteSpace($name)) { Show-WarningMessage "Enter a file name to search for."; return }
        $srv = & $resolveServer
        if (-not $srv) { Show-WarningMessage 'No connected server selected.'; return }

        # A wildcard search (*, ?) is taken literally; a plain name is matched
        # loosely (ignoring spaces, brackets/parens and case). For the loose case
        # we cast a WIDE net on the server using the longest alphanumeric chunk of
        # the name as a substring glob, then filter locally by the loose key so
        # "license 3.lic" also finds "license (3).lic", "license(3).lic", etc.
        $isWildcard = ($name -match '[\*\?]')
        if ($isWildcard) {
            $glob = $name
        }
        else {
            $chunks = @([regex]::Matches($name, '[A-Za-z0-9]+') | ForEach-Object { $_.Value })
            $anchor = if ($chunks.Count -gt 0) { ($chunks | Sort-Object { $_.Length } -Descending | Select-Object -First 1) } else { $name }
            $glob = "*$anchor*"
        }
        # Loose key of what the user typed (drop extension separately so a name
        # typed without an extension can still match files that have one).
        $typedHasExt = ($name -match '\.[^.\\/]+$')
        $typedKey     = ConvertTo-OneLinkLooseKey $name
        $typedKeyNoExt = ConvertTo-OneLinkLooseKey ($name -replace '\.[^.\\/]+$', '')

        $operation = Start-OneLinkRecordedOperation $recorder
        $outcome = 'Failed'
        $remoteSeconds = $null
        $win.Cursor = [Windows.Input.Cursors]::Wait
        $lblStatus.Text = "Searching $($srv.Host) for '$name'..."
        try {
            # Search the whole filesystem, pruning virtual/volatile trees for speed.
            # Case-insensitive; the glob is passed as a single quoted arg so it is
            # expanded by find, not the shell.
            $tmpl = @'
N=__NAME__
R=$( { sudo -n find / \( -path /proc -o -path /sys -o -path /dev -o -path /run -o -path /snap -o -path /var/lib/docker \) -prune -o -type f -iname "$N" -print 2>/dev/null || find / \( -path /proc -o -path /sys -o -path /dev -o -path /run -o -path /snap -o -path /var/lib/docker \) -prune -o -type f -iname "$N" -print 2>/dev/null ; } | sort -u | head -n 500 )
if [ -n "$R" ]; then printf '%s\n' "$R"; else echo OLK_FIND_NONE; fi
echo OLK_FIND_DONE
'@
            $cmd = $tmpl.Replace('__NAME__', (ConvertTo-OneLinkBashArg $glob))
            $res = Invoke-OneLinkSshCommand -Session $srv.Session -Command $cmd -TimeoutSeconds 150
            $remoteSeconds = ((Get-Date) - $operation.Started).TotalSeconds
            $out = [string]$res.Output
            $lines = @($out -split "`r?`n")
            $doneIdx = [array]::IndexOf($lines, 'OLK_FIND_DONE')
            if ($doneIdx -ge 0) { $outcome = 'Success' }
            $body = if ($doneIdx -ge 0) { @($lines[0..([Math]::Max(0,$doneIdx-1))]) } else { $lines }
            $candidates = @($body | Where-Object { $_ -match '^/' } )

            # For a plain name, keep only candidates whose file name matches the
            # loose key (wildcard searches keep every hit as-is).
            if ($isWildcard) {
                $found = $candidates
            }
            else {
                $found = @($candidates | Where-Object {
                    $leaf = ($_ -split '/')[-1]
                    if ($typedHasExt) {
                        (ConvertTo-OneLinkLooseKey $leaf) -eq $typedKey
                    }
                    else {
                        # user gave no extension: compare against the file name with
                        # its extension stripped, so "license (3)" matches "license (3).lic".
                        (ConvertTo-OneLinkLooseKey ($leaf -replace '\.[^.\\/]+$', '')) -eq $typedKeyNoExt
                    }
                })
            }

            if ($found.Count -eq 0 -or ($body -contains 'OLK_FIND_NONE')) {
                $matchRow.Visibility = [System.Windows.Visibility]::Collapsed
                $lblStatus.Text = ''
                Show-WarningMessage "No file matching '$name' was found on $($srv.Host)."
                return
            }

            $state.SuppressMatch = $true
            $cmbMatches.Items.Clear()
            foreach ($f in $found) { [void]$cmbMatches.Items.Add([string]$f) }
            $cmbMatches.SelectedIndex = -1
            $state.SuppressMatch = $false
            $matchRow.Visibility = [System.Windows.Visibility]::Visible
            $lblStatus.Text = "Found $($found.Count) match(es) on $($srv.Host) - pick one to load it."
            Write-OneLinkLog "[$($srv.Host)] Edit File: found $($found.Count) file(s) named '$name'." -Level Info
            if ($found.Count -eq 1) {
                # Exactly one hit: select it so the user can just click Load (or it auto-loads).
                $cmbMatches.SelectedIndex = 0
            }
        }
        catch {
            Show-ErrorMessage "Search failed on $($srv.Host): $($_.Exception.Message)"
        }
        finally {
            $win.Cursor = $null
            if ($null -eq $remoteSeconds) { $remoteSeconds = ((Get-Date) - $operation.Started).TotalSeconds }
            Complete-OneLinkActivity -Name 'Find File' -Target ([string]$srv.Host) -Outcome $outcome -OperationSeconds $remoteSeconds -Context $operation
            $recorder.Last = Get-Date
        }
    }.GetNewClosure())

    # Picking a match fills the path box and loads that file.
    $cmbMatches.Add_SelectionChanged({
        if ($state.SuppressMatch) { return }
        $sel = [string]$cmbMatches.SelectedItem
        if ([string]::IsNullOrWhiteSpace($sel)) { return }
        $txtPath.Text = $sel
        $btnLoad.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
    }.GetNewClosure())

    # Enter in the path box: an absolute path (with no wildcard) loads directly;
    # anything else (a bare name or a wildcard) triggers a Find.
    $txtPath.Add_KeyDown({
        param($s, $e)
        if ($e.Key -eq [System.Windows.Input.Key]::Return) {
            $e.Handled = $true
            $t = ([string]$txtPath.Text).Trim()
            if ($t -match '^/' -and $t -notmatch '[\*\?]') {
                $btnLoad.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
            }
            else {
                $btnFind.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent)))
            }
        }
    }.GetNewClosure())

    # ---- Save ----
    $btnSave.Add_Click({
        if (-not $state.Loaded) { Show-WarningMessage 'Load a file before saving.'; return }
        $srv = & $resolveServer
        if (-not $srv -or [string]$srv.Host -ne $state.Host) {
            Show-WarningMessage 'The selected server changed since the file was loaded. Click Load again first.'
            return
        }
        $path = $state.Path

        $svcName = $null
        if ($chkRestart.IsChecked) {
            if ($cmbService.SelectedItem -and $cmbService.SelectedItem.Tag) { $svcName = [string]$cmbService.SelectedItem.Tag }
            if ([string]::IsNullOrWhiteSpace($svcName)) { Show-WarningMessage 'Choose a service to restart, or untick the restart option.'; return }
        }

        $confirm = [System.Windows.MessageBox]::Show(
            "Save changes to:`n$($srv.Host):$path`n`nA backup (.bak) will be made first and the file's owner and permissions will be preserved." +
            $(if ($svcName) { "`n`nThe service '$svcName' will be restarted after saving." } else { '' }),
            "$($script:AppName) - confirm save", 'OKCancel', 'Question')
        if ($confirm -ne [System.Windows.MessageBoxResult]::OK) { return }

        # Normalise to Unix line endings before writing to the Linux file.
        $content = ($editor.Text -replace "`r`n", "`n")
        $b64 = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($content))

        $operation = Start-OneLinkRecordedOperation $recorder
        $outcome = 'Failed'
        $saveSeconds = 0.0
        $win.Cursor = [Windows.Input.Cursors]::Wait
        try {
            $tmpl = @'
F=__PATH__
B=__B64__
TS=$(date +%Y%m%d%H%M%S)
{ sudo -n cp -p -f "$F" "$F.bak.$TS" 2>/dev/null || cp -p -f "$F" "$F.bak.$TS" 2>/dev/null; } || true
{ sudo -n cp -p -f "$F" "$F.bak" 2>/dev/null || cp -p -f "$F" "$F.bak" 2>/dev/null; } || true
if printf '%s' "$B" | base64 -d | { sudo -n tee "$F" >/dev/null 2>&1 || tee "$F" >/dev/null 2>&1; }; then
  echo OLK_SAVE_OK
else
  echo OLK_SAVE_FAIL
fi
'@
            $cmd = $tmpl.Replace('__PATH__', (ConvertTo-OneLinkBashArg $path)).Replace('__B64__', (ConvertTo-OneLinkBashArg $b64))
            $res = Invoke-OneLinkSshCommand -Session $srv.Session -Command $cmd -TimeoutSeconds 90
            $saveSeconds = ((Get-Date) - $operation.Started).TotalSeconds
            $out = [string]$res.Output
            if (($out -split "`r?`n") -notcontains 'OLK_SAVE_OK') {
                Show-ErrorMessage "Save failed on $($srv.Host). Server response:`n$out`n$($res.Error)"
                return
            }
            Write-OneLinkLog "[$($srv.Host)] Edit File: saved '$path' (backup '$path.bak' created; owner/permissions preserved)." -Level Success

            $outcome = 'Success'
            if ($svcName) {
                $restartStart = Get-Date
                $restartOutcome = 'Failed'
                try {
                    Invoke-NMenuServiceAction -Session $srv.Session -Settings $settings -SystemdName $svcName -Action Restart | Out-Null
                    Write-OneLinkLog "[$($srv.Host)] Edit File: restarted service '$svcName' after save." -Level Success
                    $restartOutcome = 'Success'
                    $restartSeconds = ((Get-Date) - $restartStart).TotalSeconds
                    $lblStatus.Text = "Saved and restarted '$svcName' on $($srv.Host)."
                    Show-InfoMessage "Saved '$path' on $($srv.Host) and restarted '$svcName'.`nA backup was written to '$path.bak'."
                }
                catch {
                    Write-OneLinkLog "[$($srv.Host)] Edit File: save OK but service restart failed: $($_.Exception.Message)" -Level Warning
                    $outcome = 'Partial'
                    $restartSeconds = ((Get-Date) - $restartStart).TotalSeconds
                    $lblStatus.Text = "Saved on $($srv.Host); service restart failed."
                    Show-WarningMessage "The file was saved, but restarting '$svcName' failed:`n$($_.Exception.Message)"
                }
                finally {
                    $restartContext = @{ Clicks = 0; Fields = @(); ActiveSeconds = 0; Generation = $operation.Generation; Frozen = $true }
                    Complete-OneLinkActivity -Name ("Restart service ($svcName)") -Target ([string]$srv.Host) -Outcome $restartOutcome -OperationSeconds $restartSeconds -Context $restartContext
                }
            }
            else {
                $lblStatus.Text = "Saved to $($srv.Host):$path (backup: $path.bak)"
                Show-InfoMessage "Saved '$path' on $($srv.Host).`nA backup was written to '$path.bak'."
            }
        }
        catch {
            if ($saveSeconds -eq 0) { $saveSeconds = ((Get-Date) - $operation.Started).TotalSeconds }
            Show-ErrorMessage "Failed to save the file: $($_.Exception.Message)"
        }
        finally {
            $win.Cursor = $null
            Complete-OneLinkActivity -Name 'Save File' -Target ([string]$srv.Host) -Outcome $outcome -OperationSeconds $saveSeconds -Context $operation
            $recorder.Last = Get-Date
        }
    }.GetNewClosure())

    $win.Add_Closed({ Complete-OneLinkActivity -Name 'Close File Editor' -Target ([string]$state.Host) -Outcome 'Closed' -Context $recorder }.GetNewClosure())
    $btnClose.Add_Click({ $win.Close() }.GetNewClosure())

    # Non-modal: keep it open while you use the rest of Foreman (and open more than one).
    [void]$win.Show()
}

# Strip ANSI/terminal control sequences so shell output shows as clean text in a
# plain WPF textbox. (A textbox is not a full terminal emulator, so full-screen
# apps like vim/top still won't render - this just keeps ordinary command output
# readable instead of littered with escape codes.)
function Remove-OneLinkAnsi {
    param([AllowEmptyString()][string]$Text)
    $t = [string]$Text
    $t = [regex]::Replace($t, "\x1B\[[0-9;?=]*[ -/]*[@-~]", '')   # CSI (colours, cursor moves)
    $t = [regex]::Replace($t, "\x1B\][^\x07\x1B]*(\x07|\x1B\\)", '') # OSC (title, etc.)
    $t = [regex]::Replace($t, "\x1B[@-Z\\-_]", '')                  # other single-char escapes
    $t = $t -replace "\x07", ''                                     # bell
    $t = $t -replace "\r", ''                                       # bare carriage returns
    return $t
}

# Detect a full-screen / interactive (curses) program that the plain-text
# console can't render and that would hijack all further input (nano, vim, top,
# less, man, ...). Returns the offending program name, or $null if the command
# is fine to run. Skips leading wrappers (sudo, env, VAR=val, nohup, ...) and
# checks every segment of a pipeline / '&&' / ';' chain.
function Test-OneLinkInteractiveCommand {
    param([string]$CommandLine)

    $interactive = @(
        'nano','pico','vi','vim','view','vimdiff','nvim','emacs','emacsclient','mcedit','micro','joe','jed','ne','ed',
        'top','htop','atop','btop','iotop','iftop','nmon','glances',
        'less','more','most','man',
        'watch','mc','ranger','vifm',
        'tmux','screen','byobu',
        'dialog','whiptail','nmtui','alsamixer',
        'tig','lynx','links','elinks','w3m','info','visudo'
    )
    $wrappers = @('sudo','env','nice','nohup','time','command','exec','builtin','stdbuf','setsid','\')

    foreach ($seg in ($CommandLine -split '(&&|\|\||;|\||&)')) {
        $s = $seg.Trim()
        if ($s -eq '' -or $s -in @('&&','||',';','|','&')) { continue }
        $tokens = @($s -split '\s+' | Where-Object { $_ -ne '' })
        if ($tokens.Count -eq 0) { continue }

        $i = 0
        while ($i -lt $tokens.Count) {
            $tok = $tokens[$i]
            if ($tok -match '^[A-Za-z_][A-Za-z0-9_]*=') { $i++; continue }   # VAR=value prefix
            if ($tok -in $wrappers) {
                $i++
                while ($i -lt $tokens.Count -and $tokens[$i].StartsWith('-')) {
                    if ($tokens[$i] -in @('-u','-g','-p')) { $i += 2 } else { $i++ }   # sudo -u user, etc.
                }
                continue
            }
            break
        }
        if ($i -ge $tokens.Count) { continue }

        $prog = ($tokens[$i] -split '/')[-1].ToLower()
        $rest = if ($i + 1 -le $tokens.Count - 1) { @($tokens[($i + 1)..($tokens.Count - 1)]) } else { @() }

        if ($prog -in $interactive) { return $prog }
        if ($prog -eq 'crontab'   -and ($rest -contains '-e'))   { return 'crontab -e' }
        if ($prog -eq 'systemctl' -and ($rest -contains 'edit')) { return 'systemctl edit' }
    }
    return $null
}

# ----------------------------------------------------------------------------
#  In-tool SSH Console
#  ---------------------------------------------------------------------------
#  A lightweight command console over the already-embedded Posh-SSH shell stream
#  (New-SSHShellStream) - NO extra dependency. It runs on a persistent PTY, so
#  cd / environment / passwordless sudo carry over between commands, and you can
#  run anything (touch, chmod, systemctl status, tail, ...). Output is polled on
#  a DispatcherTimer so the UI never blocks. It is NOT a full terminal emulator:
#  full-screen curses apps (vim, top, nano, less, dialog menus) won't render -
#  use PuTTY for those.
# ----------------------------------------------------------------------------
function Show-OneLinkSshConsole {
    param([object]$Server = $null)   # when set (e.g. from a server row's right-click), use that server directly
    $connected = @($script:Servers | Where-Object { $null -ne $_.Session -and -not [string]::IsNullOrWhiteSpace($_.Host) })
    if ($connected.Count -eq 0) {
        Show-WarningMessage "Connect to at least one server first, then open the SSH Console."
        return
    }
    if ($null -ne $Server) {
        if ($null -eq $Server.Session) { Show-WarningMessage "Connect to $($Server.Host) first, then open its console."; return }
        $connected = @($Server)
    }

    # Capture settings into a LOCAL so the closures below (GetNewClosure) see it -
    # inside a closure, $script:Settings resolves to the closure's own scope, not
    # the real script scope, so referencing it there would be $null.
    $settings = $script:Settings

    $win = New-Object System.Windows.Window
    $win.Title = 'SSH Console'
    $win.Width = 940; $win.Height = 640
    $win.MinWidth = 560; $win.MinHeight = 400
    $win.WindowStartupLocation = 'CenterScreen'
    $win.Background = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#F5F7FB'))
    if ($script:Window) { $win.Owner = $script:Window }

    $grid = New-Object System.Windows.Controls.Grid
    # Rows: 0 header, 1 server, 2 output(*), 3 input
    foreach ($h in @('Auto', 'Auto', '*', 'Auto')) {
        $rd = New-Object System.Windows.Controls.RowDefinition
        $rd.Height = [System.Windows.GridLength]::new(1, $(if ($h -eq '*') { 'Star' } else { 'Auto' }))
        [void]$grid.RowDefinitions.Add($rd)
    }

    # Row 0: header
    $hdr = New-Object System.Windows.Controls.Border
    $hdr.Background = New-OneLinkHeaderBrush
    $hdr.Padding = '16,11'
    $htxt = New-Object System.Windows.Controls.TextBlock
    $htxt.Text = 'SSH Console'; $htxt.Foreground = [System.Windows.Media.Brushes]::White; $htxt.FontSize = 15; $htxt.FontWeight = 'Bold'
    $hdr.Child = $htxt
    [System.Windows.Controls.Grid]::SetRow($hdr, 0); [void]$grid.Children.Add($hdr)

    # Row 1: server + Clear
    $top = New-Object System.Windows.Controls.Grid
    $top.Margin = '12,12,12,4'
    foreach ($w in @('Auto', 'Auto', '*', 'Auto')) {
        $cd = New-Object System.Windows.Controls.ColumnDefinition
        $cd.Width = [System.Windows.GridLength]::new(1, $(if ($w -eq '*') { 'Star' } else { 'Auto' }))
        [void]$top.ColumnDefinitions.Add($cd)
    }
    $lblSrv = New-Object System.Windows.Controls.TextBlock
    $lblSrv.Text = 'Server:'; $lblSrv.VerticalAlignment = 'Center'; $lblSrv.Margin = '0,0,8,0'; $lblSrv.FontWeight = 'SemiBold'
    [System.Windows.Controls.Grid]::SetColumn($lblSrv, 0); [void]$top.Children.Add($lblSrv)

    $secondaryStyle = Get-OneLinkStyle 'SecondaryButtonStyle'
    $primaryStyle = Get-OneLinkStyle 'PrimaryButtonStyle'

    $cmbServer = $null
    if ($connected.Count -eq 1) {
        $lblSrvValue = New-Object System.Windows.Controls.TextBlock
        $lblSrvValue.Text = [string]$connected[0].Host
        $lblSrvValue.VerticalAlignment = 'Center'
        [System.Windows.Controls.Grid]::SetColumn($lblSrvValue, 1); [void]$top.Children.Add($lblSrvValue)
    }
    else {
        $cmbServer = New-Object System.Windows.Controls.ComboBox
        $cmbServer.Width = 200; $cmbServer.VerticalAlignment = 'Center'
        foreach ($s in $connected) { [void]$cmbServer.Items.Add([string]$s.Host) }
        $cmbServer.SelectedIndex = 0
        [System.Windows.Controls.Grid]::SetColumn($cmbServer, 1); [void]$top.Children.Add($cmbServer)
    }

    $btnClear = New-Object System.Windows.Controls.Button
    $btnClear.Content = 'Clear'; $btnClear.Width = 84; $btnClear.Height = 28
    if ($secondaryStyle) { $btnClear.Style = $secondaryStyle }
    [System.Windows.Controls.Grid]::SetColumn($btnClear, 3); [void]$top.Children.Add($btnClear)
    [System.Windows.Controls.Grid]::SetRow($top, 1); [void]$grid.Children.Add($top)

    # Row 2: output (terminal-like)
    $card = New-Object System.Windows.Controls.Border
    $card.Background = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#111827'))
    $card.CornerRadius = New-Object System.Windows.CornerRadius(8)
    $card.Margin = '12,4,12,6'
    $out = New-Object System.Windows.Controls.TextBox
    $out.IsReadOnly = $true; $out.AcceptsReturn = $true
    $out.FontFamily = New-Object System.Windows.Media.FontFamily('Consolas, Courier New, monospace')
    $out.FontSize = 13; $out.TextWrapping = 'NoWrap'
    $out.VerticalScrollBarVisibility = 'Auto'; $out.HorizontalScrollBarVisibility = 'Auto'
    $out.BorderThickness = New-Object System.Windows.Thickness(0)
    $out.Padding = '12,10'
    $out.Background = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#111827'))
    $out.Foreground = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#D1FAE5'))
    $out.Text = ''
    $card.Child = $out
    [System.Windows.Controls.Grid]::SetRow($card, 2); [void]$grid.Children.Add($card)

    # Row 3: input + Run + Close
    $bottom = New-Object System.Windows.Controls.Grid
    $bottom.Margin = '12,2,12,12'
    foreach ($w in @('Auto', '*', 'Auto', 'Auto')) {
        $cd = New-Object System.Windows.Controls.ColumnDefinition
        $cd.Width = [System.Windows.GridLength]::new(1, $(if ($w -eq '*') { 'Star' } else { 'Auto' }))
        [void]$bottom.ColumnDefinitions.Add($cd)
    }
    $prompt = New-Object System.Windows.Controls.TextBlock
    $prompt.Text = '$'; $prompt.VerticalAlignment = 'Center'; $prompt.Margin = '2,0,8,0'; $prompt.FontFamily = New-Object System.Windows.Media.FontFamily('Consolas'); $prompt.FontWeight = 'Bold'
    [System.Windows.Controls.Grid]::SetColumn($prompt, 0); [void]$bottom.Children.Add($prompt)
    $in = New-Object System.Windows.Controls.TextBox
    $in.VerticalAlignment = 'Center'; $in.Height = 28; $in.Margin = '0,0,8,0'; $in.VerticalContentAlignment = 'Center'; $in.Padding = '6,0'
    $in.FontFamily = New-Object System.Windows.Media.FontFamily('Consolas, Courier New, monospace')
    $in.ToolTip = 'Type a command and press Enter (or click Run). Runs on a persistent shell, so cd and sudo carry over.'
    [System.Windows.Controls.Grid]::SetColumn($in, 1); [void]$bottom.Children.Add($in)
    $btnRun = New-Object System.Windows.Controls.Button
    $btnRun.Content = 'Run'; $btnRun.Width = 90; $btnRun.Height = 28; $btnRun.Margin = '0,0,8,0'
    if ($primaryStyle) { $btnRun.Style = $primaryStyle }
    [System.Windows.Controls.Grid]::SetColumn($btnRun, 2); [void]$bottom.Children.Add($btnRun)
    $btnClose = New-Object System.Windows.Controls.Button
    $btnClose.Content = 'Close'; $btnClose.Width = 84; $btnClose.Height = 28; $btnClose.IsCancel = $true
    if ($secondaryStyle) { $btnClose.Style = $secondaryStyle }
    [System.Windows.Controls.Grid]::SetColumn($btnClose, 3); [void]$bottom.Children.Add($btnClose)
    [System.Windows.Controls.Grid]::SetRow($bottom, 3); [void]$grid.Children.Add($bottom)

    $win.Content = $grid
    $recorder = Enable-OneLinkWindowRecorder $win

    # ---- state + shell stream (polled by a DispatcherTimer; UI never blocks) ----
    $state = @{ Stream = $null; Host = $null; Pending = (New-Object System.Collections.ArrayList); Buffer = ''; Timeout = [math]::Max(30, [int]$settings.Ssh.CommandTimeoutSeconds) }

    $resolveServer = {
        if ($null -ne $cmbServer) {
            $h = [string]$cmbServer.SelectedItem
            return ($connected | Where-Object { [string]$_.Host -eq $h } | Select-Object -First 1)
        }
        return $connected[0]
    }.GetNewClosure()

    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(120)
    $timer.Add_Tick({
        if ($null -eq $state.Stream) { return }
        try {
            if ($state.Stream.DataAvailable) {
                $chunk = $state.Stream.Read()
                if (-not [string]::IsNullOrEmpty($chunk)) {
                    $out.AppendText([string](Update-OneLinkConsoleRecording -State $state -Chunk (Remove-OneLinkAnsi $chunk)))
                    $out.ScrollToEnd()
                }
            }
        }
        catch { Update-OneLinkConsoleRecording -State $state -Closing | Out-Null }
        $out.AppendText([string](Update-OneLinkConsoleRecording -State $state))
    }.GetNewClosure())

    $openStream = {
        $timer.Stop()
        Update-OneLinkConsoleRecording -State $state -Closing | Out-Null
        $state.Buffer = ''
        if ($null -ne $state.Stream) { try { $state.Stream.Dispose() } catch { } ; $state.Stream = $null }
        $srv = & $resolveServer
        if (-not $srv) { return }
        try {
            $state.Stream = New-OneLinkShellStream -Session $srv.Session -Settings $settings
            $state.Host = [string]$srv.Host
            # Neutralise pagers so commands that would normally open 'less'
            # (git log, journalctl, systemctl status, man, ...) just print their
            # output instead of hanging the console waiting for a pager.
            try { $state.Stream.WriteLine('export PAGER=cat GIT_PAGER=cat SYSTEMD_PAGER=cat MANPAGER=cat 2>/dev/null') } catch { }
            $out.AppendText("=== Connected to $($srv.Host). Type a command and press Enter. ===`r`n")
            $out.ScrollToEnd()
            $timer.Start()
            $in.Focus() | Out-Null
        }
        catch {
            Show-ErrorMessage "Could not open a shell on $($srv.Host): $($_.Exception.Message)"
        }
    }.GetNewClosure()

    $runCmd = {
        if ($null -eq $state.Stream) { Show-WarningMessage 'The console is not connected yet.'; return }
        $cmd = [string]$in.Text
        if ([string]::IsNullOrWhiteSpace($cmd)) { return }
        # Refuse full-screen / interactive programs the console can't render (they
        # would garble the output and capture all further input).
        $bad = Test-OneLinkInteractiveCommand $cmd
        if ($null -ne $bad) {
            $out.AppendText("`r`n[Command Console] '$bad' is an interactive / full-screen program and can't run in this console." +
                "`r`n  - To edit a file, use the 'Edit File' button." +
                "`r`n  - To view a file, try: cat <file>   (or: tail -n 100 <file>)." +
                "`r`n  - For anything full-screen (nano, vim, top, less, ...), use PuTTY.`r`n")
            $out.ScrollToEnd()
            $in.Clear()
            return
        }
        if (-not (Test-OneLinkRecorderCapture)) {
            try { $state.Stream.WriteLine($cmd) }
            catch { Show-ErrorMessage "Failed to send the command: $($_.Exception.Message)"; return }
            $in.Clear()
            return
        }
        $operation = Start-OneLinkRecordedOperation $recorder
        $token = 'OLK_METRIC_' + [guid]::NewGuid().ToString('N')
        $pending = @{ Token = $token; Host = $state.Host; Context = $operation }
        try {
            # A unique marker reports the shell's exit status after this command.
            # Keep the existing persistent shell; cd/export/sudo behavior is retained.
            $suffix = 'printf ''\n' + $token + ':%s\n'' "$?"'
            [void]$state.Pending.Add($pending)
            # Parse the marker on the same shell line so an interactive command
            # cannot consume a queued marker line as its input.
            $state.Stream.WriteLine('eval ' + (ConvertTo-OneLinkBashArg $cmd) + '; ' + $suffix)
        }
        catch {
            [void]$state.Pending.Remove($pending)
            Complete-OneLinkActivity -Name 'SSH Command' -Target ([string]$state.Host) -Outcome 'Failed' -Context $operation
            Show-ErrorMessage "Failed to send the command: $($_.Exception.Message)"; return
        }
        $in.Clear()
    }.GetNewClosure()

    $btnRun.Add_Click($runCmd)
    $in.Add_KeyDown({
        param($s, $e)
        if ($e.Key -eq [System.Windows.Input.Key]::Return) { $e.Handled = $true; & $runCmd }
    }.GetNewClosure())
    $btnClear.Add_Click({ $out.Clear(); Complete-OneLinkActivity -Name 'Clear SSH Console' -Target ([string]$state.Host) -Context $recorder }.GetNewClosure())
    if ($null -ne $cmbServer) { $cmbServer.Add_SelectionChanged({ $out.Clear(); & $openStream }.GetNewClosure()) }

    $btnClose.Add_Click({ $win.Close() }.GetNewClosure())

    $win.Add_ContentRendered({ & $openStream }.GetNewClosure())
    $win.Add_Closed({
        try { $timer.Stop() } catch { }
        Complete-OneLinkActivity -Name 'Close SSH Console' -Target ([string]$state.Host) -Outcome 'Closed' -Context $recorder
        Update-OneLinkConsoleRecording -State $state -Closing | Out-Null
        if ($null -ne $state.Stream) { try { $state.Stream.Dispose() } catch { } ; $state.Stream = $null }
    }.GetNewClosure())

    # Non-modal: keep the console open while you use the rest of Foreman (and open
    # more than one - e.g. a console per server).
    [void]$win.Show()
}

function Get-ComboText {
    param($ComboBox)
    if ($null -eq $ComboBox.SelectedItem) { return "" }
    if ($ComboBox.SelectedItem.PSObject.Properties.Name -contains 'Content') {
        return [string]$ComboBox.SelectedItem.Content
    }
    return [string]$ComboBox.SelectedItem
}

# Decrypt a SecureString to plain text (used only to pre-fill / reveal a stored
# password in the Set-Password dialog; the value stays in memory for this session).
function ConvertFrom-OneLinkSecure {
    param([AllowNull()]$Secure)
    if ($null -eq $Secure -or $Secure.Length -eq 0) { return '' }
    $bstr = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($Secure)
    try { return [System.Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr) }
    finally { [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr) }
}

# Safely refresh a DataGrid. A DataGrid throws "Refresh is not allowed during an
# AddNew or EditItem transaction" if a cell/row is mid-edit, so commit any
# pending edit first. All calls are guarded so a refresh can never surface an
# exception to the user.
function Invoke-GridRefresh {
    param($Grid)
    try { [void]$Grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Cell, $true) } catch { }
    try { [void]$Grid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row, $true) }  catch { }
    try { $Grid.Items.Refresh() } catch { }
}

# Startup self-check for the embedded Posh-SSH module. This runs on EVERY launch
# and validates the blob REGARDLESS of whether this machine already has Posh-SSH
# installed - so an incomplete build (compiled without the embedded module) is
# caught immediately on the builder's own machine, instead of only failing later
# on a clean machine that has no Posh-SSH to fall back on.
function Confirm-OneLinkPoshSsh {
    $b = $script:PoshSshZipBase64
    # A real blob is a large base64 string; the un-injected placeholder is tiny.
    $embeddedOk = (-not [string]::IsNullOrWhiteSpace($b)) -and ($b.Trim().Length -ge 100000)
    $machineHas = [bool](Get-Module -ListAvailable -Name Posh-SSH -ErrorAction SilentlyContinue)

    if (-not $embeddedOk) {
        $msg = "INCOMPLETE BUILD: this EXE was compiled WITHOUT the embedded Posh-SSH module." + [Environment]::NewLine +
               "It may work on machines that already have Posh-SSH installed, but it WILL FAIL on a clean machine." + [Environment]::NewLine + [Environment]::NewLine +
               "Rebuild from the full source - run Build.ps1 (recommended)."
        Write-OneLinkLog "INCOMPLETE BUILD: embedded Posh-SSH module is missing from this EXE. Rebuild with Build.ps1." -Level Error
        [System.Windows.MessageBox]::Show($msg, "$($script:AppName) - incomplete build", 'OK', 'Warning') | Out-Null
        return
    }

    if ($machineHas) {
        Write-OneLinkLog "Posh-SSH is present on this machine (embedded copy verified as a fallback)." -Level Info
        return
    }

    # Clean machine: prepare the bundled copy now so any problem shows at launch.
    # Detect whether this is the FIRST time (manifest not yet extracted) so we can
    # show a one-time, per-machine "dependency set up" notice.
    $modulesRoot = Join-Path $env:LOCALAPPDATA 'OneLinkAdminTool\Modules'
    $manifest = Join-Path $modulesRoot ("Posh-SSH\" + $script:PoshSshEmbeddedVersion + "\Posh-SSH.psd1")
    $firstRun = -not (Test-Path -LiteralPath $manifest)

    try {
        Initialize-EmbeddedPoshSsh
        if ($firstRun) {
            Write-OneLinkLog "First-run setup: bundled Posh-SSH extracted to $modulesRoot (per-user, no admin)." -Level Success
            [System.Windows.MessageBox]::Show(
                "First-time setup complete." + [Environment]::NewLine + [Environment]::NewLine +
                "This tool needs the Posh-SSH component for SSH/SCP. It is bundled inside the application, so nothing has to be installed manually - it was just prepared for this machine (per-user folder, no admin rights, no internet required)." + [Environment]::NewLine + [Environment]::NewLine +
                "You won't see this message again on this machine.",
                "$($script:AppName) - dependency ready", 'OK', 'Information') | Out-Null
        }
        else {
            Write-OneLinkLog "Bundled Posh-SSH ready (already prepared on this machine)." -Level Info
        }
    }
    catch {
        Write-OneLinkLog "Bundled Posh-SSH preparation warning: $($_.Exception.Message)" -Level Warning
    }
}

# Return the servers that have a non-empty host, as strings.
function Get-OneLinkServerHosts {
    return @($script:Servers | Where-Object { -not [string]::IsNullOrWhiteSpace($_.Host) } | ForEach-Object { [string]$_.Host })
}

# Rebuild the generic "Target server" combos (Package, Services, SSL):
# "All servers" + every server host.
# ---- Multi-select target pickers -------------------------------------------
# Connected servers eligible for a picker (all connected; DB-marked only for 'Db').
function Get-OneLinkEligibleTargets {
    param([string]$Key)
    $connected = @($script:Servers | Where-Object { $null -ne $_.Session })
    if ($script:TargetPickers[$Key].DbOnly) {
        return @($connected | Where-Object { $_.HasRole('Database master') -or $_.HasRole('Database slave') })
    }
    return @($connected)
}

# Update a picker button's label from the ticks in its panel.
function Update-OneLinkTargetButton {
    param([string]$Key)
    $reg = $script:TargetPickers[$Key]
    $allChecked = $false; $hosts = @()
    foreach ($ch in $reg.Panel.Children) {
        if ($ch -is [System.Windows.Controls.CheckBox]) {
            if ([string]$ch.Tag -eq '__ALL__') { $allChecked = [bool]$ch.IsChecked }
            elseif ($ch.IsChecked) { $hosts += [string]$ch.Tag }
        }
    }
    if ($allChecked) { $reg.Button.Content = 'All servers' }
    elseif ($hosts.Count -eq 0) { $reg.Button.Content = $(if ($reg.DbOnly) { 'No DB server' } else { 'None selected' }) }
    elseif ($hosts.Count -eq 1) { $reg.Button.Content = $hosts[0] }
    else { $reg.Button.Content = "$($hosts.Count) servers" }
}

# The connected servers a picker currently targets: 'All' -> every eligible server;
# otherwise the individually-ticked hosts (empty array if none ticked).
function Get-OneLinkTargetHosts {
    param([string]$Key)
    $reg = $script:TargetPickers[$Key]
    $eligible = @(Get-OneLinkEligibleTargets -Key $Key)
    $allChecked = $false; $hosts = @()
    foreach ($ch in $reg.Panel.Children) {
        if ($ch -is [System.Windows.Controls.CheckBox]) {
            if ([string]$ch.Tag -eq '__ALL__') { $allChecked = [bool]$ch.IsChecked }
            elseif ($ch.IsChecked) { $hosts += [string]$ch.Tag }
        }
    }
    if ($allChecked) { return @($eligible) }
    return @($eligible | Where-Object { $hosts -contains [string]$_.Host })
}

# Rebuild a picker's checkbox panel from the eligible servers, preserving the prior
# selection. 'All servers' checkbox at the top; ticking a server clears All and vice
# versa. Programmatic IsChecked changes don't fire Click, so there is no re-entrancy.
function Update-OneLinkTargetPicker {
    param([string]$Key)
    $reg = $script:TargetPickers[$Key]
    $panel = $reg.Panel

    $priorAll = $false; $priorHosts = @(); $hadAny = $false
    foreach ($ch in $panel.Children) {
        if ($ch -is [System.Windows.Controls.CheckBox]) {
            $hadAny = $true
            if ([string]$ch.Tag -eq '__ALL__') { $priorAll = [bool]$ch.IsChecked }
            elseif ($ch.IsChecked) { $priorHosts += [string]$ch.Tag }
        }
    }
    if (-not $hadAny) { $priorAll = $true }   # first build -> default to All

    $panel.Children.Clear()
    $cbAll = New-Object System.Windows.Controls.CheckBox
    $cbAll.Content = 'All servers'; $cbAll.Tag = '__ALL__'; $cbAll.Margin = '0,2,0,4'; $cbAll.FontWeight = 'SemiBold'
    $cbAll.IsChecked = $priorAll
    [void]$panel.Children.Add($cbAll)

    foreach ($s in (Get-OneLinkEligibleTargets -Key $Key)) {
        $cb = New-Object System.Windows.Controls.CheckBox
        $cb.Content = [string]$s.Host; $cb.Tag = [string]$s.Host; $cb.Margin = '0,2,0,2'
        $cb.IsChecked = ($priorHosts -contains [string]$s.Host)
        [void]$panel.Children.Add($cb)
    }

    $onChange = {
        param($sender, $e)
        if ([string]$sender.Tag -eq '__ALL__') {
            if ($sender.IsChecked) {
                foreach ($c in $panel.Children) { if ($c -is [System.Windows.Controls.CheckBox] -and [string]$c.Tag -ne '__ALL__') { $c.IsChecked = $false } }
            }
        }
        else {
            if ($sender.IsChecked) { $cbAll.IsChecked = $false }
        }
        Update-OneLinkTargetButton -Key $Key
        if ($Key -eq 'Service') { Update-ServiceChecklist }
        elseif ($Key -eq 'Db') { Update-OneLinkDbAllowedIp }
    }.GetNewClosure()
    foreach ($ch in $panel.Children) { if ($ch -is [System.Windows.Controls.CheckBox]) { $ch.Add_Click($onChange) } }

    Update-OneLinkTargetButton -Key $Key
}

# Rebuild the Service + Certificate target pickers (kept the old names so all the
# existing callers - connect / disconnect / add / remove / import - still work).
function Update-TargetCombos {
    Update-OneLinkTargetPicker -Key 'Service'
    Update-OneLinkTargetPicker -Key 'Cert'
}

# Rebuild the Database target picker (only 'Database master' / 'Database slave').
function Update-DbTargetCombo {
    Update-OneLinkTargetPicker -Key 'Db'
}

# Refresh the connection summary label and the Disconnect button state.
function Update-ConnectionSummary {
    $total = $script:Servers.Count
    $connected = @($script:Servers | Where-Object { $null -ne $_.Session }).Count

    if ($connected -gt 0) {
        $TxtConnectionStatus.Text = "$connected of $total server(s) connected"
        $TxtConnectionStatus.Foreground = [System.Windows.Media.Brushes]::ForestGreen
    }
    else {
        $TxtConnectionStatus.Text = if ($total -eq 0) { "No servers added" } else { "No servers connected" }
        $TxtConnectionStatus.Foreground = [System.Windows.Media.Brushes]::Crimson
    }

    $BtnDisconnect.IsEnabled = ($connected -gt 0)
}

# The systemd services a server runs, derived from its role marks.
function Get-OneLinkServerServices {
    param($Server)
    $list = @()
    foreach ($role in $Server.RoleList()) {
        if ($script:RoleServiceMap.Contains($role)) { $list += [string]$script:RoleServiceMap[$role] }
    }
    return @($list | Select-Object -Unique)
}

# Auto-discover NON-OneLink systemd service units on a server (for the 'Auxiliary
# Service' role). Lists installed unit-files whose state is enabled or disabled
# (i.e. real, manageable app services), excluding the onelink-* units that the
# existing OneLink logic already handles. Returns unit names without '.service'.
function Get-OneLinkAuxServices {
    param($Session)
    $cmd = "PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:`$PATH; " +
           "systemctl list-unit-files --type=service --no-legend 2>/dev/null | " +
           "awk '`$2==`"enabled`" || `$2==`"disabled`" {print `$1}' | " +
           "sed 's/\.service`$//' | grep -vi '^onelink' | sort -u"
    $r = Invoke-OneLinkSshCommand -Session $Session -Command $cmd -TimeoutSeconds 30
    $names = @()
    if (-not [string]::IsNullOrWhiteSpace($r.Output)) {
        $names = $r.Output -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' }
    }
    return @($names)
}

# Populate $Server.AuxServices if the server is marked 'Auxiliary Service' and they
# have not been discovered yet (or Force). No-op otherwise. Never throws.
function Update-OneLinkAuxServices {
    param($Server, [switch]$Force)
    if ($null -eq $Server -or $null -eq $Server.Session) { return }
    if (-not $Server.HasRole('Auxiliary Service')) { return }
    if (($null -ne $Server.AuxServices) -and (-not $Force)) { return }
    try { $Server.AuxServices = @(Get-OneLinkAuxServices -Session $Server.Session) }
    catch { $Server.AuxServices = @(); Write-OneLinkLog "[$($Server.Host)] Auxiliary service discovery failed: $($_.Exception.Message)" -Level Warning }
}

# The FULL set of services the Service Installer manages for a server: the OneLink
# role services (unchanged) PLUS any discovered auxiliary (non-OneLink) units when
# the server carries the 'Auxiliary Service' role. OneLink behaviour is untouched.
function Get-OneLinkServerManagedServices {
    param($Server)
    $list = @(Get-OneLinkServerServices $Server)
    if ($Server.HasRole('Auxiliary Service') -and $Server.AuxServices) {
        foreach ($s in @($Server.AuxServices)) { if ($list -notcontains $s) { $list += [string]$s } }
    }
    return @($list | Select-Object -Unique)
}

# True if $Unit is an auxiliary (non-OneLink) unit on $Server, so start/restart/stop
# must use plain systemctl instead of the nmenu (nstart/nstop) OneLink path.
function Test-OneLinkAuxService {
    param($Server, [string]$Unit)
    if ($null -eq $Server -or $null -eq $Server.AuxServices) { return $false }
    return (@($Server.AuxServices) -contains $Unit)
}

# Plain systemctl restart/stop for an auxiliary (non-OneLink) service. Success is
# judged by 'is-active' AFTER the action (like the OneLink helpers judge by state,
# not the exit code): Restart -> should be active; Stop -> should be inactive.
function Invoke-OneLinkPlainServiceAction {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]$Session,
        [Parameter(Mandatory)][string]$Unit,
        [Parameter(Mandatory)][ValidateSet('Restart','Stop')][string]$Action
    )
    $u = ConvertTo-OneLinkBashArg ($Unit + '.service')
    $verb = if ($Action -eq 'Stop') { 'stop' } else { 'restart' }
    $cmd = "sudo systemctl $verb $u >/dev/null 2>&1; echo OLK_STATE=`$(systemctl is-active $u 2>/dev/null)"
    $r = Invoke-OneLinkSshCommand -Session $Session -Command $cmd -TimeoutSeconds ([int]$script:Settings.Ssh.CommandTimeoutSeconds)
    $t = (@($r.Output, $r.Error) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join ' '
    $state = if ($t -match 'OLK_STATE=(\S+)') { $Matches[1] } else { 'unknown' }
    if ($Action -eq 'Stop') {
        if ($state -eq 'inactive' -or $state -eq 'failed' -or $state -eq 'unknown') { return "stopped (state: $state)" }
        throw "still '$state' after stop."
    }
    if ($state -eq 'active') { return "restarted (active)" }
    throw "not active after restart (state: $state)."
}

# Rebuild the Services checklist for the currently-selected target: the UNION of
# services derived from the role marks of the target server(s). Each service is
# a checkbox (checked by default) so several can be actioned at once.
function Update-ServiceChecklist {
    # remember which were checked so a refresh keeps the user's ticks
    $previouslyChecked = @{}
    foreach ($child in $SvcCheckPanel.Children) {
        if ($child -is [System.Windows.Controls.CheckBox]) {
            $previouslyChecked[[string]$child.Tag] = [bool]$child.IsChecked
        }
    }

    $SvcCheckPanel.Children.Clear()

    $targets = @(Get-OneLinkTargetHosts -Key 'Service')
    $services = New-Object System.Collections.Generic.List[string]
    foreach ($server in $targets) {
        Update-OneLinkAuxServices -Server $server   # discover non-OneLink units if marked Auxiliary and not yet done
        foreach ($svc in (Get-OneLinkServerManagedServices $server)) {
            if (-not $services.Contains($svc)) { $services.Add($svc) }
        }
    }

    if ($services.Count -eq 0) {
        $tb = New-Object System.Windows.Controls.TextBlock
        $tb.Text = 'No services - connect a server and mark it (AppServer / Concentrator / ReportServer / nConnect / Auxiliary Service).'
        $tb.TextWrapping = 'Wrap'
        $tb.Foreground = [System.Windows.Media.Brushes]::Gray
        [void]$SvcCheckPanel.Children.Add($tb)
        return
    }

    foreach ($svc in ($services | Sort-Object)) {
        $cb = New-Object System.Windows.Controls.CheckBox
        $cb.Content = $svc
        $cb.Tag = $svc
        $cb.Margin = '0,2,0,2'
        $cb.IsChecked = if ($previouslyChecked.ContainsKey($svc)) { $previouslyChecked[$svc] } else { $true }
        [void]$SvcCheckPanel.Children.Add($cb)
    }

    # Re-apply the current search filter so it survives a rebuild/refresh.
    Update-OneLinkServiceFilter
}

# Show only the service checkboxes whose name contains the search text (case-
# insensitive). Blank search shows all. Only affects visibility, not tick state.
function Update-OneLinkServiceFilter {
    if ($null -eq $TxtServiceSearch) { return }
    $q = ([string]$TxtServiceSearch.Text).Trim().ToLowerInvariant()
    foreach ($child in $SvcCheckPanel.Children) {
        if ($child -is [System.Windows.Controls.CheckBox]) {
            $name = ([string]$child.Content).ToLowerInvariant()
            $child.Visibility = if ($q -eq '' -or $name.Contains($q)) { 'Visible' } else { 'Collapsed' }
        }
    }
}

# Tick / untick every service currently VISIBLE (i.e. matching the search filter).
function Set-OneLinkServicesChecked {
    param([bool]$Checked)
    foreach ($child in $SvcCheckPanel.Children) {
        if ($child -is [System.Windows.Controls.CheckBox] -and $child.Visibility -eq 'Visible') {
            $child.IsChecked = $Checked
        }
    }
}

# The services the user has ticked in the checklist.
function Get-OneLinkCheckedServices {
    # Only services that are CHECKED and currently VISIBLE. The search filter hides
    # non-matching checkboxes (Visibility=Collapsed) without unticking them, so
    # without this a filtered-out but still-ticked service would be acted on too -
    # e.g. filtering to 'one', ticking onelink-appserver, but the default-ticked
    # hidden services still getting included. Visible-only matches what the user sees.
    $checked = @()
    foreach ($child in $SvcCheckPanel.Children) {
        if ($child -is [System.Windows.Controls.CheckBox] -and $child.IsChecked -and $child.Visibility -eq [System.Windows.Visibility]::Visible) {
            $checked += [string]$child.Tag
        }
    }
    return @($checked)
}

# Resolve the list of target servers for an operation, based on a combo value.
# Only currently-connected servers are returned.
function Get-TargetServers {
    param([string]$Selection)

    if ([string]::IsNullOrWhiteSpace($Selection) -or $Selection -eq 'All servers') {
        return @($script:Servers | Where-Object { $null -ne $_.Session })
    }

    return @($script:Servers | Where-Object { $_.Host -eq $Selection -and $null -ne $_.Session })
}

# Run a per-server action against the selected target(s). Continues on failure
# and shows a per-server summary at the end.
function Invoke-MultiServerOperation {
    param(
        [Parameter(Mandatory)][string]$Name,
        [AllowEmptyString()][string]$TargetSelection = '',
        [object[]]$TargetServers = $null,
        [Parameter(Mandatory)][scriptblock]$PerServerAction,
        [scriptblock]$AppliesTo
    )

    # Targets can be supplied directly (multi-select picker) or resolved from a
    # legacy selection string.
    if ($null -ne $TargetServers) {
        $targets = @($TargetServers)
        if ($targets.Count -eq 0) {
            Show-ErrorMessage "$Name`: no target server is selected. Pick one or more servers in 'Target server' (and Connect them). For Database actions, mark a server as 'Database master' or 'Database slave' first."
            return
        }
    }
    else {
        if ([string]::IsNullOrWhiteSpace($TargetSelection)) {
            Show-ErrorMessage "$Name`: no target server is selected. For Database actions, mark a server as 'Database master' or 'Database slave' and click Connect All."
            return
        }
        $targets = @(Get-TargetServers -Selection $TargetSelection)
        if ($targets.Count -eq 0) {
            Show-ErrorMessage "$Name`: no connected server matches the selected target '$TargetSelection'. Connect a server first."
            return
        }
    }

    $targetDesc = ($targets | ForEach-Object { [string]$_.Host }) -join ', '
    Write-OneLinkLog "Starting '$Name' on $($targets.Count) server(s): $targetDesc." -Level Info
    $script:Window.Cursor = [Windows.Input.Cursors]::Wait
    $mopStart = Get-Date

    $succeeded = New-Object System.Collections.Generic.List[string]
    $failed = New-Object System.Collections.Generic.List[string]
    $skipped = New-Object System.Collections.Generic.List[string]

    foreach ($server in $targets) {
        if ($AppliesTo -and -not (& $AppliesTo $server)) {
            $skipped.Add([string]$server.Host)
            Write-OneLinkLog "[$($server.Host)] $Name : skipped (this server does not have that service)." -Level Info
            continue
        }
        $opStart = Get-Date
        try {
            Write-OneLinkLog "[$($server.Host)] $Name : starting." -Level Info
            & $PerServerAction $server
            $opEnd = Get-Date
            Write-OneLinkLog "[$($server.Host)] $Name : completed in $([math]::Round(($opEnd-$opStart).TotalSeconds,2))s." -Level Success
            Write-OneLinkEfficiency -Operation $Name -Target ([string]$server.Host) -Outcome 'Success' -Start $opStart -End $opEnd
            $succeeded.Add([string]$server.Host)
        }
        catch {
            $opEnd = Get-Date
            Write-OneLinkLog "[$($server.Host)] $Name : FAILED after $([math]::Round(($opEnd-$opStart).TotalSeconds,2))s. $($_.Exception.Message)" -Level Error
            Write-OneLinkEfficiency -Operation $Name -Target ([string]$server.Host) -Outcome 'Failed' -Start $opStart -End $opEnd
            $failed.Add("$($server.Host): $($_.Exception.Message)")
        }
    }

    $script:Window.Cursor = [Windows.Input.Cursors]::Arrow

    # Record one activity metric for this whole operation (clicks/fields/time).
    $actOutcome = if ($failed.Count -gt 0) { if ($succeeded.Count -gt 0) { 'Partial' } else { 'Failed' } } elseif ($succeeded.Count -eq 0) { 'Skipped' } else { 'Success' }
    Complete-OneLinkActivity -Name $Name -Target $targetDesc -Outcome $actOutcome -OperationSeconds (((Get-Date) - $mopStart).TotalSeconds)

    if ($succeeded.Count -eq 0 -and $failed.Count -eq 0 -and $skipped.Count -gt 0) {
        Show-WarningMessage ("$Name" + [Environment]::NewLine +
            "Skipped on every target - none of them have that service:" + [Environment]::NewLine +
            "  " + ($skipped -join ', '))
        return
    }

    $summary = "$Name" + [Environment]::NewLine +
        "Succeeded ($($succeeded.Count)): " + ($(if ($succeeded.Count) { $succeeded -join ', ' } else { 'none' }))
    if ($skipped.Count -gt 0) {
        $summary += [Environment]::NewLine + "Skipped ($($skipped.Count)): " + ($skipped -join ', ')
    }
    if ($failed.Count -gt 0) {
        $summary += [Environment]::NewLine + "Failed ($($failed.Count)):" + [Environment]::NewLine +
            "  " + ($failed -join ([Environment]::NewLine + "  "))
        Show-WarningMessage $summary
    }
    else {
        Show-InfoMessage $summary
    }
}

# ----------------------------------------------------------------------------
#  Server-list management (editable grid)
# ----------------------------------------------------------------------------

# Add a blank editable row.
$BtnAddServer.Add_Click({
    $script:Servers.Add([OlServer]::new())
    Invoke-GridRefresh $ServerGrid
    Update-ConnectionSummary
    Complete-OneLinkActivity -Name 'Add Server Row'
})

$BtnSameCreds.Add_Click({ Set-OlServerCredentialsForAll })

$BtnRemoveServer.Add_Click({
    $all = @($script:Servers)
    if ($all.Count -eq 0) { Show-InfoMessage "There are no server rows to clear."; return }
    $confirm = [System.Windows.MessageBox]::Show(
        "Remove ALL $($all.Count) server row(s) from the list?`n`nAny open connections will be disconnected.",
        "$($script:AppName) - clear all", 'OKCancel', 'Question')
    if ($confirm -ne [System.Windows.MessageBoxResult]::OK) { return }
    foreach ($server in $all) {
        if ($null -ne $server.Session) {
            try { Disconnect-OneLinkSsh -Session $server.Session } catch { }
        }
    }
    $removedHosts = ($all | ForEach-Object { $_.Host }) -join ', '
    $script:Servers.Clear()
    Invoke-GridRefresh $ServerGrid
    Update-TargetCombos
    Update-DbTargetCombo
    Update-ConnectionSummary
    Update-ServiceChecklist
    Complete-OneLinkActivity -Name 'Clear All Servers' -Target $removedHosts
    Write-OneLinkLog "Cleared all server rows." -Level Info
})

# Small modal to capture a masked password for one row.
function Set-OlServerPassword {
    param([Parameter(Mandatory)][OlServer]$Server)

    $dlg = New-Object System.Windows.Window
    $dlg.Title = 'Set password'
    $dlg.Width = 380; $dlg.SizeToContent = 'Height'
    $dlg.WindowStartupLocation = 'CenterOwner'; $dlg.Owner = $script:Window; $dlg.ResizeMode = 'NoResize'

    $panel = New-Object System.Windows.Controls.StackPanel
    $panel.Margin = '14'
    $lbl = New-Object System.Windows.Controls.TextBlock
    $lbl.Text = "SSH password for $($Server.Host):"
    $lbl.Margin = '0,0,0,6'
    [void]$panel.Children.Add($lbl)

    # Masked box and a plain box occupy the same spot; the "Show password"
    # toggle swaps which one is visible so the user can verify what they typed.
    $inputGrid = New-Object System.Windows.Controls.Grid
    $pb = New-Object System.Windows.Controls.PasswordBox
    $pb.Height = 28
    $tb = New-Object System.Windows.Controls.TextBox
    $tb.Height = 28
    $tb.Visibility = [System.Windows.Visibility]::Collapsed
    $tb.VerticalContentAlignment = 'Center'

    # Pre-fill both with the current password so it can be reviewed on reopen.
    $existing = ConvertFrom-OneLinkSecure $Server.SecurePassword
    if (-not [string]::IsNullOrEmpty($existing)) { $pb.Password = $existing; $tb.Text = $existing }

    [void]$inputGrid.Children.Add($pb)
    [void]$inputGrid.Children.Add($tb)
    [void]$panel.Children.Add($inputGrid)

    $show = New-Object System.Windows.Controls.CheckBox
    $show.Content = 'Show password'
    $show.Margin = '0,8,0,0'
    $show.Add_Checked({
        $tb.Text = $pb.Password
        $tb.Visibility = [System.Windows.Visibility]::Visible
        $pb.Visibility = [System.Windows.Visibility]::Collapsed
        $tb.Focus() | Out-Null
    })
    $show.Add_Unchecked({
        $pb.Password = $tb.Text
        $pb.Visibility = [System.Windows.Visibility]::Visible
        $tb.Visibility = [System.Windows.Visibility]::Collapsed
        $pb.Focus() | Out-Null
    })
    [void]$panel.Children.Add($show)

    $btns = New-Object System.Windows.Controls.StackPanel
    $btns.Orientation = 'Horizontal'; $btns.HorizontalAlignment = 'Right'; $btns.Margin = '0,12,0,0'
    $ok = New-Object System.Windows.Controls.Button
    $ok.Content = 'OK'; $ok.Width = 80; $ok.Margin = '0,0,8,0'; $ok.IsDefault = $true
    $cancel = New-Object System.Windows.Controls.Button
    $cancel.Content = 'Cancel'; $cancel.Width = 80; $cancel.IsCancel = $true
    $ok.Add_Click({ $dlg.DialogResult = $true })
    [void]$btns.Children.Add($ok); [void]$btns.Children.Add($cancel)
    [void]$panel.Children.Add($btns)
    $dlg.Content = $panel
    $recorder = Enable-OneLinkWindowRecorder $dlg
    $pb.Focus() | Out-Null

    if ($dlg.ShowDialog()) {
        # Read from whichever box is currently visible.
        $plain = if ($show.IsChecked) { $tb.Text } else { $pb.Password }
        if (-not [string]::IsNullOrEmpty($plain)) {
            $sec = New-Object System.Security.SecureString
            foreach ($ch in $plain.ToCharArray()) { $sec.AppendChar($ch) }
            $sec.MakeReadOnly()
            $Server.SecurePassword = $sec
            $Server.PasswordDisplay = ([string][char]0x25CF) * 6
        }
        else {
            $Server.SecurePassword = $null
            $Server.PasswordDisplay = 'Set...'
        }
        Invoke-GridRefresh $ServerGrid
        Complete-OneLinkActivity -Name 'Set Server Password' -Target ([string]$Server.Host) -Context $recorder
    }
}

# Set ONE username and/or password and apply it to every server row (or just the
# selected rows) - saves setting the same credentials on many identical servers.
function Set-OlServerCredentialsForAll {
    if ($script:Servers.Count -eq 0) { Show-ErrorMessage "Add at least one server row first."; return }

    $dlg = New-Object System.Windows.Window
    $dlg.Title = 'Same login for all servers'
    $dlg.Width = 430; $dlg.SizeToContent = 'Height'
    $dlg.WindowStartupLocation = 'CenterOwner'; $dlg.Owner = $script:Window; $dlg.ResizeMode = 'NoResize'

    $panel = New-Object System.Windows.Controls.StackPanel
    $panel.Margin = '16'
    $intro = New-Object System.Windows.Controls.TextBlock
    $intro.Text = "Enter a username and/or password to apply to the server rows below. Leave a field blank to keep the existing value."
    $intro.TextWrapping = 'Wrap'; $intro.Margin = '0,0,0,12'
    [void]$panel.Children.Add($intro)

    $userLbl = New-Object System.Windows.Controls.TextBlock
    $userLbl.Text = 'Username'; $userLbl.Margin = '0,0,0,3'
    [void]$panel.Children.Add($userLbl)
    $userBox = New-Object System.Windows.Controls.TextBox
    $userBox.Height = 28; $userBox.VerticalContentAlignment = 'Center'; $userBox.Margin = '0,0,0,10'
    [void]$panel.Children.Add($userBox)

    $pwLbl = New-Object System.Windows.Controls.TextBlock
    $pwLbl.Text = 'Password'; $pwLbl.Margin = '0,0,0,3'
    [void]$panel.Children.Add($pwLbl)
    $inputGrid = New-Object System.Windows.Controls.Grid
    $pb = New-Object System.Windows.Controls.PasswordBox; $pb.Height = 28
    $tb = New-Object System.Windows.Controls.TextBox; $tb.Height = 28; $tb.VerticalContentAlignment = 'Center'
    $tb.Visibility = [System.Windows.Visibility]::Collapsed
    [void]$inputGrid.Children.Add($pb); [void]$inputGrid.Children.Add($tb)
    [void]$panel.Children.Add($inputGrid)

    $show = New-Object System.Windows.Controls.CheckBox
    $show.Content = 'Show password'; $show.Margin = '0,8,0,0'
    $show.Add_Checked({ $tb.Text = $pb.Password; $tb.Visibility = 'Visible'; $pb.Visibility = 'Collapsed'; $tb.Focus() | Out-Null })
    $show.Add_Unchecked({ $pb.Password = $tb.Text; $pb.Visibility = 'Visible'; $tb.Visibility = 'Collapsed'; $pb.Focus() | Out-Null })
    [void]$panel.Children.Add($show)

    $selOnly = New-Object System.Windows.Controls.CheckBox
    $selCount = @($ServerGrid.SelectedItems).Count
    $selOnly.Content = "Apply to selected rows only ($selCount selected) - otherwise ALL $($script:Servers.Count) row(s)"
    $selOnly.Margin = '0,10,0,0'
    $selOnly.IsEnabled = ($selCount -gt 0)
    [void]$panel.Children.Add($selOnly)

    $btns = New-Object System.Windows.Controls.StackPanel
    $btns.Orientation = 'Horizontal'; $btns.HorizontalAlignment = 'Right'; $btns.Margin = '0,14,0,0'
    $ok = New-Object System.Windows.Controls.Button
    $ok.Content = 'Apply'; $ok.Width = 90; $ok.Margin = '0,0,8,0'; $ok.IsDefault = $true
    $cancel = New-Object System.Windows.Controls.Button
    $cancel.Content = 'Cancel'; $cancel.Width = 80; $cancel.IsCancel = $true
    $ok.Add_Click({ $dlg.DialogResult = $true })
    [void]$btns.Children.Add($ok); [void]$btns.Children.Add($cancel)
    [void]$panel.Children.Add($btns)
    $dlg.Content = $panel
    $recorder = Enable-OneLinkWindowRecorder $dlg
    $userBox.Focus() | Out-Null

    if (-not $dlg.ShowDialog()) { return }

    $user = ([string]$userBox.Text).Trim()
    $plain = if ($show.IsChecked) { $tb.Text } else { $pb.Password }
    if ($user -eq '' -and [string]::IsNullOrEmpty($plain)) { Show-WarningMessage "Nothing entered - no changes made."; return }

    $targets = if ($selOnly.IsChecked -and $selCount -gt 0) { @($ServerGrid.SelectedItems) } else { @($script:Servers) }
    foreach ($s in $targets) {
        if ($user -ne '') { $s.Username = $user }
        if (-not [string]::IsNullOrEmpty($plain)) {
            $sec = New-Object System.Security.SecureString
            foreach ($ch in $plain.ToCharArray()) { $sec.AppendChar($ch) }
            $sec.MakeReadOnly()
            $s.SecurePassword = $sec
            $s.PasswordDisplay = ([string][char]0x25CF) * 6
        }
    }
    Invoke-GridRefresh $ServerGrid
    $what = @(); if ($user -ne '') { $what += 'username' }; if (-not [string]::IsNullOrEmpty($plain)) { $what += 'password' }
    Write-OneLinkLog "Applied shared $($what -join ' + ') to $($targets.Count) server row(s)." -Level Success
    Complete-OneLinkActivity -Name 'Set Shared Server Credentials' -Target (($targets | ForEach-Object { $_.Host }) -join ', ') -Context $recorder
    Show-InfoMessage "Applied the $($what -join ' and ') to $($targets.Count) server row(s)."
}

# Small modal with a checkbox per role in $script:OlRoles.
function Set-OlServerRoles {
    param([Parameter(Mandatory)][OlServer]$Server)

    $dlg = New-Object System.Windows.Window
    $dlg.Title = "Roles for $($Server.Host)"
    $dlg.Width = 320; $dlg.SizeToContent = 'Height'
    $dlg.WindowStartupLocation = 'CenterOwner'; $dlg.Owner = $script:Window; $dlg.ResizeMode = 'NoResize'

    $panel = New-Object System.Windows.Controls.StackPanel
    $panel.Margin = '14'
    $hdr = New-Object System.Windows.Controls.TextBlock
    $hdr.Text = 'Mark this IP for one or more purposes:'
    $hdr.Margin = '0,0,0,8'
    [void]$panel.Children.Add($hdr)

    $current = $Server.RoleList()
    $checks = @{}
    foreach ($role in $script:OlRoles) {
        $cb = New-Object System.Windows.Controls.CheckBox
        $cb.Content = $role; $cb.Margin = '0,3,0,3'
        $cb.IsChecked = ($current -contains $role)
        $checks[$role] = $cb
        [void]$panel.Children.Add($cb)
    }

    $btns = New-Object System.Windows.Controls.StackPanel
    $btns.Orientation = 'Horizontal'; $btns.HorizontalAlignment = 'Right'; $btns.Margin = '0,12,0,0'
    $ok = New-Object System.Windows.Controls.Button
    $ok.Content = 'OK'; $ok.Width = 80; $ok.Margin = '0,0,8,0'; $ok.IsDefault = $true
    $cancel = New-Object System.Windows.Controls.Button
    $cancel.Content = 'Cancel'; $cancel.Width = 80; $cancel.IsCancel = $true
    $ok.Add_Click({ $dlg.DialogResult = $true })
    [void]$btns.Children.Add($ok); [void]$btns.Children.Add($cancel)
    [void]$panel.Children.Add($btns)
    $dlg.Content = $panel
    $recorder = Enable-OneLinkWindowRecorder $dlg

    if ($dlg.ShowDialog()) {
        $selected = @()
        foreach ($role in $script:OlRoles) { if ($checks[$role].IsChecked) { $selected += $role } }
        $Server.Roles = ($selected -join ', ')
        $Server.RolesDisplay = if ($selected.Count) { $Server.Roles } else { 'Select...' }
        Invoke-GridRefresh $ServerGrid
        Update-DbTargetCombo
        Complete-OneLinkActivity -Name 'Set Server Roles' -Target ([string]$Server.Host) -Context $recorder
    }
}

# Re-discover the OneLink services installed on a connected server (the small
# refresh button in the 'OneLink Services' grid column).
function Update-OneLinkServerServices {
    param($Server)
    if ($null -eq $Server) { return }
    if ($null -eq $Server.Session) { Show-ErrorMessage "Connect this server first, then refresh its services."; return }
    $metricStart = Get-Date
    $metricOutcome = 'Failed'
    $script:Window.Cursor = [Windows.Input.Cursors]::Wait
    try {
        $Server.Services = Get-OneLinkDiscoveredServices -Session $Server.Session -Settings $script:Settings -Mappings $script:Mappings
        Update-OneLinkAuxServices -Server $Server -Force   # refresh non-OneLink units too, if marked Auxiliary
        try { Update-OneLinkServerHealth -Server $Server } catch { }   # refresh health indicator too
        $names = @($Server.Services | ForEach-Object { $_.DisplayName })
        $Server.ServicesDisplay = if ($names.Count) { "$($names.Count): " + ($names -join ', ') } else { '0 (none)' }
        Write-OneLinkLog "[$($Server.Host)] Re-checked services: $(if ($names.Count) { $names -join ', ' } else { 'none installed' })." -Level Info
        Invoke-GridRefresh $ServerGrid
        Update-ServiceChecklist
        $metricOutcome = 'Success'
    }
    catch {
        $Server.ServicesDisplay = '?'
        Invoke-GridRefresh $ServerGrid
        Write-OneLinkLog "[$($Server.Host)] Service re-check failed: $($_.Exception.Message)" -Level Warning
    }
    finally {
        $script:Window.Cursor = [Windows.Input.Cursors]::Arrow
        Complete-OneLinkActivity -Name 'Refresh Server Services' -Target ([string]$Server.Host) -Outcome $metricOutcome -OperationSeconds (((Get-Date) - $metricStart).TotalSeconds)
    }
}

# Reset a server's health indicator (on disconnect).
function Reset-OneLinkServerHealth {
    param($Server)
    if ($null -eq $Server) { return }
    $Server.Health = 'View'; $Server.HealthNote = ''
}

# Check disk + memory usage on a connected server and set its health indicator:
#   CRITICAL if any partition >=95% used OR memory >=95% used
#   CAUTION  if any partition >=85% used OR memory >=85% used
#   OK       otherwise
# Colours the Resources button and appends the state to the Status column. Never throws.
function Update-OneLinkServerHealth {
    param($Server)
    if ($null -eq $Server -or $null -eq $Server.Session) { return }
    try {
        $cmd = @'
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH
echo OLK_DF
df -Pk -x tmpfs -x devtmpfs 2>/dev/null | tail -n +2
echo OLK_MEM
free -k 2>/dev/null | awk '/^Mem:/{print $2, $4, $7}'
'@
        $r = Invoke-OneLinkSshCommand -Session $Server.Session -Command $cmd -TimeoutSeconds 20
        $lines = ([string]$r.Output) -split "`r?`n"
        $section = ''
        $worstDiskPct = -1; $worstMount = ''
        $memPct = -1
        foreach ($ln in $lines) {
            $t = $ln.Trim()
            if ($t -eq 'OLK_DF') { $section = 'df'; continue }
            if ($t -eq 'OLK_MEM') { $section = 'mem'; continue }
            if ($t -eq '') { continue }
            if ($section -eq 'df') {
                $f = $t -split '\s+'
                if ($f.Count -ge 6 -and $f[4] -match '^(\d+)%$') {
                    $pct = [int]$Matches[1]
                    if ($pct -gt $worstDiskPct) { $worstDiskPct = $pct; $worstMount = $f[5] }
                }
            }
            elseif ($section -eq 'mem') {
                $m = $t -split '\s+'
                if ($m.Count -ge 1 -and $m[0] -match '^\d+$') {
                    $total = [double]$m[0]
                    $avail = if ($m.Count -ge 3 -and $m[2] -match '^\d+$') { [double]$m[2] } elseif ($m.Count -ge 2 -and $m[1] -match '^\d+$') { [double]$m[1] } else { 0 }
                    if ($total -gt 0) { $memPct = [int][math]::Round((($total - $avail) / $total) * 100) }
                }
            }
        }

        $state = 'OK'
        if (($worstDiskPct -ge 95) -or ($memPct -ge 95)) { $state = 'CRITICAL' }
        elseif (($worstDiskPct -ge 85) -or ($memPct -ge 85)) { $state = 'CAUTION' }
        if ($worstDiskPct -lt 0 -and $memPct -lt 0) { $state = 'View' }   # nothing parsed

        $parts = @()
        if ($worstDiskPct -ge 0) { $parts += "Disk $worstMount $worstDiskPct%" }
        if ($memPct -ge 0) { $parts += "Mem $memPct%" }
        $Server.HealthNote = ($parts -join ' - ')
        $Server.Health = $state

        # Reflect the state in the Status column (strip any prior health suffix first).
        # NOTE: the pattern MUST be parenthesised - without it, PowerShell operator
        # precedence makes -replace ignore the bullet part and the strip does nothing,
        # so every refresh appends another "Health: OK" (the OK * OK * OK bug).
        $bullet = [char]0x2022
        $base = ([string]$Server.Status -replace ("\s*" + $bullet + ".*$"), '').TrimEnd()
        if ($state -ne 'View') { $Server.Status = "$base  $bullet  Health: $state" } else { $Server.Status = $base }
        Write-OneLinkLog "[$($Server.Host)] Health: $state ($($Server.HealthNote))." -Level Info
    }
    catch {
        Write-OneLinkLog "[$($Server.Host)] Health check failed: $($_.Exception.Message)" -Level Warning
    }
}

# Show a server's resource details (disk partitions, memory, CPU) in a clean,
# professional popup. Read-only; runs only against a connected server. Kept fast
# (df / free / nproc) - no slow directory traversals. Artifact/package sizes are
# shown on the Package tab instead.
function Show-OneLinkServerResources {
    param($Server)
    if ($null -eq $Server) { return }
    if ($null -eq $Server.Session) { Show-ErrorMessage "Connect this server first, then view its resources."; return }
    $metricStart = Get-Date
    $metricOutcome = 'Failed'; $metricSeconds = $null
    $script:Window.Cursor = [Windows.Input.Cursors]::Wait
    try {
        try { Update-OneLinkServerHealth -Server $Server; Invoke-GridRefresh $ServerGrid } catch { }   # refresh the health colour when opened
        $cmd = @'
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH
echo "===== Disk partitions ====="
df -hP -x tmpfs -x devtmpfs 2>/dev/null || df -hP 2>/dev/null
echo
echo "===== Memory ====="
free -h 2>/dev/null || free -m 2>/dev/null
echo
echo "===== CPU / uptime ====="
echo "  CPU cores : $(nproc 2>/dev/null)"
echo "  Uptime    :$(uptime 2>/dev/null | sed 's/^ *//')"
'@
        $r = Invoke-OneLinkSshCommand -Session $Server.Session -Command $cmd -TimeoutSeconds 60
        $body = ([string]$r.Output).Trim()
        if ([string]::IsNullOrWhiteSpace($body)) { $body = "(no output - the server did not return resource details)" }
        Write-OneLinkLog "[$($Server.Host)] Viewed server resources." -Level Info
        $metricOutcome = if ($r.ExitStatus -eq 0) { 'Success' } else { 'Failed' }
        $metricSeconds = ((Get-Date) - $metricStart).TotalSeconds
        Show-OneLinkReport -Title "Resources - $($Server.Host)" -Body $body
    }
    catch { Show-ErrorMessage "Could not read resources from $($Server.Host). $($_.Exception.Message)" }
    finally {
        $script:Window.Cursor = [Windows.Input.Cursors]::Arrow
        if ($null -eq $metricSeconds) { $metricSeconds = ((Get-Date) - $metricStart).TotalSeconds }
        Complete-OneLinkActivity -Name 'View Server Resources' -Target ([string]$Server.Host) -Outcome $metricOutcome -OperationSeconds $metricSeconds
    }
}

# Route the in-grid Password / Roles / Refresh / Resources button clicks to their actions.
$ServerGrid.AddHandler(
    [System.Windows.Controls.Primitives.ButtonBase]::ClickEvent,
    [System.Windows.RoutedEventHandler]{
        param($eventSender, $e)
        $btn = $e.OriginalSource -as [System.Windows.Controls.Button]
        if ($null -eq $btn) { $btn = $e.Source -as [System.Windows.Controls.Button] }
        if ($null -eq $btn) { return }
        $row = $btn.DataContext -as [OlServer]
        if ($null -eq $row) { return }
        switch ([string]$btn.Tag) {
            'Password'        { Set-OlServerPassword -Server $row }
            'Roles'           { Set-OlServerRoles -Server $row }
            'RefreshServices' { Update-OneLinkServerServices -Server $row }
            'Resources'       { Show-OneLinkServerResources -Server $row }
            'Console'         { Show-OneLinkSshConsole -Server $row }
            'EditFile'        { Show-OneLinkFileEditor -Server $row }
        }
    }
)

# Right-click a server row -> per-server quick actions that target THAT server
# directly (no picker). A right-click first selects the row under the cursor.
$srvRowMenu = New-Object System.Windows.Controls.ContextMenu
$srvRowMenu.Add_PreviewMouseDown({ $script:ActClicks++; Register-OneLinkInteraction })
$srvRowMenu.Add_PreviewKeyDown({ Register-OneLinkInteraction })

# A greyed, non-clickable header line showing which server the menu acts on.
$miRowHeader = New-Object System.Windows.Controls.MenuItem
$miRowHeader.IsEnabled = $false
$miRowHeader.FontWeight = 'Bold'

$miRowConsole = New-Object System.Windows.Controls.MenuItem
$miRowConsole.Header = 'Command Console'
$miRowConsole.Add_Click({
    $row = $ServerGrid.SelectedItem -as [OlServer]
    if ($null -ne $row) { Show-OneLinkSshConsole -Server $row }
})

$miRowConnect = New-Object System.Windows.Controls.MenuItem
$miRowConnect.Header = 'Connect'
$miRowConnect.Add_Click({
    $row = $ServerGrid.SelectedItem -as [OlServer]
    if ($null -eq $row) { return }
    Complete-ServerGridEdits
    if ([string]::IsNullOrWhiteSpace($row.Host)) { Show-ErrorMessage 'This row has no IP / host.'; return }
    $script:Window.Cursor = [Windows.Input.Cursors]::Wait
    $metricStart = Get-Date
    Invoke-OneLinkConnectServer -Server $row
    Complete-OneLinkActivity -Name 'Connect Server' -Target ([string]$row.Host) -Outcome ($(if ($null -ne $row.Session) { 'Success' } else { 'Failed' })) -OperationSeconds (((Get-Date) - $metricStart).TotalSeconds)
    $script:Window.Cursor = [Windows.Input.Cursors]::Arrow
    Invoke-GridRefresh $ServerGrid
    Update-ConnectionSummary; Update-TargetCombos; Update-DbTargetCombo; Update-ServiceChecklist
})

$miRowDisconnect = New-Object System.Windows.Controls.MenuItem
$miRowDisconnect.Header = 'Disconnect'
$miRowDisconnect.Add_Click({
    $row = $ServerGrid.SelectedItem -as [OlServer]
    if ($null -eq $row) { return }
    $metricStart = Get-Date; $metricOutcome = 'Success'
    if ($null -ne $row.Session) { try { Disconnect-OneLinkSsh -Session $row.Session } catch { $metricOutcome = 'Failed' } }
    $row.Session = $null; $row.Credential = $null
    $row.Status = 'Not connected'; $row.ServicesDisplay = '-'
    Reset-OneLinkServerHealth -Server $row
    Invoke-GridRefresh $ServerGrid
    Update-ConnectionSummary; Update-TargetCombos; Update-DbTargetCombo; Update-ServiceChecklist
    Complete-OneLinkActivity -Name 'Disconnect Server' -Target ([string]$row.Host) -Outcome $metricOutcome -OperationSeconds (((Get-Date) - $metricStart).TotalSeconds)
    Write-OneLinkLog "[$($row.Host)] Disconnected." -Level Info
})

$miRowReconnect = New-Object System.Windows.Controls.MenuItem
$miRowReconnect.Header = 'Reconnect'
$miRowReconnect.Add_Click({
    $row = $ServerGrid.SelectedItem -as [OlServer]
    if ($null -eq $row) { return }
    Complete-ServerGridEdits
    if ($null -ne $row.Session) { try { Disconnect-OneLinkSsh -Session $row.Session } catch { } }
    $row.Session = $null; $row.Credential = $null
    $script:Window.Cursor = [Windows.Input.Cursors]::Wait
    $metricStart = Get-Date
    Invoke-OneLinkConnectServer -Server $row
    Complete-OneLinkActivity -Name 'Reconnect Server' -Target ([string]$row.Host) -Outcome ($(if ($null -ne $row.Session) { 'Success' } else { 'Failed' })) -OperationSeconds (((Get-Date) - $metricStart).TotalSeconds)
    $script:Window.Cursor = [Windows.Input.Cursors]::Arrow
    Invoke-GridRefresh $ServerGrid
    Update-ConnectionSummary; Update-TargetCombos; Update-DbTargetCombo; Update-ServiceChecklist
})

$miRowResources = New-Object System.Windows.Controls.MenuItem
$miRowResources.Header = 'View Resources'
$miRowResources.Add_Click({
    $row = $ServerGrid.SelectedItem -as [OlServer]
    if ($null -ne $row) { Show-OneLinkServerResources -Server $row }
})

$miRowCopyIp = New-Object System.Windows.Controls.MenuItem
$miRowCopyIp.Header = 'Copy IP'
$miRowCopyIp.Add_Click({
    $row = $ServerGrid.SelectedItem -as [OlServer]
    if ($null -eq $row) { return }
    try { [System.Windows.Clipboard]::SetText([string]$row.Host); Write-OneLinkLog "Copied IP $($row.Host) to the clipboard." -Level Info; Complete-OneLinkActivity -Name 'Copy Server IP' -Target ([string]$row.Host) } catch { Complete-OneLinkActivity -Name 'Copy Server IP' -Target ([string]$row.Host) -Outcome 'Failed' }
})

$miRowRemove = New-Object System.Windows.Controls.MenuItem
$miRowRemove.Header = 'Remove from list'
$miRowRemove.Add_Click({
    $row = $ServerGrid.SelectedItem -as [OlServer]
    if ($null -eq $row) { return }
    if ($null -ne $row.Session) { try { Disconnect-OneLinkSsh -Session $row.Session } catch { } }
    [void]$script:Servers.Remove($row)
    Complete-OneLinkActivity -Name 'Remove Server Row' -Target ([string]$row.Host)
    Invoke-GridRefresh $ServerGrid
    Update-TargetCombos; Update-DbTargetCombo; Update-ConnectionSummary; Update-ServiceChecklist
})

[void]$srvRowMenu.Items.Add($miRowHeader)
[void]$srvRowMenu.Items.Add((New-Object System.Windows.Controls.Separator))
[void]$srvRowMenu.Items.Add($miRowConsole)
[void]$srvRowMenu.Items.Add((New-Object System.Windows.Controls.Separator))
[void]$srvRowMenu.Items.Add($miRowConnect)
[void]$srvRowMenu.Items.Add($miRowDisconnect)
[void]$srvRowMenu.Items.Add($miRowReconnect)
[void]$srvRowMenu.Items.Add((New-Object System.Windows.Controls.Separator))
[void]$srvRowMenu.Items.Add($miRowResources)
[void]$srvRowMenu.Items.Add($miRowCopyIp)
[void]$srvRowMenu.Items.Add((New-Object System.Windows.Controls.Separator))
[void]$srvRowMenu.Items.Add($miRowRemove)

# Show the target server's IP in the header and enable only the items that apply.
$srvRowMenu.Add_Opened({
    $row = $ServerGrid.SelectedItem -as [OlServer]
    if ($null -eq $row) { return }
    $connected = ($null -ne $row.Session)
    $miRowHeader.Header      = [string]$row.Host
    $miRowConsole.IsEnabled  = $connected
    $miRowConnect.IsEnabled  = (-not $connected)
    $miRowDisconnect.IsEnabled = $connected
    $miRowReconnect.IsEnabled = $connected
    $miRowResources.IsEnabled = $connected
    $miRowCopyIp.IsEnabled   = (-not [string]::IsNullOrWhiteSpace($row.Host))
})
$ServerGrid.ContextMenu = $srvRowMenu

# Select the row under the cursor on right-click so the menu targets it.
$ServerGrid.Add_PreviewMouseRightButtonDown({
    param($eventSender, $e)
    $dep = $e.OriginalSource -as [System.Windows.DependencyObject]
    while ($null -ne $dep -and -not ($dep -is [System.Windows.Controls.DataGridRow])) {
        if ($dep -is [System.Windows.Media.Visual] -or $dep -is [System.Windows.Media.Media3D.Visual3D]) {
            $dep = [System.Windows.Media.VisualTreeHelper]::GetParent($dep)
        }
        else {
            $dep = [System.Windows.LogicalTreeHelper]::GetParent($dep)
        }
    }
    if ($dep -is [System.Windows.Controls.DataGridRow]) { $ServerGrid.SelectedItem = $dep.Item }
    else { $ServerGrid.SelectedItem = $null }   # empty area -> menu suppressed below
})
# Don't show the menu when the right-click wasn't on a server row.
$ServerGrid.Add_ContextMenuOpening({
    param($eventSender, $e)
    if ($null -eq ($ServerGrid.SelectedItem -as [OlServer])) { $e.Handled = $true }
})

# Commit any in-progress cell edit so IP/Username are captured before connect.
function Complete-ServerGridEdits {
    try {
        [void]$ServerGrid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Cell, $true)
        [void]$ServerGrid.CommitEdit([System.Windows.Controls.DataGridEditingUnit]::Row, $true)
    }
    catch { }
}

# ----------------------------------------------------------------------------
#  Connect / disconnect (per-row credentials)
# ----------------------------------------------------------------------------

$BtnConnect.Add_Click({
    Complete-ServerGridEdits
    $rows = @($script:Servers | Where-Object { -not [string]::IsNullOrWhiteSpace($_.Host) })
    if ($rows.Count -eq 0) {
        Show-ErrorMessage "Add at least one server (with an IP / host) before connecting."
        return
    }

    $script:Window.Cursor = [Windows.Input.Cursors]::Wait
    $connAllStart = Get-Date

    foreach ($server in $rows) {
        Invoke-OneLinkConnectServer -Server $server
    }

    Invoke-GridRefresh $ServerGrid
    $script:Window.Cursor = [Windows.Input.Cursors]::Arrow
    Update-ConnectionSummary
    Update-TargetCombos
    Update-DbTargetCombo
    Update-ServiceChecklist

    $connectedNow = @($script:Servers | Where-Object { $null -ne $_.Session }).Count
    Complete-OneLinkActivity -Name 'Connect All' -Target (($rows | ForEach-Object { $_.Host }) -join ', ') -Outcome ($(if (@($rows | Where-Object { $null -ne $_.Session }).Count -eq $rows.Count) { 'Success' } elseif (@($rows | Where-Object { $null -ne $_.Session }).Count -gt 0) { 'Partial' } else { 'Failed' })) -OperationSeconds (((Get-Date) - $connAllStart).TotalSeconds)
})

# Connect a SINGLE server row (shared by 'Connect All' and the row right-click menu).
function Invoke-OneLinkConnectServer {
    param([Parameter(Mandatory)]$server)
    if ($null -ne $server.Session) { return }   # already connected

    $connectStart = Get-Date
    try {
            if ([string]::IsNullOrWhiteSpace($server.Username)) { throw "Username is required." }
            if ($null -eq $server.SecurePassword -or $server.SecurePassword.Length -eq 0) { throw "Password is not set (click the Password cell)." }

            $server.Credential = New-OneLinkCredential -Username $server.Username -Password $server.SecurePassword

            Write-OneLinkLog "[$($server.Host):$($server.Port)] Connecting as $($server.Username)." -Level Info
            $server.Session = Connect-OneLinkSsh -ComputerName $server.Host -Port ([int]$server.Port) -Credential $server.Credential -Settings $script:Settings

            $validation = Test-OneLinkSshConnection -Session $server.Session

            # The tool replicates nmenu's logic inline and never invokes nmenu,
            # so its presence is irrelevant - just mark the session connected.
            $server.Status = "Connected"

            try {
                $server.Services = Get-OneLinkDiscoveredServices -Session $server.Session -Settings $script:Settings -Mappings $script:Mappings
                Update-OneLinkAuxServices -Server $server -Force   # discover non-OneLink units too, if marked Auxiliary
                $names = @($server.Services | ForEach-Object { $_.DisplayName })
                $server.ServicesDisplay = if ($names.Count) { "$($names.Count): " + ($names -join ', ') } else { '0 (none)' }
                Write-OneLinkLog "[$($server.Host)] Discovered $($names.Count) service(s): $(if ($names.Count) { $names -join ', ' } else { 'none' })." -Level Info
            }
            catch {
                $server.Services = New-Object System.Collections.Generic.List[object]
                $server.ServicesDisplay = '?'
                Write-OneLinkLog "[$($server.Host)] Service discovery failed: $($_.Exception.Message)" -Level Warning
            }

            try {
                $server.Os = Get-OneLinkOs -Session $server.Session
                Write-OneLinkLog "[$($server.Host)] OS detected: $(if ($server.Os) { $server.Os } else { 'unknown' })." -Level Info
            }
            catch { $server.Os = '' }

            # Most operations (package install, service control, SSL, MySQL) need
            # passwordless sudo. If the account doesn't have it, enable it ONCE
            # using the login password (the same account's password, already
            # entered): 'sudo -S' reads the password from stdin - no terminal
            # needed - and writes /etc/sudoers.d/onelink-admin-tool with NOPASSWD
            # for the user, i.e. the same drop-in a properly-built OneLink image
            # ships. After this, every operation runs without a password.
            try {
                $sudoChk = Invoke-OneLinkSshCommand -Session $server.Session -Command 'sudo -n true 2>/dev/null && echo OLK_SUDO_OK || echo OLK_SUDO_NO' -TimeoutSeconds 15
                if (([string]$sudoChk.Output) -notmatch 'OLK_SUDO_OK') {
                    $pwPlain = ConvertFrom-OneLinkSecure $server.SecurePassword
                    $pwArg = ConvertTo-OneLinkBashArg $pwPlain
                    $u = [string]$server.Username
                    $boot = "printf '%s\n' $pwArg | sudo -S -p '' bash -c `"echo '$u ALL=(ALL) NOPASSWD: ALL' > /etc/sudoers.d/onelink-admin-tool && chmod 440 /etc/sudoers.d/onelink-admin-tool`" 2>/dev/null; if sudo -n true 2>/dev/null; then echo OLK_SUDO_OK; else echo OLK_SUDO_NO; fi"
                    $bootRes = Invoke-OneLinkSshCommand -Session $server.Session -Command $boot -TimeoutSeconds 25
                    if (([string]$bootRes.Output) -match 'OLK_SUDO_OK') {
                        Write-OneLinkLog "[$($server.Host)] Enabled passwordless sudo for '$u' using the login password (wrote /etc/sudoers.d/onelink-admin-tool)." -Level Success
                    }
                    else {
                        $server.Status = "$($server.Status) - sudo unavailable (password rejected)"
                        Write-OneLinkLog "[$($server.Host)] WARNING: '$u' has no passwordless sudo and the login password was not accepted by sudo (or the account is not a sudoer). Package install, service control, SSL and MySQL will fail. Grant sudo/NOPASSWD on the server." -Level Warning
                    }
                }
            }
            catch { }

            try { Update-OneLinkServerHealth -Server $server } catch { }   # disk/memory health -> Resources button colour + Status

            $connectEnd = Get-Date
            Write-OneLinkLog "[$($server.Host)] Connected. $validation" -Level Success
            Write-OneLinkEfficiency -Operation 'Connect' -Target ([string]$server.Host) -Outcome 'Success' -Start $connectStart -End $connectEnd
        }
        catch {
            $connectEnd = Get-Date
            if ($null -ne $server.Session) { try { Disconnect-OneLinkSsh -Session $server.Session } catch { } }
            $server.Session = $null
            $server.Credential = $null
            $friendly = Get-OneLinkFriendlySshError $_.Exception.Message
            $server.Status = "Failed: $($friendly.Short)"
            Write-OneLinkLog ("[$($server.Host)] Connection failed: $($friendly.Short)" +
                $(if ($friendly.Hint) { ' ' + $friendly.Hint } else { '' }) +
                " (technical detail: $($_.Exception.Message))") -Level Error
            Write-OneLinkEfficiency -Operation 'Connect' -Target ([string]$server.Host) -Outcome 'Failed' -Start $connectStart -End $connectEnd
        }
}

$BtnDisconnect.Add_Click({
    $metricStart = Get-Date; $metricFailures = 0
    $metricTargets = @($script:Servers | Where-Object { $null -ne $_.Session })
    foreach ($server in $script:Servers) {
        if ($null -ne $server.Session) {
            try { Disconnect-OneLinkSsh -Session $server.Session } catch { $metricFailures++ }
        }
        $server.Session = $null
        $server.Credential = $null
        $server.Status = "Not connected"
        $server.ServicesDisplay = '-'
        Reset-OneLinkServerHealth -Server $server
    }
    Invoke-GridRefresh $ServerGrid
    Update-ConnectionSummary
    Update-ServiceChecklist
    $metricOutcome = if ($metricFailures -eq 0) { 'Success' } elseif ($metricFailures -lt $metricTargets.Count) { 'Partial' } else { 'Failed' }
    Complete-OneLinkActivity -Name 'Disconnect All' -Target (($metricTargets | ForEach-Object { $_.Host }) -join ', ') -Outcome $metricOutcome -OperationSeconds (((Get-Date) - $metricStart).TotalSeconds)
    Write-OneLinkLog "All SSH sessions disconnected." -Level Info
})

# ----------------------------------------------------------------------------
#  Config import / export (CSV) - default field values, NO passwords, NO IPs
# ----------------------------------------------------------------------------

# The fields saved/restored by the CSV config. Server rows (IPs, credentials,
# roles) and all passwords are intentionally excluded.
function Get-OneLinkConfigFields {
    return @(
        @{ Key = 'DbUser';          Ctrl = $TxtDbUser;          Type = 'text';  Section = 'Database' },
        @{ Key = 'DbAllowedIp';     Ctrl = $CmbDbUserIp;        Type = 'text';  Section = 'Database' },
        @{ Key = 'DatabaseName';    Ctrl = $TxtDatabaseName;    Type = 'text';  Section = 'Database' },
        @{ Key = 'GrantHost';       Ctrl = $CmbGrantHost;       Type = 'text'; Section = 'Database' },
        @{ Key = 'GrantUser';       Ctrl = $CmbGrantUser;       Type = 'text';  Section = 'Database' },
        @{ Key = 'ExportDatabase';  Ctrl = $CmbExportDb;        Type = 'text';  Section = 'Database' },
        @{ Key = 'ExportFile';      Ctrl = $TxtExportFile;      Type = 'text';  Section = 'Database' },
        @{ Key = 'ImportDatabase';  Ctrl = $CmbImportDb;        Type = 'text';  Section = 'Database' },
        @{ Key = 'ImportFile';      Ctrl = $TxtImportFile;      Type = 'text';  Section = 'Database' },
        @{ Key = 'PackageFolder';   Ctrl = $TxtPackagePath;     Type = 'text';  Section = 'Package' },
        @{ Key = 'RemoteDirectory'; Ctrl = $TxtRemoteDirectory; Type = 'text';  Section = 'Package' },
        @{ Key = 'InstallReason';   Ctrl = $TxtInstallReason;   Type = 'text';  Section = 'Package' },
        @{ Key = 'InstallMode';     Ctrl = $CmbInstallMode;     Type = 'combo'; Section = 'Package' },
        @{ Key = 'SslAfterInstall'; Ctrl = $CmbSslAfterInstall; Type = 'combo'; Section = 'Package' },
        @{ Key = 'ServiceAction';   Ctrl = $CmbServiceAction;   Type = 'combo'; Section = 'Service' },
        @{ Key = 'CertFile';        Ctrl = $TxtCertFile;        Type = 'text';  Section = 'Certificate' },
        @{ Key = 'CertDestination'; Ctrl = $TxtCertDest;        Type = 'text';  Section = 'Certificate' },
        @{ Key = 'CertType';        Ctrl = $CmbCertType;        Type = 'combo'; Section = 'Certificate' },
        @{ Key = 'CertScanPath';    Ctrl = $TxtCertScanPath;    Type = 'text';  Section = 'Certificate' }
    )
}

function Set-OneLinkComboByText {
    param($ComboBox, [string]$Text)
    if ([string]::IsNullOrEmpty($Text)) { return }
    for ($i = 0; $i -lt $ComboBox.Items.Count; $i++) {
        $item = $ComboBox.Items[$i]
        $itemText = if ($item.PSObject.Properties.Name -contains 'Content') { [string]$item.Content } else { [string]$item }
        if ($itemText -eq $Text) { $ComboBox.SelectedIndex = $i; return }
    }
}

# One consistent, professional column layout for the whole config CSV. Each row
# is tagged by RecordType: 'Server' rows carry the server inventory (Password is
# left BLANK on export - fill it in before importing); 'Setting' rows carry the
# form field values. This keeps everything in a single, importable file.
function New-OneLinkConfigRow {
    param(
        [string]$RecordType, [string]$HostName = '', [string]$Port = '', [string]$Username = '',
        [string]$Password = '', [string]$Roles = '', [string]$OS = '', [string]$SettingName = '', [string]$SettingValue = ''
    )
    return [PSCustomObject][ordered]@{
        RecordType = $RecordType; Host = $HostName; Port = $Port; Username = $Username
        Password = $Password; Roles = $Roles; OS = $OS; SettingName = $SettingName; SettingValue = $SettingValue
    }
}

# Minimal XML/HTML escaper (System.Web may not be loaded in the packaged EXE).
function ConvertTo-OneLinkHtmlText {
    param([string]$Text)
    $t = [string]$Text
    $t = $t -replace '&', '&amp;' -replace '<', '&lt;' -replace '>', '&gt;' -replace '"', '&quot;'
    return $t
}

# ----------------------------------------------------------------------------
#  Standalone .xlsx engine (no external module / no Excel needed). Writes a real,
#  colourful, multi-worksheet Excel file and reads it back, using only the
#  System.IO.Compression support the EXE already loads. Style indices in the
#  embedded styles.xml: 1 header-navy, 2 header-blue, 3 header-violet,
#  4 header-cyan, 5 header-green, 6 key-cell (bold, light fill), 7 value.
# ----------------------------------------------------------------------------
function Get-OneLinkXlsxCol { param([int]$n) $s = ''; while ($n -gt 0) { $m = ($n - 1) % 26; $s = [char](65 + $m) + $s; $n = [int](($n - $m - 1) / 26) }; return $s }

function Get-OneLinkXlsxStyles {
    return @'
<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<fonts count="3">
<font><sz val="11"/><color rgb="FF0F172A"/><name val="Segoe UI"/></font>
<font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Segoe UI"/></font>
<font><b/><sz val="11"/><color rgb="FF334155"/><name val="Segoe UI"/></font>
</fonts>
<fills count="8">
<fill><patternFill patternType="none"/></fill>
<fill><patternFill patternType="gray125"/></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FF1E3A8A"/></patternFill></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FF2563EB"/></patternFill></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FF7C3AED"/></patternFill></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FF0891B2"/></patternFill></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FF16A34A"/></patternFill></fill>
<fill><patternFill patternType="solid"><fgColor rgb="FFEEF2FF"/></patternFill></fill>
</fills>
<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>
<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
<cellXfs count="8">
<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>
<xf numFmtId="0" fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"><alignment vertical="center"/></xf>
<xf numFmtId="0" fontId="1" fillId="3" borderId="0" xfId="0" applyFont="1" applyFill="1"><alignment vertical="center"/></xf>
<xf numFmtId="0" fontId="1" fillId="4" borderId="0" xfId="0" applyFont="1" applyFill="1"><alignment vertical="center"/></xf>
<xf numFmtId="0" fontId="1" fillId="5" borderId="0" xfId="0" applyFont="1" applyFill="1"><alignment vertical="center"/></xf>
<xf numFmtId="0" fontId="1" fillId="6" borderId="0" xfId="0" applyFont="1" applyFill="1"><alignment vertical="center"/></xf>
<xf numFmtId="0" fontId="2" fillId="7" borderId="0" xfId="0" applyFont="1" applyFill="1"/>
<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>
</cellXfs>
<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
</styleSheet>
'@
}

# Sheet XML from $Rows (array of rows; each row = array of @{ v=text; s=styleIndex }).
function Get-OneLinkXlsxSheetXml {
    param([object[]]$Rows, [int[]]$ColWidths)
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>')
    [void]$sb.Append('<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">')
    if ($ColWidths -and $ColWidths.Count -gt 0) {
        [void]$sb.Append('<cols>')
        for ($i = 0; $i -lt $ColWidths.Count; $i++) { $c = $i + 1; [void]$sb.Append("<col min=`"$c`" max=`"$c`" width=`"$($ColWidths[$i])`" customWidth=`"1`"/>") }
        [void]$sb.Append('</cols>')
    }
    [void]$sb.Append('<sheetData>')
    $r = 0
    foreach ($row in $Rows) {
        $r++
        [void]$sb.Append("<row r=`"$r`">")
        $c = 0
        foreach ($cell in $row) {
            $c++
            $ref = (Get-OneLinkXlsxCol $c) + $r
            $s = [int]$cell.s
            $txt = ConvertTo-OneLinkHtmlText ([string]$cell.v)
            [void]$sb.Append("<c r=`"$ref`" s=`"$s`" t=`"inlineStr`"><is><t xml:space=`"preserve`">$txt</t></is></c>")
        }
        [void]$sb.Append('</row>')
    }
    [void]$sb.Append('</sheetData></worksheet>')
    return $sb.ToString()
}

# Write a multi-sheet .xlsx. $Sheets = ordered array of @{ Name; Rows; ColWidths }.
function New-OneLinkXlsx {
    param([string]$Path, [object[]]$Sheets)
    if (Test-Path -LiteralPath $Path) { Remove-Item -LiteralPath $Path -Force }
    $fs = [System.IO.File]::Open($Path, [System.IO.FileMode]::CreateNew)
    try {
        $zip = New-Object System.IO.Compression.ZipArchive($fs, [System.IO.Compression.ZipArchiveMode]::Create)
        $addEntry = {
            param($archive, $name, $content)
            $e = $archive.CreateEntry($name, [System.IO.Compression.CompressionLevel]::Optimal)
            $w = New-Object System.IO.StreamWriter($e.Open(), (New-Object System.Text.UTF8Encoding($false)))
            $w.Write($content); $w.Flush(); $w.Dispose()
        }
        $n = $Sheets.Count
        $ct = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'
        for ($i = 1; $i -le $n; $i++) { $ct += "<Override PartName=`"/xl/worksheets/sheet$i.xml`" ContentType=`"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml`"/>" }
        $ct += '</Types>'
        & $addEntry $zip '[Content_Types].xml' $ct
        & $addEntry $zip '_rels/.rels' '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'
        $wb = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'
        for ($i = 1; $i -le $n; $i++) { $nm = ConvertTo-OneLinkHtmlText ([string]$Sheets[$i - 1].Name); $wb += "<sheet name=`"$nm`" sheetId=`"$i`" r:id=`"rId$i`"/>" }
        $wb += '</sheets></workbook>'
        & $addEntry $zip 'xl/workbook.xml' $wb
        $wr = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
        for ($i = 1; $i -le $n; $i++) { $wr += "<Relationship Id=`"rId$i`" Type=`"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet`" Target=`"worksheets/sheet$i.xml`"/>" }
        $sid = $n + 1
        $wr += "<Relationship Id=`"rId$sid`" Type=`"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles`" Target=`"styles.xml`"/></Relationships>"
        & $addEntry $zip 'xl/_rels/workbook.xml.rels' $wr
        & $addEntry $zip 'xl/styles.xml' (Get-OneLinkXlsxStyles)
        for ($i = 1; $i -le $n; $i++) { & $addEntry $zip "xl/worksheets/sheet$i.xml" (Get-OneLinkXlsxSheetXml -Rows $Sheets[$i - 1].Rows -ColWidths $Sheets[$i - 1].ColWidths) }
        $zip.Dispose()
    }
    finally { $fs.Dispose() }
}

# Read an .xlsx back to an ordered map: sheetName -> array of string-cell rows.
# Handles inline strings (our writer) AND shared strings + numbers (files re-saved
# by Excel after the user edits them).
function Import-OneLinkXlsx {
    param([string]$Path)
    $fs = [System.IO.File]::OpenRead($Path)
    try {
        $zip = New-Object System.IO.Compression.ZipArchive($fs, [System.IO.Compression.ZipArchiveMode]::Read)
        $readEntry = {
            param($archive, $name)
            $e = $archive.GetEntry($name); if ($null -eq $e) { return $null }
            $rr = New-Object System.IO.StreamReader($e.Open()); $t = $rr.ReadToEnd(); $rr.Dispose(); return $t
        }
        $strip = {
            param($x)
            $x = $x -replace 'xmlns(:\w+)?="[^"]*"', ''
            $x = $x -replace '<(/?)[A-Za-z_][\w.-]*:', '<$1'
            $x = $x -replace '\s[A-Za-z_][\w.-]*:([A-Za-z_][\w.-]*=)', ' $1'
            return $x
        }
        $shared = @()
        $ssRaw = & $readEntry $zip 'xl/sharedStrings.xml'
        if ($ssRaw) { [xml]$ssx = (& $strip $ssRaw); foreach ($si in $ssx.sst.si) { $shared += , ([string]$si.InnerText) } }
        [xml]$wbx = (& $strip (& $readEntry $zip 'xl/workbook.xml'))
        [xml]$relx = (& $strip (& $readEntry $zip 'xl/_rels/workbook.xml.rels'))
        $relMap = @{}; foreach ($rel in $relx.Relationships.Relationship) { $relMap[[string]$rel.Id] = [string]$rel.Target }
        $result = [ordered]@{}
        foreach ($sh in $wbx.workbook.sheets.sheet) {
            $name = [string]$sh.name
            $target = $relMap[[string]$sh.id]; if ([string]::IsNullOrEmpty($target)) { continue }
            if ($target -match '^/') { $target = $target.TrimStart('/') } else { $target = "xl/$target" }
            $sheetRaw = & $readEntry $zip $target; if ($null -eq $sheetRaw) { continue }
            [xml]$shx = (& $strip $sheetRaw)
            $rows = New-Object System.Collections.Generic.List[object]
            if ($shx.worksheet.sheetData) {
                foreach ($row in $shx.worksheet.sheetData.row) {
                    $cells = New-Object System.Collections.Generic.List[string]
                    foreach ($c in $row.c) {
                        $ct2 = [string]$c.t; $val = ''
                        if ($ct2 -eq 'inlineStr') { $val = [string]$c.is.InnerText }
                        elseif ($ct2 -eq 's') { $idx = 0; [void][int]::TryParse([string]$c.v, [ref]$idx); if ($idx -ge 0 -and $idx -lt $shared.Count) { $val = $shared[$idx] } }
                        else { $val = [string]$c.v }
                        $cells.Add($val)
                    }
                    $rows.Add($cells.ToArray())
                }
            }
            $result[$name] = $rows.ToArray()
        }
        $zip.Dispose()
        return $result
    }
    finally { $fs.Dispose() }
}

# Cell helper for building xlsx rows.
function New-OneLinkXlsxCell { param([string]$Value, [int]$Style = 7) return @{ v = $Value; s = $Style } }

# Build the workbook sheet layout for the config: a 'Servers' tab plus one tab per
# option group (Database / Package / Certificate / Service), each colour-headed.
# $ServerRows: @{Host;Port;Username;Password;Roles;OS}; $SettingRows: @{Key;Value;Section}.
function Get-OneLinkConfigSheets {
    param([object[]]$ServerRows, [object[]]$SettingRows)
    $sheets = @()
    $srows = @()
    $srows += , @( @('Host', 'Port', 'Username', 'Password', 'Roles', 'OS') | ForEach-Object { New-OneLinkXlsxCell $_ 1 } )
    foreach ($s in $ServerRows) {
        $srows += , @(
            (New-OneLinkXlsxCell ([string]$s.Host)),
            (New-OneLinkXlsxCell ([string]$s.Port)),
            (New-OneLinkXlsxCell ([string]$s.Username)),
            (New-OneLinkXlsxCell ([string]$s.Password)),
            (New-OneLinkXlsxCell ([string]$s.Roles)),
            (New-OneLinkXlsxCell ([string]$s.OS))
        )
    }
    $sheets += @{ Name = 'Servers'; Rows = $srows; ColWidths = @(20, 7, 18, 16, 30, 10) }

    $sectionStyle = @{ 'Database' = 2; 'Package' = 3; 'Certificate' = 4; 'Service' = 5 }
    foreach ($section in @('Database', 'Package', 'Certificate', 'Service')) {
        $items = @($SettingRows | Where-Object { $_.Section -eq $section })
        if ($items.Count -eq 0) { continue }
        $hstyle = [int]$sectionStyle[$section]
        $rows = @()
        $rows += , @( (New-OneLinkXlsxCell 'Option' $hstyle), (New-OneLinkXlsxCell 'Value' $hstyle) )
        foreach ($it in $items) {
            $rows += , @( (New-OneLinkXlsxCell ([string]$it.Key) 6), (New-OneLinkXlsxCell ([string]$it.Value)) )
        }
        $sheets += @{ Name = $section; Rows = $rows; ColWidths = @(26, 52) }
    }
    return $sheets
}

# Build a colourful, easy-to-read HTML view of the configuration (servers + all
# option groups). Opens in any browser; for reading / sharing / printing.
# $ServerRows: @{Host;Port;Username;Password;Roles;OS}; $SettingRows: @{Key;Value;Section}.
function ConvertTo-OneLinkConfigHtml {
    param([object[]]$ServerRows, [object[]]$SettingRows, [string]$Title, [switch]$IsTemplate)
    $enc = { param($s) ConvertTo-OneLinkHtmlText $s }
    $sectionColors = @{ 'Database' = '#2563EB'; 'Package' = '#7C3AED'; 'Certificate' = '#0891B2'; 'Service' = '#16A34A' }
    $stamp = (Get-Date).ToString('dd-MMM-yyyy HH:mm')
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append(@"
<!DOCTYPE html><html><head><meta charset="utf-8"><title>$(& $enc $Title)</title>
<style>
 body{font-family:'Segoe UI',Arial,sans-serif;background:#f5f7fb;color:#0f172a;margin:0;padding:24px;}
 .wrap{max-width:1000px;margin:0 auto;}
 .hd{background:linear-gradient(90deg,#2563eb,#4f46e5,#7c3aed);color:#fff;padding:18px 22px;border-radius:12px;}
 .hd h1{margin:0;font-size:22px;} .hd p{margin:4px 0 0;color:#dbe4ff;font-size:13px;}
 .card{background:#fff;border:1px solid #e2e8f0;border-radius:12px;margin:16px 0;overflow:hidden;box-shadow:0 1px 3px rgba(15,23,42,.06);}
 .cap{padding:10px 16px;font-weight:600;color:#fff;font-size:14px;}
 table{border-collapse:collapse;width:100%;font-size:13px;}
 th{background:#f1f5f9;text-align:left;padding:9px 14px;color:#334155;border-bottom:1px solid #e2e8f0;font-weight:600;}
 td{padding:8px 14px;border-bottom:1px solid #eef2f7;}
 tr:nth-child(even) td{background:#fafcff;}
 .k{color:#475569;width:34%;font-weight:600;}
 .muted{color:#94a3b8;font-style:italic;}
 .note{background:#eff6ff;border:1px solid #bfdbfe;color:#1e3a8a;border-radius:8px;padding:10px 14px;font-size:13px;margin:12px 0;}
 .foot{color:#94a3b8;font-size:12px;text-align:center;margin-top:18px;}
</style></head><body><div class="wrap">
<div class="hd"><h1>$($script:AppName) &#8212; Deployment Configuration</h1><p>$(& $enc $Title) &#183; generated $stamp</p></div>
"@)
    if ($IsTemplate) {
        [void]$sb.Append('<div class="note"><b>Template.</b> Fill in the values below (or edit the matching <b>.csv</b>), then use <b>Import Config</b> in ' + $script:AppName + '. Passwords are blank by design &#8212; add them in the CSV before importing.</div>')
    }
    # Servers card
    [void]$sb.Append('<div class="card"><div class="cap" style="background:#1e3a8a">Servers</div><table><tr><th>Host / IP</th><th>Port</th><th>Username</th><th>Password</th><th>Roles</th><th>OS</th></tr>')
    if (@($ServerRows).Count -eq 0) {
        [void]$sb.Append('<tr><td colspan="6" class="muted">(no server rows)</td></tr>')
    }
    else {
        foreach ($r in $ServerRows) {
            $pw = if ([string]::IsNullOrEmpty([string]$r.Password)) { '<span class="muted">(add in CSV)</span>' } else { '&#8226;&#8226;&#8226;&#8226;&#8226;&#8226;' }
            [void]$sb.Append("<tr><td>$(& $enc $r.Host)</td><td>$(& $enc $r.Port)</td><td>$(& $enc $r.Username)</td><td>$pw</td><td>$(& $enc $r.Roles)</td><td>$(& $enc $r.OS)</td></tr>")
        }
    }
    [void]$sb.Append('</table></div>')
    # Settings grouped by section
    foreach ($section in @('Database', 'Package', 'Certificate', 'Service')) {
        $items = @($SettingRows | Where-Object { $_.Section -eq $section })
        if ($items.Count -eq 0) { continue }
        $color = $sectionColors[$section]
        [void]$sb.Append("<div class=`"card`"><div class=`"cap`" style=`"background:$color`">$section</div><table><tr><th class=`"k`">Option</th><th>Value</th></tr>")
        foreach ($it in $items) {
            $val = if ([string]::IsNullOrWhiteSpace([string]$it.Value)) { '<span class="muted">(not set)</span>' } else { & $enc $it.Value }
            [void]$sb.Append("<tr><td class=`"k`">$(& $enc $it.Key)</td><td>$val</td></tr>")
        }
        [void]$sb.Append('</table></div>')
    }
    [void]$sb.Append("<div class=`"foot`">$($script:AppName) &#183; $($script:AppTagline)</div></div></body></html>")
    return $sb.ToString()
}

$BtnExportConfig.Add_Click({
    try {
        $sfd = New-Object Microsoft.Win32.SaveFileDialog
        $sfd.Filter = "Excel workbook (*.xlsx)|*.xlsx|All files (*.*)|*.*"
        $sfd.FileName = "$($script:AppName)-config.xlsx"
        if (-not $sfd.ShowDialog()) { return }

        $serverRows = New-Object System.Collections.Generic.List[object]
        $settingRows = New-Object System.Collections.Generic.List[object]
        # Server inventory (Password intentionally BLANK - the user fills it before importing).
        foreach ($s in $script:Servers) {
            if ([string]::IsNullOrWhiteSpace($s.Host)) { continue }
            $serverRows.Add([pscustomobject]@{ Host = [string]$s.Host; Port = [string]$s.Port; Username = [string]$s.Username; Password = ''; Roles = [string]$s.Roles; OS = [string]$s.Os })
        }
        # Form settings, grouped into their tabs.
        foreach ($f in (Get-OneLinkConfigFields)) {
            $value = if ($f.Type -eq 'combo') { Get-ComboText $f.Ctrl } else { [string]$f.Ctrl.Text }
            $settingRows.Add([pscustomobject]@{ Key = $f.Key; Value = $value; Section = $f.Section })
        }

        $sheets = Get-OneLinkConfigSheets -ServerRows $serverRows.ToArray() -SettingRows $settingRows.ToArray()
        New-OneLinkXlsx -Path $sfd.FileName -Sheets $sheets

        $svrCount = $serverRows.Count
