$BtnImportConfig.Add_Click({
    try {
        $ofd = New-Object Microsoft.Win32.OpenFileDialog
        $ofd.Filter = "Config file (*.xlsx;*.csv)|*.xlsx;*.csv|Excel workbook (*.xlsx)|*.xlsx|CSV config (*.csv)|*.csv|All files (*.*)|*.*"
        if (-not $ofd.ShowDialog()) { return }

        $fields = @{}
        foreach ($f in (Get-OneLinkConfigFields)) { $fields[$f.Key] = $f }
        $settingCount = 0
        $newServers = New-Object System.Collections.Generic.List[object]

        # Apply one setting key/value to its control. Returns 1 if applied, else 0.
        $applySetting = {
            param($key, $value)
            if ($fields.ContainsKey($key)) {
                $ff = $fields[$key]
                if ($ff.Type -eq 'combo') { Set-OneLinkComboByText -ComboBox $ff.Ctrl -Text $value } else { $ff.Ctrl.Text = $value }
                return 1
            }
            return 0
        }
        # Build an OlServer from parts (skips the template placeholder password).
        $makeServer = {
            param($h, $port, $user, $roles, $os, $pw)
            $srv = [OlServer]::new()
            $srv.Host = [string]$h
            $pp = 22; [void][int]::TryParse([string]$port, [ref]$pp); $srv.Port = $pp
            $srv.Username = [string]$user
            $srv.Roles = [string]$roles
            $srv.RolesDisplay = if ([string]::IsNullOrWhiteSpace($srv.Roles)) { 'Select...' } else { $srv.Roles }
            $srv.Os = [string]$os
            if (-not [string]::IsNullOrEmpty([string]$pw) -and ([string]$pw) -ne '<ssh-password>') {
                $srv.SecurePassword = ConvertTo-SecureString ([string]$pw) -AsPlainText -Force
                $srv.PasswordDisplay = ([string][char]0x25CF) * 6
            }
            return $srv
        }

        if ([IO.Path]::GetExtension($ofd.FileName) -ieq '.xlsx') {
            # ---- Excel workbook (tabs: Servers, Database, Package, Certificate, Service) ----
            $book = Import-OneLinkXlsx -Path $ofd.FileName
            foreach ($sheetName in $book.Keys) {
                $rows = @($book[$sheetName])
                if ($rows.Count -lt 1) { continue }
                if ($sheetName -eq 'Servers') {
                    for ($i = 1; $i -lt $rows.Count; $i++) {   # row 0 is the header
                        $r = @($rows[$i]); if ($r.Count -lt 1 -or [string]::IsNullOrWhiteSpace([string]$r[0])) { continue }
                        $g = { param($a, $j) if ($j -lt $a.Count) { [string]$a[$j] } else { '' } }
                        $newServers.Add((& $makeServer (& $g $r 0) (& $g $r 1) (& $g $r 2) (& $g $r 4) (& $g $r 5) (& $g $r 3)))
                    }
                }
                else {
                    # Option / Value tab -> settings
                    for ($i = 1; $i -lt $rows.Count; $i++) {
                        $r = @($rows[$i]); if ($r.Count -lt 1) { continue }
                        $key = [string]$r[0]; $val = if ($r.Count -ge 2) { [string]$r[1] } else { '' }
                        $settingCount += (& $applySetting $key $val)
                    }
                }
            }
        }
        else {
            # ---- CSV (current + legacy formats) ----
            $data = @(Import-Csv -LiteralPath $ofd.FileName)
            if ($data.Count -eq 0) { Show-WarningMessage "The file is empty."; return }
            $hasRecordType = @($data | Get-Member -MemberType NoteProperty -Name RecordType).Count -gt 0
            if (-not $hasRecordType) {
                foreach ($record in $data) { $settingCount += (& $applySetting ([string]$record.Key) ([string]$record.Value)) }
            }
            else {
                foreach ($record in $data) {
                    $rt = [string]$record.RecordType
                    if ($rt -eq 'Server') {
                        if ([string]::IsNullOrWhiteSpace($record.Host)) { continue }
                        $newServers.Add((& $makeServer ([string]$record.Host) ([string]$record.Port) ([string]$record.Username) ([string]$record.Roles) ([string]$record.OS) ([string]$record.Password)))
                    }
                    elseif ($rt -eq 'Setting') {
                        $settingCount += (& $applySetting ([string]$record.SettingName) ([string]$record.SettingValue))
                    }
                }
            }
        }

        # Load the imported servers into the grid.
        if ($newServers.Count -gt 0) {
            $existing = @($script:Servers | Where-Object { -not [string]::IsNullOrWhiteSpace($_.Host) })
            $replace = $true
            if ($existing.Count -gt 0) {
                $ans = [System.Windows.MessageBox]::Show(
                    "The file has $($newServers.Count) server(s). Replace the current $($existing.Count) server row(s), or append?" + [Environment]::NewLine +
                    "Yes = replace   .   No = append   .   Cancel = keep only settings",
                    'Import servers', 'YesNoCancel', 'Question')
                if ($ans -eq 'Cancel') { $newServers.Clear() }
                elseif ($ans -eq 'No') { $replace = $false }
            }
            if ($newServers.Count -gt 0) {
                if ($replace) {
                    foreach ($s in $script:Servers) { if ($null -ne $s.Session) { try { Disconnect-OneLinkSsh -Session $s.Session } catch { } } }
                    $script:Servers.Clear()
                }
                foreach ($s in $newServers) { $script:Servers.Add($s) }
                Invoke-GridRefresh $ServerGrid
                Update-ConnectionSummary
                Update-TargetCombos
                Update-DbTargetCombo
            }
        }

        Write-OneLinkLog "Configuration imported from $($ofd.FileName): $($newServers.Count) server(s), $settingCount setting(s)." -Level Success
        Show-InfoMessage ("Imported from:`n$($ofd.FileName)`n`n" +
            "$($newServers.Count) server(s) and $settingCount setting(s) applied.`n" +
            "For any server whose Password was left blank, click its Password cell to set it before connecting.")
    }
    catch {
        Show-ErrorMessage "Import failed. $($_.Exception.Message)"
    }
})

# ----------------------------------------------------------------------------
#  Operations
# ----------------------------------------------------------------------------

# Resolve the MySQL/MariaDB unit on a server: prefer the OS default (mysqld on
# RHEL, mysql on Debian) and report whether it is running / stopped / present.
function Resolve-OneLinkMysql {
    param($Server)
    $order = if ([string]$Server.Os -eq 'debian') { @('mysql','mysqld','mariadb') } else { @('mysqld','mysql','mariadb') }
    $fallback = $null
    foreach ($unit in $order) {
        $cmd = "PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:`$PATH; " +
               "A=`$(systemctl is-active '$unit' 2>/dev/null); " +
               "E=`$(systemctl list-unit-files '$unit.service' --no-legend 2>/dev/null | wc -l); " +
               "echo `"`$A|`$E`""
        $r = Invoke-OneLinkSshCommand -Session $Server.Session -Command $cmd -TimeoutSeconds 15
        $parts = (([string]$r.Output).Trim() -split '\|')
        $active = if ($parts.Count -ge 1) { $parts[0].Trim() } else { '' }
        $exists = if ($parts.Count -ge 2) { ([int]("0" + ($parts[1] -replace '\D',''))) -ge 1 } else { $false }
        if ($active -eq 'active') { return [pscustomobject]@{ Unit = $unit; State = 'Running'; Exists = $true } }
        if ($exists -and -not $fallback) { $fallback = [pscustomobject]@{ Unit = $unit; State = 'Stopped'; Exists = $true } }
    }
    if ($fallback) { return $fallback }
    return [pscustomobject]@{ Unit = $order[0]; State = 'Unknown'; Exists = $false }
}

function Set-OneLinkMysqlStatusBox {
    param([string]$State, [string]$Unit)
    switch ($State) {
        'Running' { $TxtMysqlStatus.Text = "Status: RUNNING ($Unit)"; $TxtMysqlStatus.Foreground = [System.Windows.Media.Brushes]::ForestGreen }
        'Stopped' { $TxtMysqlStatus.Text = "Status: STOPPED ($Unit)"; $TxtMysqlStatus.Foreground = [System.Windows.Media.Brushes]::Crimson }
        default   { $TxtMysqlStatus.Text = "Status: unknown"; $TxtMysqlStatus.Foreground = [System.Windows.Media.Brushes]::Gray }
    }
}

# Resolve ONE selected Database-target server (connected). For single-server DB
# operations (export / import / MySQL control); if several are ticked, uses the first.
function Get-OneLinkDbTargetServer {
    $srv = @(Get-OneLinkTargetHosts -Key 'Db')
    if ($srv.Count -eq 0) { Show-ErrorMessage "Select a Database target server (mark a server 'Database master' or 'Database slave', Connect it, then tick it under 'Target server')."; return $null }
    if ($srv.Count -gt 1) { Show-ErrorMessage 'Select exactly one Database target for this action. Create Database, Create User and Grant support multiple targets.'; return $null }
    return $srv[0]
}

# Detect the installed MySQL service and whether its data directory is initialized.
function Get-OneLinkMysqlSetupState {
    param($Session)
    $cmd = @'
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH
A=$(systemctl is-active mysqld 2>/dev/null)
DD=$(sudo my_print_defaults mysqld 2>/dev/null | sed -n 's/^--datadir=//p' | tail -1)
[ -z "$DD" ] && DD=/var/lib/mysql
INIT=no
if [ -f "$DD/mysql.ibd" ] || [ -f "$DD/ibdata1" ] || [ -d "$DD/mysql" ]; then INIT=yes; fi
echo "OLK_A=$A;OLK_INIT=$INIT"
'@
    $r = Invoke-OneLinkSshCommand -Session $Session -Command (ConvertTo-OneLinkDatabaseCommand $cmd) -TimeoutSeconds 20
    $t = ([string]$r.Output)
    $active = ($t -match 'OLK_A=active')
    $initialized = ($t -match 'OLK_INIT=yes') -or $active
    return [pscustomobject]@{ Active = $active; Initialized = $initialized }
}

function Invoke-OneLinkMysqlEnableRhel {
    param($Session, $Settings)
    # Use the installed service's initialization/configuration. Do not reset root
    # credentials or disable MySQL password validation as a side effect of Start.
    $cmd = @'
set -e
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH
if [ "$(id -u)" = 0 ]; then systemctl enable --now mysqld; else sudo -n systemctl enable --now mysqld; fi
systemctl is-active --quiet mysqld
'@
    Invoke-OneLinkDatabaseCommand -Session $Session -Command $cmd -TimeoutSeconds ([Math]::Max([int]$Settings.Ssh.CommandTimeoutSeconds, 300)) | Out-Null
    return 'MySQL is enabled and running. Existing authentication settings were preserved.'
}
function Invoke-OneLinkMysqlControl {
    param([Parameter(Mandatory)][ValidateSet('Restart','Stop','Status')][string]$Action)

    $server = Get-OneLinkDbTargetServer
    if ($null -eq $server) { return }

    $script:Window.Cursor = [Windows.Input.Cursors]::Wait
    $start = Get-Date
    $outcome = 'Failed'
    try {
        $mysql = Resolve-OneLinkMysql -Server $server
        if (-not $mysql.Exists -and $Action -ne 'Status') {
            throw "No MySQL/MariaDB service found on $($server.Host) (looked for mysqld / mysql / mariadb)."
        }

        switch ($Action) {
            'Restart' {
                if ([string]$server.Os -eq 'redhat' -and $mysql.Unit -eq 'mysqld') {
                    # RHEL: a plain restart fails on a FRESH VM (mysqld is disabled and
                    # not initialised), so the first time we enable the installed MySQL service.
                    # Once MySQL is set up, a restart is just a restart.
                    $state = Get-OneLinkMysqlSetupState -Session $server.Session
                    if (-not $state.Initialized) {
                        # First-time setup: nothing exists yet, so nothing to lose - no
                        # scary prompt. Enable + start it the OneLink way.
                        Write-OneLinkLog "[$($server.Host)] MySQL not set up yet - running first-time enable (RHEL)." -Level Info
                        $out = Invoke-OneLinkMysqlEnableRhel -Session $server.Session -Settings $script:Settings
                        Write-OneLinkLog "[$($server.Host)] MySQL first-time enable (RHEL): $out" -Level Success
                    }
                    else {
                        # Already set up: MySQL HAS data now, so confirm before restarting.
                        $ans = [System.Windows.MessageBox]::Show(
                            "MySQL is already set up on $($server.Host). Restart it now?" + [Environment]::NewLine +
                            "The database will briefly stop while it restarts.",
                            'Restart MySQL', 'YesNo', 'Question')
                        if ($ans -ne 'Yes') { $outcome = 'Cancelled'; Write-OneLinkLog "[$($server.Host)] MySQL restart cancelled." -Level Info; return }
                        Invoke-OneLinkDatabaseServiceAction -Session $server.Session -Unit $mysql.Unit -TimeoutSeconds ([int]$script:Settings.Ssh.CommandTimeoutSeconds) -Action 'Restart' | Out-Null
                        Write-OneLinkLog "[$($server.Host)] MySQL ($($mysql.Unit)) restarted." -Level Success
                    }
                }
                else {
                    Invoke-OneLinkDatabaseServiceAction -Session $server.Session -Unit $mysql.Unit -TimeoutSeconds ([int]$script:Settings.Ssh.CommandTimeoutSeconds) -Action 'Restart' | Out-Null
                    Write-OneLinkLog "[$($server.Host)] MySQL ($($mysql.Unit)) restarted." -Level Success
                }
            }
            'Stop' {
                Invoke-OneLinkDatabaseServiceAction -Session $server.Session -Unit $mysql.Unit -TimeoutSeconds ([int]$script:Settings.Ssh.CommandTimeoutSeconds) -Action 'Stop' | Out-Null
                Write-OneLinkLog "[$($server.Host)] MySQL ($($mysql.Unit)) stopped." -Level Success
            }
            'Status' {
                $r = Invoke-OneLinkSshCommand -Session $server.Session -Command ("systemctl status --no-pager -- " + (ConvertTo-OneLinkBashArg $mysql.Unit)) -TimeoutSeconds 30
                Write-OneLinkLog "[$($server.Host)] MySQL ($($mysql.Unit)) status:`n$($r.Output)" -Level Info
            }
        }

        # Re-read and show current state.
        $after = Resolve-OneLinkMysql -Server $server
        Set-OneLinkMysqlStatusBox -State $after.State -Unit $after.Unit
        $outcome = 'Success'
        Write-OneLinkEfficiency -Operation "MySQL $Action" -Target ([string]$server.Host) -Outcome 'Success' -Start $start -End (Get-Date)
    }
    catch {
        Write-OneLinkLog "[$($server.Host)] MySQL $Action failed. $($_.Exception.Message)" -Level Error
        Write-OneLinkEfficiency -Operation "MySQL $Action" -Target ([string]$server.Host) -Outcome 'Failed' -Start $start -End (Get-Date)
        Show-ErrorMessage "MySQL $Action failed on $($server.Host). $($_.Exception.Message)"
    }
    finally {
        $script:Window.Cursor = [Windows.Input.Cursors]::Arrow
        Complete-OneLinkActivity -Name "MySQL $Action" -Target ([string]$server.Host) -Outcome $outcome -OperationSeconds (((Get-Date) - $start).TotalSeconds)
    }
}

$BtnMysqlRestart.Add_Click({ Invoke-OneLinkMysqlControl -Action 'Restart' })
$BtnMysqlStop.Add_Click({ Invoke-OneLinkMysqlControl -Action 'Stop' })
$BtnMysqlStatus.Add_Click({ Invoke-OneLinkMysqlControl -Action 'Status' })

# Run a MySQL query on a target over SSH (via sudo mysql) and return the rows
# as a string array. Uses -N -B for clean, tab-separated, header-less output.
function Invoke-OneLinkMysqlQuery {
    param($Session, [string]$Sql, [int]$TimeoutSeconds = 30)
    $out = (Invoke-OneLinkDatabaseCommand -Session $Session -Command (New-OneLinkMysqlSqlCommand $Sql) -TimeoutSeconds $TimeoutSeconds).Trim()
    if ([string]::IsNullOrWhiteSpace($out)) { return @() }
    return @($out -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' })
}

# ============================================================================
#  InnoDB Buffer Pool Size (Database tab).
#  Mirrors the nmenu 'ndb_innodb_buffer_pool' script's logic directly (same
#  as the rest of this tool, no nmenu dependency on the target): 75% of Total
#  RAM is the recommended/enforced maximum, the value is rounded to the
#  nearest 128 MB (MySQL's allocation granularity), and the setting lives in
#  the SAME config file on both RHEL and Debian - only the systemd unit used
#  to restart MySQL differs by OS (resolved the same way as the existing
#  Restart/Stop buttons via Resolve-OneLinkMysql).
# ============================================================================

$script:InnodbConfigFile = '/etc/mysql/mysql.conf.d/zz-aristocrat.cnf'
$script:InnodbMaxBytes = $null   # cached 75%-of-RAM cap from the last Check/Apply on the current target

# Bytes -> "X.XX GB" / "X.XX MB" (matches the nmenu script's bytes_to_human()).
function Format-OneLinkInnodbSize {
    param([double]$Bytes)
    if ($Bytes -ge 1GB) { return ('{0:N2} GB' -f ($Bytes / 1GB)) }
    return ('{0:N2} MB' -f ($Bytes / 1MB))
}

# Parse a user-entered size like "1.5G", "500M", "2GB", "1.5g", "500mb" into
# bytes. Matches the nmenu script's ^[0-9]+(\.[0-9]+)?[GgMm]$ validation,
# extended to also accept an optional trailing "B" (GB/Gb/gb/MB/Mb/mb).
function Convert-OneLinkInnodbSizeToBytes {
    param([string]$Text)
    $t = ([string]$Text).Trim()
    if ($t -notmatch '^(?<num>[0-9]+(\.[0-9]+)?)\s*(?<unit>[GgMm][Bb]?)$') {
        throw "Invalid format. Please provide a number followed by G or M (e.g., 1.5G, 500M, 2GB)."
    }
    $value = [double]$Matches['num']
    $unit = $Matches['unit'].Substring(0,1).ToUpperInvariant()
    if ($unit -eq 'G') { return [math]::Round($value * 1GB) }
    return [math]::Round($value * 1MB)
}

# Round to the nearest 128 MB multiple, exactly like the nmenu script's
# NEAREST=$(( (BYTES + MULTIPLE/2) / MULTIPLE * MULTIPLE )) integer math.
function Get-OneLinkInnodbNearest128 {
    param([double]$Bytes)
    $chunk = 128MB
    return [math]::Floor(($Bytes + ($chunk / 2)) / $chunk) * $chunk
}

# Read current innodb_buffer_pool_size + /proc/meminfo from the target and
# compute the recommended maximum: 75% of Total RAM, minus a 0.001 GB
# rounding-safety margin - identical math to the nmenu script.
function Get-OneLinkInnodbStatus {
    param($Session)
    $rows = @(Invoke-OneLinkMysqlQuery -Session $Session -Sql "SHOW VARIABLES LIKE 'innodb_buffer_pool_size';")
    $current = 0.0
    if ($rows.Count -gt 0) {
        $parts = $rows[0] -split "`t"
        if ($parts.Count -ge 2) { $current = [double]("0" + ($parts[1] -replace '[^\d.]','')) }
    }

    $memCmd = 'T=$(awk ''/^MemTotal:/{print $2}'' /proc/meminfo); A=$(awk ''/^MemAvailable:/{print $2}'' /proc/meminfo); echo "$T|$A"'
    $mem = Invoke-OneLinkSshCommand -Session $Session -Command $memCmd -TimeoutSeconds 15
    $memParts = ([string]$mem.Output).Trim() -split '\|'
    $totalKb = if ($memParts.Count -ge 1) { [double]("0" + ($memParts[0] -replace '\D','')) } else { 0 }
    $availKb = if ($memParts.Count -ge 2) { [double]("0" + ($memParts[1] -replace '\D','')) } else { 0 }

    $totalBytes = $totalKb * 1KB
    $availBytes = $availKb * 1KB
    $maxGbSafe = [math]::Round(($totalBytes * 0.75 / 1GB) - 0.001, 3)
    if ($maxGbSafe -lt 0) { $maxGbSafe = 0 }
    $maxBytesSafe = [math]::Round($maxGbSafe * 1GB)

    [pscustomobject]@{
        CurrentBytes = $current
        TotalBytes   = $totalBytes
        AvailBytes   = $availBytes
        MaxBytesSafe = $maxBytesSafe
    }
}

# Refresh the info box + live-validate whatever is currently typed.
function Update-OneLinkInnodbWarning {
    $text = $TxtInnodbSize.Text
    if ([string]::IsNullOrWhiteSpace($text)) {
        $BrdInnodbWarn.Background = [System.Windows.Media.Brushes]::Transparent
        $TxtInnodbWarn.Foreground = $script:Window.FindResource('MutedTextBrush')
        $TxtInnodbWarn.Text = "Enter a size (e.g. 1.5G, 500M) and click 'Check Current / Recommended' to compare it against this server's RAM."
        return
    }
    try {
        $bytes = Convert-OneLinkInnodbSizeToBytes $text
    }
    catch {
        $BrdInnodbWarn.Background = [System.Windows.Media.Brushes]::Transparent
        $TxtInnodbWarn.Foreground = $script:Window.FindResource('WarningBrush')
        $TxtInnodbWarn.Text = $_.Exception.Message
        return
    }
    if ($null -eq $script:InnodbMaxBytes) {
        $BrdInnodbWarn.Background = [System.Windows.Media.Brushes]::Transparent
        $TxtInnodbWarn.Foreground = $script:Window.FindResource('MutedTextBrush')
        $TxtInnodbWarn.Text = "$(Format-OneLinkInnodbSize $bytes) entered. Click 'Check Current / Recommended' first to compare it against this server's RAM."
        return
    }
    if ($bytes -gt $script:InnodbMaxBytes) {
        $BrdInnodbWarn.Background = [System.Windows.Media.Brushes]::MistyRose
        $TxtInnodbWarn.Foreground = $script:Window.FindResource('DangerBrush')
        $TxtInnodbWarn.Text = "CAUTION: $(Format-OneLinkInnodbSize $bytes) exceeds the recommended maximum ($(Format-OneLinkInnodbSize $script:InnodbMaxBytes) = 75% of Total RAM). Please enter the recommended size or less."
    }
    else {
        $BrdInnodbWarn.Background = [System.Windows.Media.Brushes]::Honeydew
        $TxtInnodbWarn.Foreground = $script:Window.FindResource('SuccessBrush')
        $TxtInnodbWarn.Text = "OK: $(Format-OneLinkInnodbSize $bytes) is within the recommended maximum ($(Format-OneLinkInnodbSize $script:InnodbMaxBytes))."
    }
}
$TxtInnodbSize.Add_TextChanged({ Update-OneLinkInnodbWarning })

function Invoke-OneLinkInnodbCheck {
    $server = Get-OneLinkDbTargetServer
    if ($null -eq $server) { return }
    $script:Window.Cursor = [Windows.Input.Cursors]::Wait
    try {
        $info = Get-OneLinkInnodbStatus -Session $server.Session
        $script:InnodbMaxBytes = $info.MaxBytesSafe
        $TxtInnodbInfo.Text =
            "Current innodb_buffer_pool_size: $(Format-OneLinkInnodbSize $info.CurrentBytes)" + [Environment]::NewLine +
            "Total RAM: $(Format-OneLinkInnodbSize $info.TotalBytes)   |   Available RAM: $(Format-OneLinkInnodbSize $info.AvailBytes)" + [Environment]::NewLine +
            "Recommended maximum (75% of Total RAM): $(Format-OneLinkInnodbSize $info.MaxBytesSafe)"
        Update-OneLinkInnodbWarning
        Write-OneLinkLog "[$($server.Host)] InnoDB buffer pool checked: current $(Format-OneLinkInnodbSize $info.CurrentBytes), recommended max $(Format-OneLinkInnodbSize $info.MaxBytesSafe)." -Level Info
    }
    catch {
        Show-ErrorMessage "Could not read InnoDB buffer pool / RAM info from $($server.Host). $($_.Exception.Message)"
    }
    finally {
        $script:Window.Cursor = [Windows.Input.Cursors]::Arrow
    }
}

function Invoke-OneLinkInnodbApply {
    $server = Get-OneLinkDbTargetServer
    if ($null -eq $server) { return }

    $script:Window.Cursor = [Windows.Input.Cursors]::Wait
    $start = Get-Date
    $outcome = 'Failed'
    try {
        $bytes = Convert-OneLinkInnodbSizeToBytes $TxtInnodbSize.Text

        $info = Get-OneLinkInnodbStatus -Session $server.Session
        $script:InnodbMaxBytes = $info.MaxBytesSafe
        Update-OneLinkInnodbWarning

        if ($bytes -gt $info.MaxBytesSafe) {
            $outcome = 'Cancelled'
            Show-ErrorMessage ("Entered value ({0}) exceeds 75% of total system RAM (recommended maximum: {1} on {2}). Please enter a size within the recommended limit." -f (Format-OneLinkInnodbSize $bytes), (Format-OneLinkInnodbSize $info.MaxBytesSafe), $server.Host)
            return
        }

        $nearest = Get-OneLinkInnodbNearest128 $bytes
        $note = if ($nearest -ne $bytes) { "MySQL enforces innodb_buffer_pool_size in multiples of 128 MB - the nearest multiple to $(Format-OneLinkInnodbSize $bytes) is $(Format-OneLinkInnodbSize $nearest)." + [Environment]::NewLine } else { '' }

        $ans = [System.Windows.MessageBox]::Show(
            $note + "This will set innodb_buffer_pool_size to $(Format-OneLinkInnodbSize $nearest) on $($server.Host) and restart MySQL. Proceed?",
            'InnoDB Buffer Pool Size', 'YesNo', 'Warning')
        if ($ans -ne 'Yes') { $outcome = 'Cancelled'; Write-OneLinkLog "[$($server.Host)] InnoDB buffer pool change cancelled." -Level Info; return }

        $cfgArg = ConvertTo-OneLinkBashArg $script:InnodbConfigFile
        $bytesArg = ConvertTo-OneLinkBashArg ([string][int64]$nearest)
        $tmpl = @'
set -e
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH
CFG=__CFGQ__
BYTES=__BYTESQ__
if [ ! -f "$CFG" ]; then echo "Config file $CFG not found on this server." >&2; exit 1; fi
BACKUP="${CFG}.bak.$(date +%F_%H%M%S)"
sudo cp "$CFG" "$BACKUP"
if grep -q "innodb_buffer_pool_size" "$CFG"; then
    sudo sed -i "s/^\s*innodb_buffer_pool_size\s*=.*/innodb_buffer_pool_size=$BYTES/" "$CFG"
else
    sudo sed -i "/^\[mysqld\]/a innodb_buffer_pool_size=$BYTES" "$CFG"
fi
echo "BACKUP=$BACKUP"
'@
        $cmd = $tmpl.Replace('__CFGQ__', $cfgArg).Replace('__BYTESQ__', $bytesArg)
        $cfgOut = Invoke-OneLinkDatabaseCommand -Session $server.Session -Command $cmd -TimeoutSeconds 60
        $backupPath = $null
        if ($cfgOut -match 'BACKUP=(\S+)') { $backupPath = $Matches[1] }
        Write-OneLinkLog "[$($server.Host)] $script:InnodbConfigFile updated (innodb_buffer_pool_size=$([int64]$nearest)). Backup: $backupPath" -Level Info

        $mysql = Resolve-OneLinkMysql -Server $server
        try {
            Invoke-OneLinkDatabaseServiceAction -Session $server.Session -Unit $mysql.Unit -Action 'Restart' -TimeoutSeconds ([Math]::Max([int]$script:Settings.Ssh.CommandTimeoutSeconds, 120))
        }
        catch {
            # Mirror the nmenu script's rollback: if MySQL fails to come back up
            # with the new setting, restore the previous config and retry the start.
            if ($backupPath) {
                $restoreTmpl = @'
set -e
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH
sudo cp __BACKUPQ__ __CFGQ__
if [ "$(id -u)" = 0 ]; then systemctl start __UNITQ__; else sudo -n systemctl start __UNITQ__; fi
'@
                $restoreCmd = $restoreTmpl.Replace('__BACKUPQ__', (ConvertTo-OneLinkBashArg $backupPath)).Replace('__CFGQ__', $cfgArg).Replace('__UNITQ__', (ConvertTo-OneLinkBashArg $mysql.Unit))
                try { Invoke-OneLinkDatabaseCommand -Session $server.Session -Command $restoreCmd -TimeoutSeconds 60 | Out-Null } catch { }
            }
            throw "MySQL failed to restart with the new innodb_buffer_pool_size. The previous configuration was restored from $backupPath. $($_.Exception.Message)"
        }

        $after = Get-OneLinkInnodbStatus -Session $server.Session
        $script:InnodbMaxBytes = $after.MaxBytesSafe
        $TxtInnodbInfo.Text =
            "Current innodb_buffer_pool_size: $(Format-OneLinkInnodbSize $after.CurrentBytes)" + [Environment]::NewLine +
            "Total RAM: $(Format-OneLinkInnodbSize $after.TotalBytes)   |   Available RAM: $(Format-OneLinkInnodbSize $after.AvailBytes)" + [Environment]::NewLine +
            "Recommended maximum (75% of Total RAM): $(Format-OneLinkInnodbSize $after.MaxBytesSafe)"
        Update-OneLinkInnodbWarning
        Set-OneLinkMysqlStatusBox -State 'Running' -Unit $mysql.Unit

        $outcome = 'Success'
        Write-OneLinkLog "[$($server.Host)] innodb_buffer_pool_size set to $(Format-OneLinkInnodbSize $after.CurrentBytes) and MySQL restarted." -Level Success
        Write-OneLinkEfficiency -Operation 'InnoDB Buffer Pool' -Target ([string]$server.Host) -Outcome 'Success' -Start $start -End (Get-Date)
    }
    catch {
        Write-OneLinkEfficiency -Operation 'InnoDB Buffer Pool' -Target ([string]$server.Host) -Outcome 'Failed' -Start $start -End (Get-Date)
        Show-ErrorMessage "InnoDB buffer pool change failed on $($server.Host). $($_.Exception.Message)"
    }
    finally {
        $script:Window.Cursor = [Windows.Input.Cursors]::Arrow
        Complete-OneLinkActivity -Name 'InnoDB Buffer Pool' -Target ([string]$server.Host) -Outcome $outcome -OperationSeconds (((Get-Date) - $start).TotalSeconds)
    }
}

$BtnInnodbCheck.Add_Click({ Invoke-OneLinkInnodbCheck })
$BtnInnodbApply.Add_Click({ Invoke-OneLinkInnodbApply })

# ============================================================================
#  Run SQL Script (Database tab) - mirrors nmenu's ndb_run <file>: run an
#  existing .sql file (already on the target server) through the MySQL root
#  socket. Adds a search-by-name step across the whole server (nmenu's own
#  file picker only browsed $HOME) and a dedicated progress popup.
# ============================================================================

$script:SqlRunState = @{ Job = $null }   # single-flight guard; a hashtable so a
                                          # GetNewClosure timer tick can safely
                                          # clear it (see the Watch-OneLinkBgJob
                                          # GOTCHA comment above for why a plain
                                          # $script:var would NOT work here).

# Search the ENTIRE target server for .sql files whose name contains $Term
# (case-insensitive), skipping virtual filesystems for speed/safety.
function Invoke-OneLinkSqlScriptSearch {
    $server = Get-OneLinkDbTargetServer
    if ($null -eq $server) { return }
    $term = $TxtSqlSearchTerm.Text.Trim()
    if ([string]::IsNullOrWhiteSpace($term)) { Show-ErrorMessage "Type part of the script name to search for (e.g. 'test')."; return }

    $script:Window.Cursor = [Windows.Input.Cursors]::Wait
    $CmbSqlScriptFound.Items.Clear()
    $TxtSqlSearchStatus.Text = "Searching $($server.Host) for '*$term*.sql' - this can take a moment on a large disk..."
    $TxtSqlSearchStatus.Foreground = $script:Window.FindResource('MutedTextBrush')
    try {
        $termArg = ConvertTo-OneLinkBashArg $term
        $tmpl = @'
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH
T=__TERMQ__
PATTERN="*$T*.sql"
run_find() { if [ "$(id -u)" = 0 ]; then find "$@"; else sudo -n find "$@" 2>/dev/null || find "$@"; fi; }
run_find / \( -path /proc -o -path /sys -o -path /dev -o -path /run -o -path /snap \) -prune -o -type f -iname "$PATTERN" -print 2>/dev/null | sort -u | head -n 200
'@
        $cmd = $tmpl.Replace('__TERMQ__', $termArg)
        $out = Invoke-OneLinkDatabaseCommand -Session $server.Session -Command $cmd -TimeoutSeconds 150
        $paths = @($out -split "`r?`n" | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '' })
        foreach ($p in $paths) { [void]$CmbSqlScriptFound.Items.Add($p) }
        if ($paths.Count -eq 0) {
            $TxtSqlSearchStatus.Text = "No .sql files matching '$term' were found on $($server.Host)."
            $TxtSqlSearchStatus.Foreground = $script:Window.FindResource('WarningBrush')
        }
        else {
            $CmbSqlScriptFound.SelectedIndex = 0
            $TxtSqlSearchStatus.Text = "Found $($paths.Count) script(s) matching '$term' on $($server.Host)."
            $TxtSqlSearchStatus.Foreground = $script:Window.FindResource('SuccessBrush')
        }
        Write-OneLinkLog "[$($server.Host)] SQL script search for '$term': $($paths.Count) match(es)." -Level Info
    }
    catch {
        $TxtSqlSearchStatus.Text = "Search failed: $($_.Exception.Message)"
        $TxtSqlSearchStatus.Foreground = $script:Window.FindResource('DangerBrush')
        Show-ErrorMessage "Could not search for SQL scripts on $($server.Host). $($_.Exception.Message)"
    }
    finally { $script:Window.Cursor = [Windows.Input.Cursors]::Arrow }
}
$BtnSqlSearch.Add_Click({ Invoke-OneLinkSqlScriptSearch })

# Translate a raw MySQL/SSH failure into a short, human-readable explanation.
# The full raw output is always shown too, underneath this summary line.
function Get-OneLinkSqlErrorHint {
    param([string]$RawOutput, [string]$ExceptionMessage)
    $text = if (-not [string]::IsNullOrWhiteSpace($RawOutput)) { $RawOutput } else { $ExceptionMessage }
    if ([string]::IsNullOrWhiteSpace($text)) { return 'The script failed for an unknown reason (no output was returned).' }

    switch -Regex ($text) {
        'ERROR 1045'                                    { return "Access denied - the database rejected the connection (the MySQL root socket login is not working)." }
        'ERROR 1049'                                     { return "Unknown database - the script references a database that does not exist on this server. Check any USE/database name in the script." }
        'ERROR 1050'                                     { return "Table already exists - the script tried to CREATE a table that is already there." }
        'ERROR 1051|ERROR 1146'                          { return "Unknown table - the script references a table that does not exist. Check the table name and that the right database is selected." }
        'ERROR 1054'                                     { return "Unknown column - the script references a column that does not exist in the table." }
        'ERROR 1062'                                     { return "Duplicate entry - the script tried to insert a row that violates a UNIQUE/PRIMARY KEY constraint." }
        'ERROR 1064'                                      { return "SQL syntax error - there is a mistake in the script's SQL near the point MySQL reported. Check the exact line in the script." }
        'ERROR 1136'                                     { return "Column count mismatch - an INSERT statement supplies a different number of values than the table has columns." }
        'ERROR 1142|ERROR 1044|Access denied for user'   { return "Permission denied - the database account does not have the privilege needed for this statement." }
        'ERROR 1215|ERROR 1452'                          { return "Foreign key constraint failed - the script's data violates a foreign key relationship (e.g. inserting a child row before its parent)." }
        'ERROR 2002|Can''t connect'                      { return "Could not connect to MySQL - the database service may be stopped. Check MySQL status (Restart/Status buttons above) and try again." }
        'not found on the server'                        { return "The selected .sql file no longer exists on the server (it may have been moved or deleted after the search)." }
        'MySQL/MariaDB client is not installed'          { return "No MySQL/MariaDB client is installed on this server, so the script could not be run." }
        'a password is required|sudo:.*password'         { return "Passwordless sudo is not available for this account, so the command could not run as root. Reconnect the server (the tool tries to configure this automatically) or grant sudo." }
        default                                           { return "The script did not complete successfully. See the full output below for MySQL's exact error." }
    }
}

# Self-contained worker: run one .sql file already on the target server.
$script:SqlRunWorker = {
    $ErrorActionPreference = 'Stop'
    . ([scriptblock]::Create($DatabaseFunctions))
    # Pre-set these BEFORE anything that could throw, so the watcher (which reads
    # them under this app's Set-StrictMode -Version Latest) never hits a missing
    # hashtable key - see the InnoDB Get-OneLinkInnodbStatus fix for the same class of bug.
    $sync.RawOutput = ''
    $sync.ExitStatus = $null
    $sess = $null
    try {
        if (($env:PSModulePath -split ';') -notcontains $ModulesRoot) { $env:PSModulePath = $ModulesRoot + ';' + $env:PSModulePath }
        Import-Module Posh-SSH -ErrorAction Stop
        $sec = ConvertTo-SecureString $SrvPass -AsPlainText -Force
        $cred = [pscredential]::new($SrvUser, $sec)
        $sync.Status = "Connecting to $SrvHost ..."
        $sess = New-SSHSession -ComputerName $SrvHost -Port $SrvPort -Credential $cred -AcceptKey -ErrorAction Stop

        $sync.Status = "Running $FilePath on $SrvHost (large scripts can take a while) ..."
        $wrapped = ConvertTo-OneLinkDatabaseCommand (New-OneLinkSqlScriptRunCommand -FilePath $FilePath)
        $r = Invoke-SSHCommand -SSHSession $sess -Command $wrapped -TimeOut $Timeout
        $sync.RawOutput = ((@($r.Output) + @($r.Error)) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join [Environment]::NewLine
        $sync.ExitStatus = $r.ExitStatus
        $sync.Ok = ($r.ExitStatus -eq 0)
        $sync.Message = if ($sync.Ok) { 'Script completed successfully.' } else { "Script exited with code $($r.ExitStatus)." }
    }
    catch {
        $sync.Ok = $false
        $sync.Message = $_.Exception.Message
    }
    finally {
        try { if ($sess) { Remove-SSHSession -SSHSession $sess -ErrorAction SilentlyContinue | Out-Null } } catch { }
        $sync.Done = $true
    }
}

# Build the non-modal "Run SQL Script" progress popup. Closing (X / Alt+F4) is
# blocked while the script is still running, same spirit as the other
# irreversible-operation confirms in this tool.
function Show-OneLinkSqlRunWindow {
    param([string]$ScriptPath, [string]$HostName)
    $win = New-Object System.Windows.Window
    $win.Title = 'Run SQL Script'
    $win.Width = 760; $win.Height = 520
    $win.MinWidth = 480; $win.MinHeight = 320
    $win.WindowStartupLocation = 'CenterScreen'
    $win.Background = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#F5F7FB'))
    if ($script:Window) { $win.Owner = $script:Window }

    $grid = New-Object System.Windows.Controls.Grid
    foreach ($h in @('Auto', 'Auto', '*', 'Auto')) {
        $rd = New-Object System.Windows.Controls.RowDefinition
        $rd.Height = [System.Windows.GridLength]::new(1, $(if ($h -eq '*') { 'Star' } else { 'Auto' }))
        [void]$grid.RowDefinitions.Add($rd)
    }

    $hdr = New-Object System.Windows.Controls.Border
    $hdr.Background = New-OneLinkHeaderBrush
    $hdr.Padding = '16,11'
    $htxt = New-Object System.Windows.Controls.TextBlock
    $htxt.Text = 'Run SQL Script'; $htxt.Foreground = [System.Windows.Media.Brushes]::White; $htxt.FontSize = 15; $htxt.FontWeight = 'Bold'
    $hdr.Child = $htxt
    [System.Windows.Controls.Grid]::SetRow($hdr, 0); [void]$grid.Children.Add($hdr)

    $sub = New-Object System.Windows.Controls.TextBlock
    $sub.Text = "$ScriptPath  ->  $HostName"
    $sub.Margin = '14,10,14,0'; $sub.FontSize = 12; $sub.Foreground = [System.Windows.Media.Brushes]::Gray; $sub.TextWrapping = 'Wrap'
    [System.Windows.Controls.Grid]::SetRow($sub, 1); [void]$grid.Children.Add($sub)

    $card = New-Object System.Windows.Controls.Border
    $card.Background = [System.Windows.Media.Brushes]::White
    $card.BorderBrush = New-Object System.Windows.Media.SolidColorBrush ([System.Windows.Media.ColorConverter]::ConvertFromString('#E2E8F0'))
    $card.BorderThickness = New-Object System.Windows.Thickness(1)
    $card.CornerRadius = New-Object System.Windows.CornerRadius(8)
    $card.Margin = '14,10,14,6'
    $tb = New-Object System.Windows.Controls.TextBox
    $tb.Text = 'Waiting for the script to start...'
    $tb.IsReadOnly = $true; $tb.AcceptsReturn = $true
    $tb.FontFamily = New-Object System.Windows.Media.FontFamily('Consolas, Courier New, monospace')
    $tb.FontSize = 13; $tb.TextWrapping = 'NoWrap'
    $tb.VerticalScrollBarVisibility = 'Auto'; $tb.HorizontalScrollBarVisibility = 'Auto'
    $tb.BorderThickness = New-Object System.Windows.Thickness(0)
    $tb.Padding = '14,12'; $tb.Background = [System.Windows.Media.Brushes]::White
    $card.Child = $tb
    [System.Windows.Controls.Grid]::SetRow($card, 2); [void]$grid.Children.Add($card)

    $footer = New-Object System.Windows.Controls.Grid
    $c0 = New-Object System.Windows.Controls.ColumnDefinition; $c0.Width = '*'
    $c1 = New-Object System.Windows.Controls.ColumnDefinition; $c1.Width = 'Auto'
    [void]$footer.ColumnDefinitions.Add($c0); [void]$footer.ColumnDefinitions.Add($c1)
    $footer.Margin = '14,0,14,12'

    $status = New-Object System.Windows.Controls.TextBlock
    $status.Text = 'Status: Starting...'; $status.FontWeight = 'Bold'; $status.VerticalAlignment = 'Center'
    $status.Foreground = Get-OneLinkStyle 'WarningBrush'
    [System.Windows.Controls.Grid]::SetColumn($status, 0); [void]$footer.Children.Add($status)

    $close = New-Object System.Windows.Controls.Button
    $close.Content = 'Close'; $close.Width = 100; $close.Height = 30; $close.IsEnabled = $false
    $primaryStyle = Get-OneLinkStyle 'PrimaryButtonStyle'
    if ($primaryStyle) { $close.Style = $primaryStyle }
    [System.Windows.Controls.Grid]::SetColumn($close, 1); [void]$footer.Children.Add($close)
    [System.Windows.Controls.Grid]::SetRow($footer, 3); [void]$grid.Children.Add($footer)

    $win.Content = $grid

    $running = @{ Value = $true }
    $win.Add_Closing({
        param($closingSender, $closingArgs)
        if ($running.Value) {
            $closingArgs.Cancel = $true
            [System.Windows.MessageBox]::Show('The script is still running. Please wait for it to finish.', 'Run SQL Script', 'OK', 'Information') | Out-Null
        }
    }.GetNewClosure())
    $close.Add_Click({ $running.Value = $false; $win.Close() }.GetNewClosure())

    $win.Show()
    return [pscustomobject]@{ Window = $win; Output = $tb; Status = $status; Close = $close; Running = $running }
}

# Poll the SQL-run background job on the UI thread; update the popup, and
# report a human-friendly result when it finishes.
function Watch-OneLinkSqlRunJob {
    param($Ctx, $Popup, $RunButton, [string]$TargetHost, [string]$ScriptPath)
    $state = $script:SqlRunState
    $state.Job = $Ctx
    $startTime = Get-Date
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(500)
    $tick = {
        if ($Ctx.Sync.Done -or $Ctx.Handle.IsCompleted) {
            $timer.Stop()
            $state.Job = $null
            $RunButton.IsEnabled = $true
            try { $Ctx.PS.EndInvoke($Ctx.Handle) } catch { }
            try { $Ctx.PS.Dispose() } catch { }
            try { $Ctx.Runspace.Dispose() } catch { }
            if (-not $Ctx.Sync.Done) {
                $Ctx.Sync.Ok = $false
                if ([string]::IsNullOrWhiteSpace([string]$Ctx.Sync.Message)) { $Ctx.Sync.Message = 'Stopped unexpectedly.' }
            }
            $ok = [bool]$Ctx.Sync.Ok
            $raw = [string]$Ctx.Sync.RawOutput
            $elapsed = ((Get-Date) - $startTime).TotalSeconds
            if ($ok) {
                $Popup.Status.Text = 'Status: Completed successfully.'
                $Popup.Status.Foreground = Get-OneLinkStyle 'SuccessBrush'
                $Popup.Output.Text = if ([string]::IsNullOrWhiteSpace($raw)) { '(The script ran successfully and produced no output.)' } else { $raw }
                Write-OneLinkLog "[$TargetHost] SQL script '$ScriptPath' completed successfully." -Level Success
            }
            else {
                $hint = Get-OneLinkSqlErrorHint -RawOutput $raw -ExceptionMessage ([string]$Ctx.Sync.Message)
                $Popup.Status.Text = 'Status: FAILED.'
                $Popup.Status.Foreground = Get-OneLinkStyle 'DangerBrush'
                $bodyText = $hint
                if (-not [string]::IsNullOrWhiteSpace($raw)) { $bodyText += [Environment]::NewLine + [Environment]::NewLine + '--- Full output ---' + [Environment]::NewLine + $raw }
                $Popup.Output.Text = $bodyText
                Write-OneLinkLog "[$TargetHost] SQL script '$ScriptPath' failed: $hint" -Level Error
            }
            $Popup.Running.Value = $false
            $Popup.Close.IsEnabled = $true
            Write-OneLinkEfficiency -Operation 'Run SQL Script' -Target $TargetHost -Outcome ($(if ($ok) { 'Success' } else { 'Failed' })) -Start $startTime -End (Get-Date)
            Complete-OneLinkActivity -Name 'Run SQL Script' -Target $TargetHost -Outcome ($(if ($ok) { 'Success' } else { 'Failed' })) -OperationSeconds $elapsed
        }
        else {
            $Popup.Output.Text = [string]$Ctx.Sync.Status
        }
    }.GetNewClosure()
    $timer.Add_Tick($tick)
    $timer.Start()
}

function Invoke-OneLinkSqlScriptRun {
    if ($script:SqlRunState.Job) { Show-ErrorMessage "A SQL script is already running. Wait for it to finish."; return }
    $server = Get-OneLinkDbTargetServer
    if ($null -eq $server) { return }
    $path = Get-ComboText $CmbSqlScriptFound
    if ([string]::IsNullOrWhiteSpace($path)) { Show-ErrorMessage "Search for and select a .sql script to run first."; return }

    $ans = [System.Windows.MessageBox]::Show(
        "This will run the SQL script:`n$path`n`non $($server.Host), against its live database." +
        "`n`nThis can change or delete data and CANNOT be undone automatically. Proceed?",
        'Run SQL Script', 'YesNo', 'Warning', [System.Windows.MessageBoxResult]::No)
    if ($ans -ne 'Yes') { Write-OneLinkLog "[$($server.Host)] Run SQL script cancelled ($path)." -Level Info; return }

    $popup = Show-OneLinkSqlRunWindow -ScriptPath $path -HostName ([string]$server.Host)
    $BtnRunSqlScript.IsEnabled = $false

    $vars = @{
        SrvHost = [string]$server.Host; SrvPort = [int]$server.Port
        SrvUser = $server.Credential.UserName; SrvPass = $server.Credential.GetNetworkCredential().Password
        FilePath = $path; Timeout = [Math]::Max([int]$script:Settings.Ssh.CommandTimeoutSeconds, 1800)
        DatabaseFunctions = Get-OneLinkDatabaseWorkerFunctions
        ModulesRoot = (Join-Path $env:LOCALAPPDATA 'OneLinkAdminTool\Modules')
    }
    $ctx = Start-OneLinkBgJob -Script $script:SqlRunWorker -Vars $vars
    Write-OneLinkLog "[$($server.Host)] Running SQL script: $path" -Level Info
    Watch-OneLinkSqlRunJob -Ctx $ctx -Popup $popup -RunButton $BtnRunSqlScript -TargetHost ([string]$server.Host) -ScriptPath $path
}
$BtnRunSqlScript.Add_Click({ Invoke-OneLinkSqlScriptRun })

# Rebuild the "Allowed IP" dropdown choices from the DB target selection:
# % (any host), localhost (local-only), and each selected target's own IP.
# Called by the Db picker's change handler (see Update-OneLinkTargetPicker).
function Update-OneLinkDbAllowedIp {
    $cur = $CmbDbUserIp.Text
    $CmbDbUserIp.Items.Clear()
    [void]$CmbDbUserIp.Items.Add('%')
    [void]$CmbDbUserIp.Items.Add('localhost')
    foreach ($s in @(Get-OneLinkTargetHosts -Key 'Db')) {
        $tgt = [string]$s.Host
        if ($tgt -match '^\d{1,3}(\.\d{1,3}){3}$' -and $CmbDbUserIp.Items -notcontains $tgt) { [void]$CmbDbUserIp.Items.Add($tgt) }
    }
    $CmbDbUserIp.Text = $cur
}

# Allowed IP is LOCKED by default (uses the % default). The user must tick the
# checkbox to set a specific host; unticking it resets to the default (blank -> %).
$ChkSetAllowedIp.Add_Click({
    $CmbDbUserIp.IsEnabled = [bool]$ChkSetAllowedIp.IsChecked
    if (-not $ChkSetAllowedIp.IsChecked) { $CmbDbUserIp.Text = '' }
})

$BtnCreateDbUser.Add_Click({
    try {
        if ([string]::IsNullOrWhiteSpace($TxtDbUser.Text)) { throw "Database username is required." }
        if ($PwdDbUser.Password.Length -eq 0) { throw "Database password is required." }
        if ($PwdDbUser.Password -ne $PwdDbUserConfirm.Password) { throw "The password and re-typed password do not match." }
    }
    catch {
        Show-ErrorMessage $_.Exception.Message
        return
    }

    # Allowed IP only applies when the user ticked the checkbox; otherwise use the
    # default (blank -> '%').
    $allowedIp = if ($ChkSetAllowedIp.IsChecked) { $CmbDbUserIp.Text } else { '' }

    Invoke-MultiServerOperation -Name 'Create DB User' -TargetServers (Get-OneLinkTargetHosts -Key 'Db') -PerServerAction {
        param($server)
        # Blank Allowed IP -> '%' (any host, incl. the local socket) so the
        # account works as 'user'@'%' and `mysql -u user -p` connects locally.
        $out = Invoke-OneLinkCreateDatabaseUser `
            -Session $server.Session `
            -Settings $script:Settings `
            -Username $TxtDbUser.Text `
            -Password $PwdDbUser.Password `
            -AllowedIp $allowedIp
        Write-OneLinkLog "[$($server.Host)] $out" -Level Info
    }
})

$BtnCreateDatabase.Add_Click({
    if ([string]::IsNullOrWhiteSpace($TxtDatabaseName.Text)) { Show-ErrorMessage "Database name is required."; return }
    $dbName = $TxtDatabaseName.Text.Trim()

    # CREATE DATABASE IF NOT EXISTS is evaluated independently on every target.
    Invoke-MultiServerOperation -Name 'Create Database' -TargetServers (Get-OneLinkTargetHosts -Key 'Db') -PerServerAction {
        param($server)
        $out = Invoke-OneLinkCreateDatabase `
            -Session $server.Session `
            -Settings $script:Settings `
            -DatabaseName $TxtDatabaseName.Text.Trim()
        Write-OneLinkLog "[$($server.Host)] $out" -Level Info
    }
})

# Load the user and database lists from the selected target's MySQL.
$BtnRefreshDbLists.Add_Click({
    $srv = Get-OneLinkDbTargetServer
    if ($null -eq $srv) { return }
    $script:Window.Cursor = [Windows.Input.Cursors]::Wait
    try {
        $users = Invoke-OneLinkMysqlQuery -Session $srv.Session -Sql "SELECT DISTINCT User FROM mysql.user WHERE User <> '' ORDER BY User"
        $accountHosts = @(Invoke-OneLinkMysqlQuery -Session $srv.Session -Sql 'SELECT DISTINCT Host FROM mysql.user ORDER BY Host')
        $h = $CmbGrantHost.Text; $CmbGrantHost.Items.Clear(); foreach ($x in $accountHosts) { [void]$CmbGrantHost.Items.Add($x) }; $CmbGrantHost.Text = $h
        $dbs   = Invoke-OneLinkMysqlQuery -Session $srv.Session -Sql "SHOW DATABASES"
        $sys = @('information_schema', 'performance_schema', 'mysql', 'sys')
        $dbs = @($dbs | Where-Object { $sys -notcontains $_ })
        # Hide root and MySQL's internal system accounts for safety - the user
        # must not be able to pick them for a grant.
        $sysUsers = @('root', 'mysql.sys', 'mysql.session', 'mysql.infoschema', 'debian-sys-maint', 'mariadb.sys')
        $users = @($users | Where-Object { $sysUsers -notcontains $_ })

        $u = $CmbGrantUser.Text; $CmbGrantUser.Items.Clear(); foreach ($x in $users) { [void]$CmbGrantUser.Items.Add($x) }; $CmbGrantUser.Text = $u
        $d = $CmbGrantDb.Text;   $CmbGrantDb.Items.Clear();   foreach ($x in $dbs)   { [void]$CmbGrantDb.Items.Add($x) };   $CmbGrantDb.Text = $d
        $be = $CmbExportDb.Text; $CmbExportDb.Items.Clear();  foreach ($x in $dbs)   { [void]$CmbExportDb.Items.Add($x) };  $CmbExportDb.Text = $be
        $bi = $CmbImportDb.Text; $CmbImportDb.Items.Clear();  foreach ($x in $dbs)   { [void]$CmbImportDb.Items.Add($x) };  $CmbImportDb.Text = $bi
        Write-OneLinkLog "[$($srv.Host)] Loaded $($users.Count) MySQL user(s) and $($dbs.Count) database(s)." -Level Success
    }
    catch {
        Show-ErrorMessage "Could not load users/databases from $($srv.Host). $($_.Exception.Message)"
    }
    finally { $script:Window.Cursor = [Windows.Input.Cursors]::Arrow }
})

$BtnGrantPrivileges.Add_Click({
    if ([string]::IsNullOrWhiteSpace($CmbGrantUser.Text)) { Show-ErrorMessage "Select or type a user to grant."; return }
    if ([string]::IsNullOrWhiteSpace($CmbGrantDb.Text)) { Show-ErrorMessage "Select or type a database to grant on."; return }
    # Optional password: if one is entered, the re-typed value must match (a
    # wrong password would overwrite the user's real password).
    if ($PwdGrant.Password -ne $PwdGrantConfirm.Password) { Show-ErrorMessage "The optional password and its re-typed value do not match."; return }

    Invoke-MultiServerOperation -Name 'Grant Admin Privileges' -TargetServers (Get-OneLinkTargetHosts -Key 'Db') -PerServerAction {
        param($server)
        # Grant to the exact user/host account; a blank password leaves it unchanged.
        $out = Invoke-OneLinkGrantPrivileges `
            -Session $server.Session `
            -Settings $script:Settings `
            -Username $CmbGrantUser.Text.Trim() `
            -AllowedIp $CmbGrantHost.Text.Trim() `
            -DatabaseName $CmbGrantDb.Text.Trim() `
            -Password $PwdGrant.Password
        Write-OneLinkLog "[$($server.Host)] $out" -Level Info
    }
})

# Browse for a LOCAL Windows backup file (only relevant to the 'Local Windows' location).
# MAXIMUM time (seconds) a backup/restore SSH command is ALLOWED to run before the
# tool gives up - it is a ceiling, NOT a fixed wait: the command returns the instant
# it finishes. Default 129600 = 36 hours (1.5 days) for very large dumps; override
# via Settings.json -> Database.BackupTimeoutSeconds.
$script:BackupTimeoutSeconds = 129600
try { if ($script:Settings.Database -and $script:Settings.Database.BackupTimeoutSeconds) { $script:BackupTimeoutSeconds = [int]$script:Settings.Database.BackupTimeoutSeconds } } catch { }

# Last path segment, treating both / and \ as separators (Linux or Windows/UNC).
function Get-OneLinkPathLeaf { param([string]$Path) return (($Path -split '[\\/]') | Where-Object { $_ -ne '' } | Select-Object -Last 1) }

# --- Backup (Export) file picker + destination toggles ---
$BtnBrowseExport.Add_Click({
    if ((Get-ComboText $CmbExportDest) -notlike 'Local*') {
        Show-InfoMessage "Browse is for 'Local Windows' files. For 'Server' type a Linux path; for 'Network location' type a UNC path (e.g. \\server\share\db.sql.gz)."
        return
    }
    $dlg = New-Object System.Windows.Forms.OpenFileDialog
    $dlg.Filter = 'SQL backups (*.sql;*.gz;*.zip)|*.sql;*.gz;*.zip|All files (*.*)|*.*'
    $dlg.CheckFileExists = $false   # naming a NEW file for the backup
    $dlg.Title = 'Name the backup file on this PC'
    try { if (-not [string]::IsNullOrWhiteSpace($TxtExportFile.Text)) { $dlg.InitialDirectory = [IO.Path]::GetDirectoryName($TxtExportFile.Text); $dlg.FileName = [IO.Path]::GetFileName($TxtExportFile.Text) } } catch { }
    if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $TxtExportFile.Text = $dlg.FileName }
})

$CmbExportDest.Add_SelectionChanged({
    $loc = Get-ComboText $CmbExportDest
    $ExportNetRow.Visibility = if ($loc -like 'Network*') { 'Visible' } else { 'Collapsed' }
    if ($loc -like 'Local*' -and $TxtExportFile.Text -match '^/') { $TxtExportFile.Text = (Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'onelink_db_export.sql.gz') }
    elseif ($loc -like 'Network*' -and $TxtExportFile.Text -notmatch '^\\\\') { $TxtExportFile.Text = '\\server\share\onelink_db_export.sql.gz' }
    elseif ($loc -like 'Server*' -and $TxtExportFile.Text -notmatch '^/') { $TxtExportFile.Text = '/mysqldata/ndb_export.sql.gz' }
})

# --- Restore (Import) file picker + source toggles ---
$BtnBrowseImport.Add_Click({
    if ((Get-ComboText $CmbImportSrc) -notlike 'Local*') {
        Show-InfoMessage "Browse is for 'Local Windows' files. For 'Server' / 'Another VM' type a Linux path; for 'Network location' type a UNC path."
        return
    }
    $dlg = New-Object System.Windows.Forms.OpenFileDialog
    $dlg.Filter = 'SQL backups (*.sql;*.gz;*.zip)|*.sql;*.gz;*.zip|All files (*.*)|*.*'
    $dlg.CheckFileExists = $true    # the backup to restore must exist
    $dlg.Title = 'Select the backup file on this PC'
    try { if (-not [string]::IsNullOrWhiteSpace($TxtImportFile.Text)) { $dlg.InitialDirectory = [IO.Path]::GetDirectoryName($TxtImportFile.Text); $dlg.FileName = [IO.Path]::GetFileName($TxtImportFile.Text) } } catch { }
    if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $TxtImportFile.Text = $dlg.FileName }
})

$CmbImportSrc.Add_SelectionChanged({
    $loc = Get-ComboText $CmbImportSrc
    $ImportNetRow.Visibility = if ($loc -like 'Network*') { 'Visible' } else { 'Collapsed' }
    $ImportVmRow.Visibility  = if ($loc -like 'Another VM*') { 'Visible' } else { 'Collapsed' }
    if ($loc -like 'Local*' -and $TxtImportFile.Text -match '^/') { $TxtImportFile.Text = (Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'onelink_db_export.sql.gz') }
    elseif ($loc -like 'Network*' -and $TxtImportFile.Text -notmatch '^\\\\') { $TxtImportFile.Text = '\\server\share\onelink_db_export.sql.gz' }
    elseif (($loc -like 'Server*' -or $loc -like 'Another VM*') -and $TxtImportFile.Text -notmatch '^/') { $TxtImportFile.Text = '/mysqldata/ndb_export.sql.gz' }
})

# ---------------------------------------------------------------------------
#  Background job infrastructure for long DB backup/restore (keeps the UI
#  responsive and lets the user Stop a running operation).
# ---------------------------------------------------------------------------
# The single in-flight backup/restore context, held INSIDE a hashtable. This is
# deliberate: the completion runs in a DispatcherTimer tick built with
# .GetNewClosure(), and inside such a closure `$script:X = ...` writes to the
# closure's own module scope - it does NOT clear the real script variable. So a
# plain `$script:BgJob = $null` in the tick never cleared the flag ("a
# backup/restore is already running" on the 2nd export). Mutating a CAPTURED
# hashtable's member does reach the real object, so we clear via $state.Job.
$script:BgState = @{ Job = $null }

# Run a SELF-CONTAINED scriptblock in a background runspace. It receives $sync
# (a synchronized state bag) plus every entry of $Vars as a variable.
function Start-OneLinkBgJob {
    param([scriptblock]$Script, [hashtable]$Vars)
    $sync = [hashtable]::Synchronized(@{ Cancel = $false; Status = 'Starting...'; Done = $false; Ok = $false; Message = ''; Client = $null; StopInfo = $null })
    $rs = [runspacefactory]::CreateRunspace()
    $rs.ApartmentState = 'STA'
    $rs.ThreadOptions = 'ReuseThread'
    $rs.Open()
    $rs.SessionStateProxy.SetVariable('sync', $sync)
    foreach ($k in $Vars.Keys) { $rs.SessionStateProxy.SetVariable($k, $Vars[$k]) }
    $ps = [powershell]::Create()
    $ps.Runspace = $rs
    [void]$ps.AddScript($Script)
    $handle = $ps.BeginInvoke()
    return [pscustomobject]@{ Sync = $sync; PS = $ps; Runspace = $rs; Handle = $handle }
}

# Poll a background job on the UI thread; update status, and report on completion.
function Watch-OneLinkBgJob {
    param($Ctx, $StatusCtrl, $RunButton, $StopButton, [string]$OpName, [string]$TargetHost)
    $RunButton.IsEnabled = $false
    $StopButton.IsEnabled = $true
    $state = $script:BgState   # local reference to the shared hashtable; GetNewClosure captures it
    $state.Job = $Ctx
    $startTime = Get-Date
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(500)
    $tick = {
        $StatusCtrl.Text = [string]$Ctx.Sync.Status
        # Finish when the worker signals Done OR when the runspace pipeline has
        # actually completed. The second check is the safety net: a hard Stop
        # (BeginStop) or a worker crash can abort the thread BEFORE its
        # finally{ $sync.Done = $true } runs, which used to leave $script:BgJob
        # stuck non-null forever ("a backup/restore is already running" with
        # nothing running). Handle.IsCompleted flips true even in that case.
        if ($Ctx.Sync.Done -or $Ctx.Handle.IsCompleted) {
            $timer.Stop()
            # Clear the guard and reset buttons FIRST, before any call that could
            # throw, so the tool can never wedge in the "busy" state. $state is the
            # captured shared hashtable - mutating .Job here DOES reach the real
            # $script:BgState (unlike `$script:BgJob = $null`, which a GetNewClosure
            # would write to its own module scope).
            $state.Job = $null
            $RunButton.IsEnabled = $true
            $StopButton.IsEnabled = $false
            try { $Ctx.PS.EndInvoke($Ctx.Handle) } catch { }
            try { $Ctx.PS.Dispose() } catch { }
            try { $Ctx.Runspace.Dispose() } catch { }
            # If the pipeline ended without the worker setting Done, it was killed
            # before it could record a result - treat that as stopped/failed.
            if (-not $Ctx.Sync.Done) {
                $Ctx.Sync.Ok = $false
                if ([string]::IsNullOrWhiteSpace([string]$Ctx.Sync.Message)) { $Ctx.Sync.Message = 'Stopped.' }
            }
            Complete-OneLinkActivity -Name $OpName -Target $TargetHost -Outcome ($(if ($Ctx.Sync.Ok) { 'Success' } else { 'Failed' })) -OperationSeconds (((Get-Date) - $startTime).TotalSeconds)
            if ($Ctx.Sync.Ok) {
                $StatusCtrl.Text = "Done. " + [string]$Ctx.Sync.Message
                Write-OneLinkLog "[$TargetHost] $OpName : $($Ctx.Sync.Message)" -Level Success
                Write-OneLinkEfficiency -Operation $OpName -Target $TargetHost -Outcome 'Success' -Start $startTime -End (Get-Date)
                Show-InfoMessage "$OpName completed.`n`n$($Ctx.Sync.Message)"
            }
            else {
                $StatusCtrl.Text = "Stopped/failed. " + [string]$Ctx.Sync.Message
                Write-OneLinkLog "[$TargetHost] $OpName : $($Ctx.Sync.Message)" -Level Error
                Write-OneLinkEfficiency -Operation $OpName -Target $TargetHost -Outcome 'Failed' -Start $startTime -End (Get-Date)
                Show-WarningMessage "$OpName did not complete.`n`n$($Ctx.Sync.Message)"
            }
        }
    }.GetNewClosure()
    $timer.Add_Tick($tick)
    $timer.Start()
}

# Stop a running job: flag cancel, kill the server-side dump/restore, drop the
# worker's SSH client, and stop the runspace pipeline.
function Stop-OneLinkBgJob {
    param($Ctx)
    if ($null -eq $Ctx) { return }
    $Ctx.Sync.Cancel = $true
    $Ctx.Sync.Status = 'Stopping (killing server-side job and aborting transfer)...'
    $si = $Ctx.Sync.StopInfo
    if ($si) {
        try {
            Import-OneLinkPoshSsh
            $sec = ConvertTo-SecureString $si.Pass -AsPlainText -Force
            $cr = [pscredential]::new($si.User, $sec)
            $s2 = New-SSHSession -ComputerName $si.Host -Port $si.Port -Credential $cr -AcceptKey -ConnectionTimeout 15 -ErrorAction Stop
            if ($si.JobId -notmatch '^[a-f0-9]{32}$') { throw 'Invalid database job identity.' }
            $stopScript = @'
d=__DIR__
if [ -r "$d/pid" ]; then
    read -r pid < "$d/pid"
    case "$pid" in ''|*[!0-9]*) exit 1;; esac
    if [ -r "/proc/$pid/cmdline" ] && tr '\0' ' ' < "/proc/$pid/cmdline" | grep -F -- "$d" >/dev/null; then
        if [ "$(id -u)" = 0 ]; then kill -TERM -- "-$pid"; else sudo -n kill -TERM -- "-$pid"; fi
    fi
fi
'@
            $stopScript = $stopScript.Replace('__DIR__', (ConvertTo-OneLinkBashArg ('/tmp/onelink-db-' + $si.JobId)))
            Invoke-SSHCommand -SSHSession $s2 -Command (ConvertTo-OneLinkDatabaseCommand $stopScript) -TimeOut 25 | Out-Null
            Remove-SSHSession -SSHSession $s2 -ErrorAction SilentlyContinue | Out-Null
        }
        catch { }
    }
    try { if ($Ctx.Sync.Client) { $Ctx.Sync.Client.Disconnect() } } catch { }
    try { [void]$Ctx.PS.BeginStop($null, $null) } catch { }
}

# Self-contained worker: export a database to Server / Local / Network.
$script:ExportWorker = {
    $ErrorActionPreference = 'Stop'
    . ([scriptblock]::Create($DatabaseFunctions))
    function q($v) { "'" + ([string]$v -replace "'", "'\''") + "'" }
    $downloadDir = $null
    $sess = $null
    try {
        if (($env:PSModulePath -split ';') -notcontains $ModulesRoot) { $env:PSModulePath = $ModulesRoot + ';' + $env:PSModulePath }
        Import-Module Posh-SSH -ErrorAction Stop
        $pfx = 'PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH'
        $sec = ConvertTo-SecureString $SrvPass -AsPlainText -Force
        $cred = [pscredential]::new($SrvUser, $sec)
        $sync.Status = "Connecting to $SrvHost ..."
        $sess = New-SSHSession -ComputerName $SrvHost -Port $SrvPort -Credential $cred -AcceptKey -ErrorAction Stop
        $sync.Client = $sess.Session
        if ($sync.Cancel) { throw 'Stopped.' }

        if ($Loc -like 'Server*') {
            $sync.Status = "Exporting '$Db' on $SrvHost to $File (large DBs can take a long time) ..."
            $databaseCommand = New-OneLinkDatabaseExportCommand -DatabaseName $Db -FilePath $(if ($Loc -like 'Server*') { $File } else { $rtmp })
            $r = Invoke-SSHCommand -SSHSession $sess -Command (New-OneLinkDatabaseJobCommand -Command $databaseCommand -JobId $JobId) -TimeOut $Timeout
            if ($r.ExitStatus -ne 0) { throw ("Database command failed (exit {0}). {1}" -f $r.ExitStatus, ((@($r.Output) + @($r.Error)) -join " ")) }
            if ($sync.Cancel) { throw 'Stopped.' }
            $sync.Ok = $true; $sync.Message = "Exported '$Db' to $File on $SrvHost."
        }
        else {
            $base = (($File -split '[\\/]') | Where-Object { $_ -ne '' } | Select-Object -Last 1); if (-not $base) { $base = 'onelink_db_export.sql.gz' }
            $rtmp = "$UploadDir/olk_backup_$([guid]::NewGuid().ToString('N'))$(if ($File.EndsWith('.gz')) { '.sql.gz' } else { '.sql' })"
            $sync.Status = "Exporting '$Db' on $SrvHost (temp) ..."
            $databaseCommand = New-OneLinkDatabaseExportCommand -DatabaseName $Db -FilePath $(if ($Loc -like 'Server*') { $File } else { $rtmp })
            $r = Invoke-SSHCommand -SSHSession $sess -Command (New-OneLinkDatabaseJobCommand -Command $databaseCommand -JobId $JobId) -TimeOut $Timeout
            if ($r.ExitStatus -ne 0) { throw ("Database command failed (exit {0}). {1}" -f $r.ExitStatus, ((@($r.Output) + @($r.Error)) -join " ")) }
            if ($sync.Cancel) { throw 'Stopped.' }
            $chk = Invoke-SSHCommand -SSHSession $sess -Command ("test -f " + (q $rtmp) + " && echo OLK_HAVE || echo OLK_MISS") -TimeOut 20
            if (([string]$chk.Output) -notmatch 'OLK_HAVE') { throw ("Database export did not create '$rtmp' on $SrvHost. " + ((@($r.Output, $r.Error) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }) -join ' ').Trim()) }
            if ($Loc -like 'Network*') {
                $rootShare = if ($File -match '^(\\\\[^\\]+\\[^\\]+)') { $matches[1] } else { $File }
                if (-not [string]::IsNullOrWhiteSpace($NetUser)) { Invoke-OneLinkNetUse use $rootShare $NetPass "/user:$NetUser" | Out-Null }
                else { Invoke-OneLinkNetUse use $rootShare | Out-Null }
            }
            $destDir = [IO.Path]::GetDirectoryName($File)
            if (-not (Test-Path -LiteralPath $destDir)) { New-Item -ItemType Directory -Path $destDir -Force | Out-Null }
            $sync.Status = "Downloading backup to $File (large DBs can take a long time) ..."
            $downloadDir = Join-Path ([IO.Path]::GetTempPath()) ('olk_download_' + [guid]::NewGuid().ToString('N'))
            [void](New-Item -ItemType Directory -Path $downloadDir)
            Get-SCPItem -ComputerName $SrvHost -Port $SrvPort -Credential $cred -Path $rtmp -PathType File -Destination $downloadDir -AcceptKey -Force -ErrorAction Stop
            $downloaded = Join-Path $downloadDir (($rtmp -split '/')[-1])
            if ($sync.Cancel) { throw 'Stopped.' }
            Move-Item -LiteralPath $downloaded -Destination $File -Force
            if ($sync.Cancel) { throw 'Stopped.' }
            Invoke-SSHCommand -SSHSession $sess -Command ("sudo rm -f " + (q $rtmp) + " 2>/dev/null; true") -TimeOut 30 | Out-Null
            $sync.Ok = $true; $sync.Message = "Exported '$Db' from $SrvHost to $File."
        }
    }
    catch {
        if ($sync.Cancel) { $sync.Ok = $false; $sync.Message = 'Stopped by user.' }
        else { $sync.Ok = $false; $sync.Message = $_.Exception.Message }
    }
    finally {
        try { if ($sess) { Remove-SSHSession -SSHSession $sess -ErrorAction SilentlyContinue | Out-Null } } catch { }
        if ($downloadDir -and (Test-Path -LiteralPath $downloadDir)) {
            $resolved = [IO.Path]::GetFullPath($downloadDir)
            $tempRoot = [IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\') + '\'
            if ($resolved.StartsWith($tempRoot, [StringComparison]::OrdinalIgnoreCase) -and [IO.Path]::GetFileName($resolved) -like 'olk_download_*') { Remove-Item -LiteralPath $resolved -Recurse -Force -ErrorAction SilentlyContinue }
        }
        $sync.Done = $true
    }
}

# Self-contained worker: import a database from Server / Local / Network / Another VM.
$script:ImportWorker = {
    $ErrorActionPreference = 'Stop'
    . ([scriptblock]::Create($DatabaseFunctions))
    function q($v) { "'" + ([string]$v -replace "'", "'\''") + "'" }
    $remoteImportDir = $null
    $sess = $null; $pcTmp = $null
    try {
        if (($env:PSModulePath -split ';') -notcontains $ModulesRoot) { $env:PSModulePath = $ModulesRoot + ';' + $env:PSModulePath }
        Import-Module Posh-SSH -ErrorAction Stop
        $pfx = 'PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:$PATH'
        $sec = ConvertTo-SecureString $SrvPass -AsPlainText -Force
        $cred = [pscredential]::new($SrvUser, $sec)
        $sync.Status = "Connecting to $SrvHost ..."
        $sess = New-SSHSession -ComputerName $SrvHost -Port $SrvPort -Credential $cred -AcceptKey -ErrorAction Stop
        $sync.Client = $sess.Session
        if ($sync.Cancel) { throw 'Stopped.' }

        $rfile = $File
        $cleanup = $false
        if ($Loc -notlike 'Server*') {
            $localFile = $null
            if ($Loc -like 'Local*') {
                if (-not (Test-Path -LiteralPath $File -PathType Leaf)) { throw "Local file not found: $File" }
                $localFile = $File
            }
            elseif ($Loc -like 'Network*') {
                $rootShare = if ($File -match '^(\\\\[^\\]+\\[^\\]+)') { $matches[1] } else { $File }
                if (-not [string]::IsNullOrWhiteSpace($NetUser)) { Invoke-OneLinkNetUse use $rootShare $NetPass "/user:$NetUser" | Out-Null }
                else { Invoke-OneLinkNetUse use $rootShare | Out-Null }
                if (-not (Test-Path -LiteralPath $File -PathType Leaf)) { throw "File not found or share not reachable: $File" }
                $localFile = $File
            }
            elseif ($Loc -like 'Another VM*') {
                $vsec = ConvertTo-SecureString $VmPass -AsPlainText -Force
                $vcred = [pscredential]::new($VmUser, $vsec)
                $pcTmp = Join-Path ([IO.Path]::GetTempPath()) ("olk_" + [Guid]::NewGuid().ToString('N'))
                New-Item -ItemType Directory -Path $pcTmp -Force | Out-Null
                $sync.Status = "Downloading backup from $VmHost (can take a long time) ..."
                Get-SCPItem -ComputerName $VmHost -Port 22 -Credential $vcred -Path $File -PathType File -Destination $pcTmp -AcceptKey -Force -ErrorAction Stop
                $leaf = (($File -split '[\\/]') | Where-Object { $_ -ne '' } | Select-Object -Last 1)
                $localFile = Join-Path $pcTmp $leaf
            }
            if ($sync.Cancel) { throw 'Stopped.' }
            # Make sure the server-side temp dir exists/writable before the upload.
            $remoteImportDir = "$UploadDir/olk_restore_$JobId"
            $prep = Invoke-SSHCommand -SSHSession $sess -Command ('umask 077; mkdir -- ' + (q $remoteImportDir)) -TimeOut 30
            if ($prep.ExitStatus -ne 0) { throw 'Could not create the restore staging directory.' }
            $sync.Status = "Uploading backup to $SrvHost (can take a long time) ..."
            Set-SCPItem -ComputerName $SrvHost -Port $SrvPort -Credential $cred -Path $localFile -Destination $remoteImportDir -AcceptKey -ErrorAction Stop
            $rfile = "$remoteImportDir/" + [IO.Path]::GetFileName($localFile)
            $cleanup = $true
            if ($sync.Cancel) { throw 'Stopped.' }
        }
        $sync.Status = "Restoring '$Db' on $SrvHost (large DBs can take a long time) ..."
            $databaseCommand = New-OneLinkDatabaseImportCommand -DatabaseName $Db -FilePath $rfile
            $r = Invoke-SSHCommand -SSHSession $sess -Command (New-OneLinkDatabaseJobCommand -Command $databaseCommand -JobId $JobId) -TimeOut $Timeout
            if ($r.ExitStatus -ne 0) { throw ("Database command failed (exit {0}). {1}" -f $r.ExitStatus, ((@($r.Output) + @($r.Error)) -join " ")) }
        if ($sync.Cancel) { throw 'Stopped.' }
        if ($cleanup) { Invoke-SSHCommand -SSHSession $sess -Command ("rm -f -- " + (q $rfile) + "; rmdir -- " + (q $remoteImportDir)) -TimeOut 30 | Out-Null }
        $sync.Ok = $true; $sync.Message = "Imported into '$Db' on $SrvHost."
    }
    catch {
        if ($sync.Cancel) { $sync.Ok = $false; $sync.Message = 'Stopped by user.' }
        else { $sync.Ok = $false; $sync.Message = $_.Exception.Message }
    }
    finally {
        try { if ($sess) { Remove-SSHSession -SSHSession $sess -ErrorAction SilentlyContinue | Out-Null } } catch { }
        if ($pcTmp) {
            $resolved = [IO.Path]::GetFullPath($pcTmp)
            $tempRoot = [IO.Path]::GetFullPath([IO.Path]::GetTempPath()).TrimEnd('\') + '\'
            if ($resolved.StartsWith($tempRoot, [StringComparison]::OrdinalIgnoreCase) -and [IO.Path]::GetFileName($resolved) -match '^olk_[a-f0-9]{32}$') { Remove-Item -LiteralPath $resolved -Recurse -Force -ErrorAction SilentlyContinue }
        }
        $sync.Done = $true
    }
}

